gfx rock_on 0
gfx mottle_on 0
tick 60
smoothmove 1
tick 1
tickalpha 0
shot shots/g222_warm.png
tick 1
tickalpha 0
shot shots/g222_sea_tick.png
tickalpha 0.5
shot shots/g222_sea_sub.png
cam 32 32
tick 1
tickalpha 0
shot shots/g222_warm2.png
tick 1
tickalpha 0
shot shots/g222_land_tick.png
tickalpha 0.5
shot shots/g222_land_sub.png
quit
G222EOF
