EOS
sed 's/g244_SHOT/g244_cla_rep/' gate_wrenchlit.txt > gate_wrenchlit_cla_rep.txt
sed 's/g244_SHOT/g244_enh_rep/' gate_wrenchlit.txt > gate_wrenchlit_enh_rep.txt
