grun -                  --scen SCG02EA --pack SCG02EA.pack $WLB --enhanced --noecur --script gate_wrenchlit_noe_ctrl.txt
gshots shots/g244_proc.png shots/g244_cla_rep.png shots/g244_cla_ctrl.png shots/g244_enh_rep.png \
       shots/g244_enh_rep2.png shots/g244_enh_ctrl.png shots/g244_noe_rep.png shots/g244_noe_ctrl.png
# Ten fields, every one a value that FAILS its own leg, so a run that could not be
# measured cannot report a pass: top base ay foot anchorbad | sil covered spread same lit,
# then the remastered wrench's three: its pixel share, its offset, its share off --noecur
WL="0 0 0 9 1 0 0 9 0 unmeasured 0 99 0"
if [ "$GRC" = "0" ]; then
WL=$(python3 - <<'PY'
import re
import numpy as np
from PIL import Image

# ---- leg A: the numbers the lift was chosen from, off the last wrenchdump ----
log = open('shots/g244_proc.log').read()
blocks = log.split('WRENCHDUMP-BEGIN')[1:]
top = base = ay = 0.0
foot = 9.0
anchorbad = 1
if blocks:
    b = blocks[-1].split('WRENCHDUMP-END')[0]
    q = re.search(r'WRENCHQUAD\|PROC\|id=\d+\|dimw=(\d+)\|x0=([-0-9.]+)\|x1=([-0-9.]+)'
                  r'\|y0=([-0-9.]+)\|y1=([-0-9.]+)\|z=[-0-9.]+\|top=([-0-9.]+)\|base=([-0-9.]+)', b)
    d = re.search(r'WRENCH3D\|PROC\|id=\d+\|mesh=\d+\|face=-?\d+\|yawdeg=[-0-9.]+'
                  r'\|ax=([-0-9.]+)\|az=([-0-9.]+)\|ay=([-0-9.]+)', b)
    if q and d:
        top, base = float(q.group(6)), float(q.group(7))
        foot = int(q.group(1)) / 24.0 * 0.5
        ay = float(d.group(3))
        # the quad is centred on the lift; the 3D anchor must stand on the same point
        qx = (float(q.group(2)) + float(q.group(3))) * 0.5
        qy = (float(q.group(4)) + float(q.group(5))) * 0.5
        anchorbad = 0 if (abs(float(d.group(1)) - qx) < 0.001 and abs(ay - qy) < 0.001) else 1

# ---- leg B: the wrench's own pixels, Classic against Enhanced ----
def load(p):
    return np.asarray(Image.open('shots/' + p).convert('RGB')).astype(int)
cr, cc, dr, dc, dr2, er, ec = [load(p) for p in ('g244_cla_rep.png', 'g244_cla_ctrl.png',
                                                  'g244_enh_rep.png', 'g244_enh_ctrl.png',
                                                  'g244_enh_rep2.png', 'g244_noe_rep.png',
                                                  'g244_noe_ctrl.png')]
same = 1 if np.array_equal(dr, dr2) else 0
win = np.zeros(cr.shape[:2], bool)
win[320:420, 660:780] = True                    # the barracks, cam 55 51 at 1280x720
chg = lambda a, b: (np.abs(a - b).sum(axis=2) > 24) & win
sil = chg(cr, cc)    # the slab: depth-free, so exactly its pixels
esil = chg(er, ec)   # the same cartridge model through the Enhanced chain (--noecur)
nsil = int(sil.sum())
covered = int((esil & sil).sum()) / float(nsil) if nsil else 0.0
# the shipped picture: the remastered wrench, against its own control
rsil = chg(dr, dc)
rshare = int(rsil.sum()) / float(nsil) if nsil else 0.0
roff = 99.0
if nsil and rsil.sum():
    sy, sx = np.nonzero(sil)
    ry, rx = np.nonzero(rsil)
    roff = float(np.hypot(rx.mean() - sx.mean(), ry.mean() - sy.mean()))
both = rsil | esil
roffcart = int((chg(dr, er) & both).sum()) / float(both.sum()) if both.sum() else 0.0
lum = lambda im: 0.299 * im[..., 0] + 0.587 * im[..., 1] + 0.114 * im[..., 2]
lc, le = lum(cr), lum(er)
spread = 9.0
ratios = []
if nsil >= 100:
    ys = np.nonzero(sil)[0]
    y0, y1 = ys.min(), ys.max()
    h = (y1 - y0 + 1) / 3.0
    for k in range(3):
        a, b = int(y0 + k * h), int(y0 + (k + 1) * h)
        m = sil.copy(); m[:a, :] = False; m[b:, :] = False
        if m.sum() and lc[m].mean() > 0:
            ratios.append(le[m].mean() / lc[m].mean())
    if len(ratios) == 3:
        spread = max(ratios) - min(ratios)
print('%.4f %.4f %.4f %.4f %d %d %.3f %.3f %d %s %.3f %.1f %.3f' % (
    top, base, ay, foot, anchorbad, nsil, covered, spread, same,
    ','.join('%.3f' % r for r in ratios) or 'unmeasured', rshare, roff, roffcart))
PY
)
fi
set -- $WL
WL_TOP=$1; WL_BASE=$2; WL_AY=$3; WL_FOOT=$4; WL_ANCHORBAD=$5
WL_SIL=$6; WL_COVERED=$7; WL_SPREAD=$8; WL_SAME=$9; shift 9; WL_RATIOS=${1:-unmeasured}
WL_RSHARE=${2:-0}; WL_ROFF=${3:-99}; WL_RCART=${4:-0}
WL_REMOK=$(python3 -c "print(1 if $WL_RSHARE >= 0.6 and $WL_ROFF <= 8.0 and $WL_RCART >= 0.5 else 0)")
WL_ROOF=$(python3 -c "print('%.4f' % ($WL_TOP + $WL_BASE + 0.10 - 0.001))")
WL_TOPOK=$(python3 -c "print(1 if 1.0 <= $WL_TOP <= 1.2 else 0)")
WL_BASEOK=$(python3 -c "print(1 if 0.09 <= $WL_BASE <= 0.11 else 0)")
WL_LIFTOK=$(python3 -c "print(1 if $WL_AY >= $WL_ROOF else 0)")
WL_WONOK=$(python3 -c "print(1 if $WL_AY > $WL_FOOT + 0.001 else 0)")
WL_SPREADOK=$(python3 -c "print(1 if $WL_SPREAD < 0.15 else 0)")
WL_COVOK=$(python3 -c "print(1 if $WL_COVERED >= 0.9 else 0)")
if [ "$GRC" != "0" ]; then
  bad "G244 the repair wrench floats over the roof and is lit as itself: a run failed (exit $GRC), so nothing below was measured"
elif [ "$WL_TOPOK" != "1" ]; then
  bad "G244 the repair wrench floats over the roof: wrenchdump read the Refinery's roof as top=$WL_TOP cell, wanted 1.0..1.2 (the tower). 1.35 is the smokestack tip (a highest-vertex rule), 0.90 the percentile fallback, 0.58 the lower deck, 0 a build that prints no top= at all"
elif [ "$WL_BASEOK" != "1" ]; then
  bad "G244 the repair wrench floats over the roof: the slab's underside is base=$WL_BASE cell above its anchor, wanted 0.09..0.11 (mesh y 101 of CUR05). The lift rule adds this number, so a wrong reading puts the slab in the wrong place"
elif [ "$WL_LIFTOK" != "1" ]; then
  bad "G244 the repair wrench floats over the roof: the draw lifted the wrench to ay=$WL_AY, below the roof rule's $WL_ROOF (top $WL_TOP + base $WL_BASE + 0.10 clearance). The slab is inside the Refinery's tower again"
elif [ "$WL_WONOK" != "1" ]; then
  bad "G244 the repair wrench floats over the roof: ay=$WL_AY does not exceed the footprint rule's $WL_FOOT, so the roof rule did not win on the one building this gate chose because it must"
elif [ "$WL_ANCHORBAD" != "0" ]; then
  bad "G244 the repair wrench floats over the roof: the 3D anchor draw_mesh reported and the collector's quad centre disagree on the Refinery. The lift moved one and not the other"
elif [ "${WL_SIL:-0}" -lt 500 ]; then
  bad "G244 the repair wrench is lit as itself: only $WL_SIL pixels changed between the repairing and non-repairing Classic frames inside the barracks window, wanted at least 500. The wrench is not on screen where this gate looks"
elif [ "$WL_SAME" != "1" ]; then
  bad "G244 the repair wrench is lit as itself: two Enhanced runs of the same repairing tick differ. Nondeterministic pixels make the luminance leg below meaningless"
elif [ "$WL_COVOK" != "1" ]; then
  bad "G244 the repair wrench is lit as itself: the Enhanced repairing frame (--noecur, the cartridge model) changed only $WL_COVERED of the wrench's silhouette against its own control, wanted 0.9. The wrench is not drawn under the Enhanced chain"
elif [ "$WL_REMOK" != "1" ]; then
  bad "G244 the remastered wrench: the default Enhanced repairing frame changed $WL_RSHARE of the Classic silhouette's pixel count (want >= 0.6), centred $WL_ROFF px from it (want <= 8), and differs from the --noecur frame over $WL_RCART of the two wrenches (want >= 0.5). The remastered wrench is not what Enhanced draws over a repairing building, or not where the slab is"
elif [ "$WL_SPREADOK" != "1" ]; then
  bad "G244 the repair wrench is lit as itself: across the three bands of the wrench the Enhanced (--noecur)/Classic luminance ratios are $WL_RATIOS, a spread of $WL_SPREAD (want < 0.15). The Enhanced chain is shading the wrench with the roof behind it, which is the wrench drawn without its own depth"
else
  ok "G244 the repair wrench floats over the roof and is lit as itself: Refinery roof read as $WL_TOP, slab base $WL_BASE, wrench lifted to $WL_AY (roof rule $WL_ROOF, footprint rule $WL_FOOT), anchor on the quad; barracks wrench $WL_SIL px, Enhanced (--noecur)/Classic band ratios $WL_RATIOS spread $WL_SPREAD, $WL_COVERED of the silhouette changed in Enhanced; the remastered wrench $WL_RSHARE of its pixels, $WL_ROFF px off centre, $WL_RCART off the cartridge's; two Enhanced runs identical"
fi

# G245 THE TANK SHELL LIES ALONG ITS FLIGHT UNDER ENHANCED AND STANDS ON END IN CLASSIC.
# The 120MM bullet mesh is authored as an upright 24 x 77 x 20 box, and the cartridge's
# bullet draw (RAM 0x801D6418) only ever yaws it, so on the console the tank shell is a
# vertical pillar in every flight direction; the grenade is the same pillar (model-table
# slots 92 and 96 share one scene node). Classic keeps that. Under the Enhanced picture
# the shell is laid along its direction of travel, a deliberate departure, and the
# grenade stays upright on both. Three runs on SCG90EA, a Medium Tank force-firing due
# west (face=194) and due north (face=0), the shell caught two to three cells out with
# nothing between it and the camera:
#   (a) the READOUT: EFXDUMP|BULLET carries flat=0 in Classic and flat=1 under Enhanced
#       for the 120mm round, and EFXDUMP|BULLETSCR projects the middle of the drawn box.
#   (b) the PICTURE, west: the bright box on the flight line (gate_shell.py, threshold
#       120 in a 17 px window about the projected centre) is TALLER than wide in Classic
#       (3 x 6 measured at 1280x720 with the camera on the height of its own cell, 3 x 5
#       with it on the ground averaged round that cell) and WIDER than tall under
#       Enhanced (7 x 3, and 5 x 2). The threshold is 120, not the script's default
#       150: with the averaged camera the laid shell's upper face reads 115 and its side
#       144 to 162, so 150 cut it to 3 x 2 though it is drawn 6 x 2; the grass in the
#       window never passes 79 in any of the three frames.
#   (c) the PICTURE, north: laid along the view direction the box foreshortens to no
#       more than 8 px tall and 4 px wide (2 x 5 measured), which is what a shell pointing
#       along its travel looks like from behind.
#   (d) CENTRING AND LIFT: in all three frames the bright box's centre lands within 2.5 px
#       of the projected centre (0.4..0.6 px measured), so the laid shell neither trails
#       nor leads its lepton coordinate and sits on its lift rather than in the ground.
# Why a broken build cannot pass: a shell drawn upright under Enhanced fails (b) and the
# flat=1 readout (the shipped binary before this measured 2 x 6 there); a lay-flat matrix
# with the wrong centring fails (d); a build without the readout fails (a) and has no
# centre to measure from; a build that draws no shell prints a zero box and fails every
# comparison.
sed 's#shots/shell_x.png#shots/g_shell_wc.png#' "$GATEDIR/gate_shell_w.txt" > /tmp/gshell_wc.txt
sed 's#shots/shell_x.png#shots/g_shell_we.png#' "$GATEDIR/gate_shell_w.txt" > /tmp/gshell_we.txt
sed 's#shots/shell_x.png#shots/g_shell_ne.png#' "$GATEDIR/gate_shell_n.txt" > /tmp/gshell_ne.txt
# THE GROUND DETAIL, PINNED OFF: a grass clump or a rock on the flight line clips the
# shell's box ("nothing between it and the camera" is this gate's premise).
# AND THE TEMPORAL ANTI-ALIASING (aa_mode): it blends the shell, a box two pixels wide,
# with the frames before it, so the bright box flying north thins to 1 x 1 against 2 x 5
# without it. The box sizes and the threshold above were measured without it.
for g245f in /tmp/gshell_wc.txt /tmp/gshell_we.txt /tmp/gshell_ne.txt; do
  { printf 'gfx fol_on 0\ngfx rock_on 0\ngfx mottle_on 0\ngfx aa_mode 0\n'; cat "$g245f"; } > "$g245f.pin" && mv "$g245f.pin" "$g245f"
done
gbegin shots/g_shell_wc.png shots/g_shell_we.png shots/g_shell_ne.png \
       shots/g_shell_wc.log shots/g_shell_we.log shots/g_shell_ne.log
grun shots/g_shell_wc.log --scen SCG90EA --pack SCG01EA.pack $BASE --noshroud --w 1280 --h 720 --script /tmp/gshell_wc.txt
grun shots/g_shell_we.log --scen SCG90EA --pack SCG01EA.pack $BASE --noshroud --w 1280 --h 720 --enhanced --script /tmp/gshell_we.txt
grun shots/g_shell_ne.log --scen SCG90EA --pack SCG01EA.pack $BASE --noshroud --w 1280 --h 720 --enhanced --script /tmp/gshell_ne.txt
gshots shots/g_shell_wc.png shots/g_shell_we.png shots/g_shell_ne.png
# The readouts: one BULLET line and one BULLETSCR line per run, the rule and the pixel.
SHWC=$(grep -c '^EFXDUMP|BULLET|120mm|id=0|cell=55.8,52.2|face=194|alt=0|invis=0|flat=0$' shots/g_shell_wc.log)
SHWE=$(grep -c '^EFXDUMP|BULLET|120mm|id=0|cell=55.8,52.2|face=194|alt=0|invis=0|flat=1$' shots/g_shell_we.log)
SHNE=$(grep -c '^EFXDUMP|BULLET|120mm|id=0|cell=58.5,50.0|face=0|alt=0|invis=0|flat=1$' shots/g_shell_ne.log)
SHWCS=$(sed -n 's/^EFXDUMP|BULLETSCR|120mm|id=0|scr=\([0-9.]*\),\([0-9.]*\)|flat=0$/\1 \2/p' shots/g_shell_wc.log | head -1)
SHWES=$(sed -n 's/^EFXDUMP|BULLETSCR|120mm|id=0|scr=\([0-9.]*\),\([0-9.]*\)|flat=1$/\1 \2/p' shots/g_shell_we.log | head -1)
SHNES=$(sed -n 's/^EFXDUMP|BULLETSCR|120mm|id=0|scr=\([0-9.]*\),\([0-9.]*\)|flat=1$/\1 \2/p' shots/g_shell_ne.log | head -1)
# The radius of eight contains the largest expected shell plus the 2.5 px centring
# allowance, while excluding an unrelated bright structure pixel nine rows away.
# Geometry thresholds and the centring assertion remain unchanged.
# The pictures, measured about the projected centre. A run without the readout has no
# centre to measure about, and its box is reported as 0 x 0 rather than measured at some
# corner of the frame where the sidebar would be counted instead.
if [ -n "$SHWCS" ]; then set -- $(python3 "$GATEDIR/gate_shell.py" shots/g_shell_wc.png $SHWCS 8 120); else set -- 0 0 0 0 0; fi
SHWCW=$1; SHWCH=$2; SHWCX=$3; SHWCY=$4
if [ -n "$SHWES" ]; then set -- $(python3 "$GATEDIR/gate_shell.py" shots/g_shell_we.png $SHWES 8 120); else set -- 0 0 0 0 0; fi
SHWEW=$1; SHWEH=$2; SHWEX=$3; SHWEY=$4
if [ -n "$SHNES" ]; then set -- $(python3 "$GATEDIR/gate_shell.py" shots/g_shell_ne.png $SHNES 8 120); else set -- 0 0 0 0 0; fi
SHNEW=$1; SHNEH=$2; SHNEX=$3; SHNEY=$4
# centre error, worst axis, over the three frames; 99 when a readout or a box is missing
SHERR=$(python3 -c "
w=[('$SHWCS','$SHWCX','$SHWCY'),('$SHWES','$SHWEX','$SHWEY'),('$SHNES','$SHNEX','$SHNEY')]
e=0.0
for s,x,y in w:
    if not s or (x in ('','0') and y in ('','0')): e=99.0; continue
    px,py=(float(v) for v in s.split())
    e=max(e,abs(px-float(x)),abs(py-float(y)))
print('%.1f'%e)")
SHOK=$(python3 -c "print(1 if float('$SHERR') <= 2.5 else 0)")
if [ "$GRC" != "0" ]; then
  bad "G245 tank shell: a run failed or wrote no shot (GRC=$GRC)"
elif [ "$SHWC" = "1" ] && [ "$SHWE" = "1" ] && [ "$SHNE" = "1" ] \
   && [ "${SHWCW:-0}" -ge 2 ] && [ "${SHWCH:-0}" -ge 4 ] && [ "$SHWCW" -lt "$SHWCH" ] \
   && [ "${SHWEW:-0}" -ge 5 ] && [ "$SHWEW" -gt "$SHWEH" ] \
   && [ "${SHNEH:-0}" -ge 3 ] && [ "$SHNEH" -le 8 ] && [ "${SHNEW:-0}" -le 4 ] \
   && [ "$SHOK" = "1" ]; then
  ok "G245 tank shell: Classic draws the console's upright box (${SHWCW}x${SHWCH} px, flat=0) and Enhanced lays it along its flight (west ${SHWEW}x${SHWEH} px, north ${SHNEW}x${SHNEH} px, flat=1), face=194 west and 0 north, every box centred within $SHERR px of its projected centre"
else
  bad "G245 tank shell: readouts classic-west=$SHWC enhanced-west=$SHWE enhanced-north=$SHNE (want 1 each), boxes classic-west=${SHWCW}x${SHWCH}(want taller than wide) enhanced-west=${SHWEW}x${SHWEH}(want wider than tall, >=5 wide) enhanced-north=${SHNEW}x${SHNEH}(want <=4 x <=8), worst centre error ${SHERR}px(want <=2.5)"
fi

# G246 THE ROCKET LAUNCHER POINTS WHERE ITS ROCKETS GO IN BOTH 3D LOOKS, N64 AND ENHANCED,
# AND THE FLAT CLASSIC VIEW IS LEFT TO THE 1995 SPRITE. The GDI rocket launcher (INI MSAM)
# is turret equipped in the engine but its cartridge model is one rigid node, and the
# console draws the whole model at PrimaryFacing while the homing DRAGON round leaves along
# SecondaryFacing from the unit's centre. The body is turned only in TarComClass::AI's
# FIRE_FACING arm, which is unreachable while the launcher is rearming, so a retarget
# inside the 83-tick reload swings the turret alone and the next volley leaves out of the
# flank of a body that never moved. In the N64 and Enhanced looks draw_facing hands the
# launcher its turret facing instead (launcher_follows_turret), a declared deviation from
# the console in the N64 look. Classic draws the engine's own 1995 sprite, which already
# picks its frame by the turret, so the renderer's facing is not handed to it. Same
# scenario, same script, three looks, and the SIM must be identical in all three: this is
# a renderer-only change and the readouts prove it.
#
# THE REPRO is the reload gate. SCG90EA with unit 003 swapped for a launcher at 57,50
# facing north. Force-fire east at 61,50: the body turns 0->63 (FIRE_FACING, the turret
# was 64 off), both rockets leave east (tick 33, 42). At tick 60, inside the reload,
# force-fire north at 57,46: the turret swings 63->0 at 6/tick over 13 ticks while the
# body stays at 63, and the next pair leaves at tick 125 and 134, due north (face=0) from
# 57.5,50.3, the unit's own centre. All three runs must print the same engine state at
# every sample or the gate is measuring different games.
#
# Assertions, all needed:
#   (a) ENGINE, every look: face=63 tface=63 before the retarget; face=63 tface=0 after
#       the swing and at the launch; the launch line EFXDUMP|BULLET|DRAGON|id=0|
#       cell=57.5,50.3|face=0. The body did NOT turn and the rocket is going north.
#   (b) YAW, N64 and Enhanced alike: 191 ((63+128)&255) before the swing, 128
#       ((0+128)&255) at the launch, and the 13-tick swing is CONTINUOUS: 14 samples, no
#       |jump| above 6 (the turret's own ROT+1 step), so the swap cannot snap the hull
#       the way the old stillness latch snapped the harvester. The two looks' yaw
#       sequences are equal sample for sample.
#   (c) YAW, Classic: every sample stays the body's 191, which proves the swap is not
#       handed to the flat view (its picture is the engine's sprite, not this yaw).
#   (d) PIXELS: the launcher's own sand pixels in a box around it (cam 57 50 at zoom max
#       puts it at about 685,386; the box keeps the medium tank to its west and the smoke
#       column out). Their spread is taller than wide when it points north. Measured:
#       N64 w=32 h=53 and Enhanced w=33 h=59. The build before the N64 swap measures
#       w=64 h=35 in N64 (the launcher lying east-west, rockets out of its flank) and
#       fails (b) with yaw 191 in all 17 N64 samples.
#
# The Enhanced run passes --noevhc: this gate is about the cartridge's one-node model.
# The remastered launcher has its launcher as a turret piece, so its hull stays at
# PrimaryFacing (east-west here) while the launcher alone turns north, as any remastered
# turret does (G296).
GML=$(mktemp -d "${TMPDIR:-/tmp}/gate_mlrs.XXXXXX")
cp missions/*.INI missions/*.BIN "$GML"/
sed -i.bak 's/^003=GoodGuy,MTNK,256,3257,0,Guard,None/003=GoodGuy,MSAM,256,3257,0,Guard,None/' "$GML/SCG90EA.INI"
GMLSWAP=$(grep -c '^003=GoodGuy,MSAM,256,3257,0,Guard,None' "$GML/SCG90EA.INI")
for look in n64 enh classic; do
GMLMODE=""; [ "$look" = "classic" ] && GMLMODE="gfxmode 0"
cat > "/tmp/g246_$look.txt" <<EOS
tick 5
$GMLMODE
cam 57 50
zoom max
lclickobj MSAM 0
tick 1
order 61 50 c
tick 60
aimwatch MSAM 0 0
efxdump
order 57 46 c
aimwatch MSAM 0 13
tick 52
aimwatch MSAM 0 0
efxdump
deselect
tick 3
aimwatch MSAM 0 0
efxdump
shot shots/g246_$look.png
quit
EOS
done
gbegin shots/g246_n64.png shots/g246_enh.png shots/g246_classic.png \
       shots/g246_n64.log shots/g246_enh.log shots/g246_classic.log
grun shots/g246_n64.log --scen SCG90EA --pack SCG01EA.pack $BASE --dir "$GML/" --noshroud \
     --w 1280 --h 720 --script /tmp/g246_n64.txt
grun shots/g246_enh.log --scen SCG90EA --pack SCG01EA.pack $BASE --dir "$GML/" --noshroud \
     --w 1280 --h 720 --enhanced --noevhc --script /tmp/g246_enh.txt
grun shots/g246_classic.log --scen SCG90EA --pack SCG01EA.pack $BASE --dir "$GML/" --noshroud \
     --w 1280 --h 720 --script /tmp/g246_classic.txt
gshots shots/g246_n64.png shots/g246_enh.png shots/g246_classic.png
rm -rf "$GML"
# (a) the engine, read out of each log and required to agree between the looks
gml_engine() {
  grep -E '^AIMWATCH\|MSAM#0\|t=[0-9]+\|' "$1" | sed 's/|still=[0-9]*|isstill=[0-9]|yaw=[0-9]*|jump=[-+0-9]*|/|/' | tr '\n' ' '
}
GMLEN=$(gml_engine shots/g246_n64.log)
GMLEE=$(gml_engine shots/g246_enh.log)
GMLEC=$(gml_engine shots/g246_classic.log)
GMLSAME=0; [ -n "$GMLEN" ] && [ "$GMLEN" = "$GMLEE" ] && [ "$GMLEN" = "$GMLEC" ] && GMLSAME=1
GMLPRE=$(grep -c '^AIMWATCH|MSAM#0|t=0|lx=14720|ly=12928|face=63|tface=63|' shots/g246_n64.log)
GMLPOST=$(grep -c '^AIMWATCH|MSAM#0|t=0|lx=14720|ly=12928|face=63|tface=0|' shots/g246_n64.log)
GMLLAUNCH=0
for l in n64 enh classic; do
  grep -q '^EFXDUMP|BULLET|DRAGON|id=0|cell=57.5,50.3|face=0|' "shots/g246_$l.log" && GMLLAUNCH=$((GMLLAUNCH+1))
done
# (b) N64 and Enhanced: the yaw follows the turret, continuously, the same in both
gml_yaws() { grep -E '^AIMWATCH\|MSAM#0\|t=[0-9]+\|' "$1" | sed -n 's/.*|yaw=\([0-9]*\)|.*/\1/p' | tr '\n' ' '; }
GMLYN=$(gml_yaws shots/g246_n64.log)
GMLYE=$(gml_yaws shots/g246_enh.log)
GMLYSAME=0; [ -n "$GMLYN" ] && [ "$GMLYN" = "$GMLYE" ] && GMLYSAME=1
gml_follow() {
  local P A J S
  P=$(grep -c '^AIMWATCH|MSAM#0|t=0|lx=14720|ly=12928|face=63|tface=63|still=70|isstill=1|yaw=191|' "$1")
  A=$(grep -c '^AIMWATCH|MSAM#0|t=0|lx=14720|ly=12928|face=63|tface=0|still=13[58]|isstill=1|yaw=128|' "$1")
  J=$(grep -E '^AIMWATCH\|MSAM#0\|t=[0-9]+\|' "$1" | sed -n 's/.*|jump=\([-+0-9]*\)|.*/\1/p' | tr -d '+' | sort -n | awk 'NR==1{lo=$1} {hi=$1} END{m=-lo; if (hi>m) m=hi; print m+0}')
  S=$(grep -c '^AIMWATCH|MSAM#0|t=1[0-3]|' "$1")
  echo "$P $A ${J:-99} $S"
}
set -- $(gml_follow shots/g246_n64.log)
GMLNPRE="$1"; GMLNAT="$2"; GMLNJUMP="$3"; GMLNSW="$4"
set -- $(gml_follow shots/g246_enh.log)
GMLEPRE="$1"; GMLEAT="$2"; GMLEJUMP="$3"; GMLESW="$4"
# (c) Classic: the flat view is not handed the swap
GMLCYAW=$(grep -E '^AIMWATCH\|MSAM#0\|t=[0-9]+\|' shots/g246_classic.log | grep -c '|yaw=191|')
GMLCN=$(grep -cE '^AIMWATCH\|MSAM#0\|t=[0-9]+\|' shots/g246_classic.log)
# (d) the pixels
GMLPIX=$(python3 - <<'PY'
from PIL import Image
import numpy as np
out = []
for p in ('shots/g246_n64.png', 'shots/g246_enh.png'):
    a = np.asarray(Image.open(p).convert('RGB')).astype(int)
    box = a[320:450, 632:770]
    r, g, b = box[:, :, 0], box[:, :, 1], box[:, :, 2]
    sand = (r > g) & (g > b) & (r >= 110) & (r - b >= 45)
    ys, xs = np.nonzero(sand)
    if len(xs) < 400:
        out += [len(xs), 0, 0]
        continue
    w = int(np.percentile(xs, 97) - np.percentile(xs, 3))
    h = int(np.percentile(ys, 97) - np.percentile(ys, 3))
    out += [len(xs), w, h]
print(' '.join(str(v) for v in out))
PY
)
set -- $GMLPIX
GMLNS="${1:-0}"; GMLNW="${2:-0}"; GMLNH="${3:-0}"; GMLES="${4:-0}"; GMLEW="${5:-0}"; GMLEH="${6:-0}"
if [ "$GRC" != "0" ]; then
  bad "G246 rocket launcher: a run failed or wrote no shot (GRC=$GRC)"
elif [ "$GMLSWAP" != "1" ] || [ "$GMLSAME" != "1" ] || [ "$GMLPRE" -lt 2 ] || [ "$GMLPOST" -lt 2 ] \
   || [ "$GMLLAUNCH" != "3" ]; then
  bad "G246 rocket launcher, the engine half: launcher-in-scenario=$GMLSWAP(want 1) same-sim-three-looks=$GMLSAME(want 1) face63-tface63-samples=$GMLPRE(want >=2) face63-tface0-samples=$GMLPOST(want >=2) north-launch-from-centre=$GMLLAUNCH of 3 looks"
elif [ "$GMLNPRE" -lt 1 ] || [ "$GMLNAT" -lt 2 ] || [ "$GMLNSW" != "4" ] || [ "$GMLNJUMP" -gt 6 ]; then
  bad "G246 rocket launcher, N64: yaw191-before=$GMLNPRE(want >=1) yaw128-at-launch=$GMLNAT(want >=2) swing-samples=$GMLNSW(want 4) largest-jump=$GMLNJUMP(want <=6); the console's own pose (yaw 191 throughout) is what an N64 build without the swap draws"
elif [ "$GMLEPRE" -lt 1 ] || [ "$GMLEAT" -lt 2 ] || [ "$GMLESW" != "4" ] || [ "$GMLEJUMP" -gt 6 ]; then
  bad "G246 rocket launcher, Enhanced: yaw191-before=$GMLEPRE(want >=1) yaw128-at-launch=$GMLEAT(want >=2) swing-samples=$GMLESW(want 4) largest-jump=$GMLEJUMP(want <=6)"
elif [ "$GMLYSAME" != "1" ]; then
  bad "G246 rocket launcher: the N64 and Enhanced yaws differ (N64: $GMLYN / Enhanced: $GMLYE)"
elif [ "$GMLCN" -lt 17 ] || [ "$GMLCYAW" != "$GMLCN" ]; then
  bad "G246 rocket launcher, Classic: $GMLCYAW of $GMLCN sampled yaws are the body's 191 (want all of >=17: the flat view is not handed the swap)"
elif [ "$GMLNS" -lt 400 ] || [ "$GMLES" -lt 400 ] || [ "$GMLNH" -le "$GMLNW" ] || [ "$GMLEH" -le "$GMLEW" ]; then
  bad "G246 rocket launcher, the pixels: n64 sand=$GMLNS w=$GMLNW h=$GMLNH, enhanced sand=$GMLES w=$GMLEW h=$GMLEH (want h>w in both, pointing north)"
else
  ok "G246 rocket launcher: same sim in N64, Enhanced and Classic (face 63, turret 63->0 in 13 ticks, volley north from 57.5,50.3); N64 and Enhanced both follow the turret 191->128 with no jump over $GMLNJUMP and land at 128 at the launch, sample for sample alike; Classic's flat view keeps the body's 191 in all $GMLCN samples; launcher ${GMLNW}x${GMLNH} px north in N64, ${GMLEW}x${GMLEH} px north in Enhanced"
fi

# G247 THE TEXTURE BOOKS SIT ON THEIR BUILDINGS. G68 reads the slot the silo picks; this
# gate reads the PICTURE, and it exists because G68 stayed green for a whole release over a
# fill dome nobody could see. bake_struct_flipbooks baked every book variant from the
# payload list's raw vertices, without the book node's mount transform, while the base
# mesh carried the same geometry posed (through the walker's node+0x04 fallback). Two of
# the six books hang off a posed node: the silo's dome variant sat 10.93 units inside the
# building's own dome, so a full silo looked exactly like an empty one, and the refinery's
# storage strip stood 0.28 cells east of the strip on the building, so the refinery wore
# two columns and only the loose one filled. Three legs:
#   a  texbookdump: every book variant's triangles are on the base mesh (onbase == tris)
#      in whatever pack is loaded, so a pack baked by the older baker is named here;
#   b  the Nod silo on SCG32EA (id=88, box 575,320..705,400 at 1280x720): zero
#      bright-green pixels at fill 0, and a measured 904 at fill 40, threshold 400;
#   c  the Test Map refinery while its harvester unloads (stage 21): switching the books
#      off changes pixels inside the corner column 500,260..545,360 (measured 203,
#      threshold 100) and NONE in the box the second column used to fill,
#      540,260..554,350 (was 315).
# PROVEN TO FAIL on the build before the fix: no TEXBOOK readout, 0 green at fill 40, 315
# pixels in the old column's box.
gbegin shots/silofill_0.png shots/silofill_40.png shots/procstrip_on.png shots/procstrip_off.png
grun shots/gtexbook.log --scen SCG32EA --pack SCG32EA.pack $BASE --noshroud --nosound \
    --w 1280 --h 720 --script gate_silofill.txt
gshots shots/silofill_0.png shots/silofill_40.png
TBK_N=$(grep -c '^TEXBOOK|' shots/gtexbook.log)
TBK_OFF=$(awk -F'|' '/^TEXBOOK\|/ { t=$6; b=$7; sub("tris=","",t); sub("onbase=","",b); if (t+0 != b+0) print $2 }' shots/gtexbook.log | tr '\n' ' ')
TBK_S0=$(sed -n 's/^SILOBOOK|id=88|.*|state=\([0-9-]*\)|.*/\1/p' shots/gtexbook.log | head -1)
TBK_S40=$(sed -n 's/^SILOBOOK|id=88|.*|state=\([0-9-]*\)|.*/\1/p' shots/gtexbook.log | tail -1)
TBK_G=$(python3 - shots/silofill_0.png shots/silofill_40.png <<'PY'
import sys
from PIL import Image
out = []
for p in sys.argv[1:3]:
    im = Image.open(p).convert("RGB"); px = im.load()
    n = sum(1 for y in range(320, 400) for x in range(575, 705)
            if px[x, y][1] > 150 and px[x, y][0] < 80 and px[x, y][2] < 80)
    out.append(str(n))
print(" ".join(out))
PY
)
set -- $TBK_G
TBK_G0="${1:-x}"; TBK_G40="${2:-x}"
grun shots/gtexbook.log --scen SCG90EA --pack SCG01EA.pack $BASE --noshroud --nosound \
    --w 1280 --h 720 --script gate_procstrip.txt
[ -s shots/procstrip.png ] && mv shots/procstrip.png shots/procstrip_on.png
TBK_ST=$(sed -n 's/^ANIM|PROC|.*|stage=\([0-9]*\)|.*/\1/p' shots/gtexbook.log | head -1)
grun shots/gtexbook.log --scen SCG90EA --pack SCG01EA.pack $BASE --noshroud --nosound \
    --notexbook --w 1280 --h 720 --script gate_procstrip.txt
[ -s shots/procstrip.png ] && mv shots/procstrip.png shots/procstrip_off.png
gshots shots/procstrip_on.png shots/procstrip_off.png
TBK_D=$(python3 - shots/procstrip_on.png shots/procstrip_off.png <<'PY'
import sys
from PIL import Image
a = Image.open(sys.argv[1]).convert("RGB").load(); b = Image.open(sys.argv[2]).convert("RGB").load()
def box(x0, y0, x1, y1):
    return sum(1 for y in range(y0, y1) for x in range(x0, x1) if a[x, y] != b[x, y])
print("%d %d" % (box(500, 260, 545, 360), box(540, 260, 554, 350)))
PY
)
set -- $TBK_D
TBK_DCOL="${1:-x}"; TBK_DOLD="${2:-x}"
if [ "$GRC" != "0" ]; then
  bad "G247 texture books on their buildings: a run failed or a shot is missing (GRC=$GRC)"
elif [ "${TBK_N:-0}" -lt 6 ] || [ -n "$TBK_OFF" ]; then
  bad "G247 texture books on their buildings: texbookdump lines=$TBK_N(want >=6) books off their base=[$TBK_OFF](want none): the loaded pack was baked without the book node's pose"
elif [ "$TBK_S0" != "0" ] || [ "$TBK_S40" != "40" ] || [ "$TBK_ST" != "21" ]; then
  bad "G247 texture books on their buildings: the scene did not reach the states this gate measures (silo states $TBK_S0/$TBK_S40 want 0/40, refinery stage $TBK_ST want 21)"
elif [ "$TBK_G0" = "0" ] && [ "${TBK_G40:-0}" -ge 400 ] && [ "${TBK_DCOL:-0}" -ge 100 ] && [ "$TBK_DOLD" = "0" ]; then
  ok "G247 texture books on their buildings: all $TBK_N book variants sit on their base meshes, the silo dome shows $TBK_G0 green pixels empty and $TBK_G40 full, and the refinery strip fills $TBK_DCOL pixels of the corner column with $TBK_DOLD in the box its stray copy used to fill"
else
  bad "G247 texture books on their buildings: silo green empty=$TBK_G0(want 0) full=$TBK_G40(want >=400); refinery strip column=$TBK_DCOL(want >=100) old-stray-box=$TBK_DOLD(want 0)"
fi

# G248 THE STRUCTURE ANIMATION CURVES ARE THE CONSOLE'S. Two legs. First the extractor's
# BEEFED02 evaluator is run against the cartridge's own: tools/anim/anim_console_check.py
# loads the resident segment and both model segments into the MIPS interpreter, calls the
# cartridge's curve init and apply for every animated node, and compares the matrix the
# console builds with the one rebuilt from the committed slot JSON at every baked frame
# (tolerance 2e-3; measured worst 6.5e-6). The evaluator before it blended key values with
# slerp and ignored the two control points, which was 178 degrees wrong on the
# Communications Centre's dish and turned its 412-degree pan into a 308-degree pan the
# other way; the check fails on those JSONs by 159 degrees at frame 24. Second, the PACK in
# the run folder: armdump reads the dish's drawn bearing at cartridge frames 24, 48, 72
# and 96 (ticks 48..192), which the console's evaluator puts at -93.6, -176.0, +94.3 and
# +14.1 degrees, with the dish upright (roll < 2) there and at ticks 576 and 768, where the
# authored clip would have it pointing at the sky and upside down; the idle window keeps
# the drawn frame inside 2..102.
# PROVEN TO FAIL: the pre-fix JSONs fail the console check, and the pre-fix renderer has no
# armdump verb and pans the other way (+65 at frame 24).
ACC_LINE=$(python3 "$GATEDIR/../tools/anim/anim_console_check.py" 2>&1 | tee -a "$OUT" | grep '^CONSOLECHECK|nodes=' | tail -1)
ACC_N=$(echo "$ACC_LINE" | sed -n 's/^CONSOLECHECK|nodes=\([0-9]*\)|bad=\([0-9]*\)|.*/\1/p')
ACC_B=$(echo "$ACC_LINE" | sed -n 's/^CONSOLECHECK|nodes=\([0-9]*\)|bad=\([0-9]*\)|.*/\2/p')
gbegin shots/eyedish_f096.png shots/eyedish_f288.png shots/eyedish_f384.png
grun shots/geyedish.log --scen SCB13EA --pack SCB13EA.pack $BASE --noshroud --nosound \
    --nominimap --nosidebar --w 1280 --h 720 --script gate_eyedish.txt
gshots shots/eyedish_f096.png shots/eyedish_f288.png shots/eyedish_f384.png
EYE_RES=$(python3 - shots/geyedish.log <<'PY'
import re, sys
az, roll, fr = [], [], []
for ln in open(sys.argv[1]):
    m = re.match(r"ARMMAT\|EYE\|id=\d+\|frame=([0-9.]+)\|part=1\|az=(-?[0-9.]+)\|el=(-?[0-9.]+)\|roll=(-?[0-9.]+)", ln)
    if m:
        fr.append(float(m.group(1))); az.append(float(m.group(2))); roll.append(float(m.group(4)))
want = [-93.6, -176.0, 94.3, 14.1]
if len(az) < 6:
    print("0 samples=%d" % len(az)); raise SystemExit
def dang(a, b):
    d = (a - b + 180.0) % 360.0 - 180.0
    return abs(d)
okaz = all(dang(a, w) <= 3.0 for a, w in zip(az[:4], want))
okroll = max(roll) < 2.0
okfr = all(2.0 <= f <= 102.0 for f in fr)
print("%d az=%s roll_max=%.1f frames=%s" % (1 if (okaz and okroll and okfr) else 0,
      [round(a, 1) for a in az], max(roll), [round(f, 1) for f in fr]))
PY
)
set -- $EYE_RES
EYE_OK="$1"
if [ "$ACC_N" != "15" ] || [ "$ACC_B" != "0" ]; then
  bad "G248 animation curves: the console check did not pass ($ACC_LINE): the committed slot JSONs are not what the cartridge's evaluator produces"
elif [ "$GRC" != "0" ]; then
  bad "G248 animation curves: the dish run failed or wrote no shot (GRC=$GRC)"
elif [ "$EYE_OK" = "1" ]; then
  ok "G248 animation curves: $ACC_N BEEFED02 nodes match the console's evaluator at every baked frame, and the Communications Centre's dish pans upright on the console's bearings ($EYE_RES)"
else
  bad "G248 animation curves: the dish is not on the console's pan (want az -93.6/-176.0/94.3/14.1 within 3, roll < 2, frames in 2..102) [$EYE_RES]"
fi

# G249. THE EXIT COMES BEFORE THE RALLY, AND THE AIRSTRIP HONOURS IT. Six legs and two
# controls, all on the rally point a factory stores in its ArchiveTarget (G96).
#   A  SCG90EA barracks, rally north at 58,50: the soldier enters the exit cell 58,55
#      before any cell above the pad row, and ends at 58,50. On a build that hands the
#      rally to the soldier at the door point it walks 58,54 then 59,54, through the
#      side of the hut, and never enters 58,55.
#   B  SCB70EA Hand of Nod, rally north at 15,44: the exit cell 16,50 before any cell
#      above row 50 (the spawn cell 15,49 excepted), ending at 15,44.
#   C  SCG90EA barracks, rally behind and left at 55,50: the exit cell first, then along
#      the front of the pad, ending at 55,50. Without the door the line to the rally runs
#      through the occupied corner 57,53.
#   D  SCB70EA airstrip, rally at 9,58: the buggy is in limbo before the drop, then under
#      MISSION_MOVE, and ends at 9,58.
#   E  the same strip and rally, a harvester: never MISSION_MOVE, never at 9,58, ends
#      under MISSION_HARVEST. The strip is Nod's only harvester source.
#   F  SCB70EA helipad: the rally is refused (accepted=0) and the dump names none.
#   A' and B' are A and B with the rally lines taken out: the vanilla exit walk, 58,54
#      58,55 and 15,49 15,50 16,50, and no rally stored anywhere.
# PROVEN TO FAIL on the build before the fix, 3 of 8: A walks 58,54 59,54 59,53 and never
# enters 58,55, B walks 15,49 16,49 17,48, C walks 58,54 57,54 57,53 through the occupied
# corner, D's buggy is scattered to 13,54 and ends there in guard, F stores the helipad
# rally at 20,50; only E and the two controls pass.
gbegin shots/exitpath_a_door.png shots/exitpath_a_end.png shots/exitpath_b_door.png \
       shots/exitpath_c_front.png shots/exitpath_d_drop.png shots/exitpath_d_end.png
grun shots/gexitpath_a.log --scen SCG90EA --pack SCG01EA.pack $BASE --noshroud --nosound \
    --w 1280 --h 720 --script gate_exitpath.txt
# The controls drop the shot lines as well as the rally lines: they run AFTER the rally
# arm and would otherwise overwrite its pictures with their own, and a control soldier
# standing at the exit cell looks exactly like a fixed one at the same tick.
sed '/^[[:space:]]*rally /d; /^[[:space:]]*shot /d' gate_exitpath.txt > /tmp/g249_actl.txt
grun shots/gexitpath_actl.log --scen SCG90EA --pack SCG01EA.pack $BASE --noshroud --nosound \
    --w 1280 --h 720 --script /tmp/g249_actl.txt
grun shots/gexitpath_c.log --scen SCG90EA --pack SCG01EA.pack $BASE --noshroud --nosound \
    --w 1280 --h 720 --script gate_exitpath_nw.txt
grun shots/gexitpath_b.log --scen SCB70EA --pack SCB01EA.pack $BASE --noshroud --nosound \
    --w 1280 --h 720 --script gate_exitpath_hand.txt
sed '/^[[:space:]]*rally /d; /^[[:space:]]*shot /d' gate_exitpath_hand.txt > /tmp/g249_bctl.txt
grun shots/gexitpath_bctl.log --scen SCB70EA --pack SCB01EA.pack $BASE --noshroud --nosound \
    --w 1280 --h 720 --script /tmp/g249_bctl.txt
grun shots/gexitpath_d.log --scen SCB70EA --pack SCB01EA.pack $BASE --noshroud --nosound \
    --w 1280 --h 720 --script gate_exitpath_afld.txt
grun shots/gexitpath_e.log --scen SCB70EA --pack SCB01EA.pack $BASE --noshroud --nosound \
    --w 1280 --h 720 --script gate_exitpath_harv.txt
gshots shots/exitpath_a_door.png shots/exitpath_a_end.png shots/exitpath_b_door.png \
       shots/exitpath_c_front.png shots/exitpath_d_drop.png shots/exitpath_d_end.png
EXP_RES=$(python3 - shots/gexitpath_a.log shots/gexitpath_actl.log shots/gexitpath_c.log \
                    shots/gexitpath_b.log shots/gexitpath_bctl.log shots/gexitpath_d.log \
                    shots/gexitpath_e.log <<'PY'
import re, sys
LIMBO = (127, 127)
def read(path, label):
    text = open(path, errors="replace").read()
    cells, missions = [], []
    # A watch prints the cell it starts in, so the second watch of a script repeats the
    # last cell of the first: consecutive repeats are one cell, not a step.
    for m in re.finditer(r"^WATCH\|%s\|f=\d+\|cell=(\d+),(\d+)\|mission=(\w+)" % re.escape(label), text, re.M):
        cell = (int(m.group(1)), int(m.group(2)))
        if not cells or cells[-1] != cell:
            cells.append(cell)
        missions.append(m.group(3))
    o = re.search(r"^OBJ\|%s\|[A-Z]+\|\w+\|cell=(\d+),(\d+)\|[^|]*\|mission=(\w+)" % re.escape(label), text, re.M)
    obj = ((int(o.group(1)), int(o.group(2))), o.group(3)) if o else (None, None)
    return text, cells, missions, obj
def fmt(cells):
    return ">".join("%d,%d" % c for c in cells) if cells else "none"
def exit_first(cells, exitcell, behind, skip=0):
    walk = [c for c in cells if c != LIMBO]
    if exitcell not in walk:
        return False
    past = [i for i, c in enumerate(walk) if i >= skip and behind(c)]
    return not past or walk.index(exitcell) < past[0]
res, notes = {}, []
# A: barracks north rally.
t, c, m, o = read(sys.argv[1], "E1:GoodGuy#4")
res["A"] = exit_first(c, (58, 55), lambda p: p[1] <= 53) and o[0] == (58, 50)
notes.append("A %s end=%s" % (fmt([x for x in c if x != LIMBO]), o[0]))
# A': the control walks the vanilla exit and stores no rally.
t, c, m, o = read(sys.argv[2], "E1:GoodGuy#4")
res["A'"] = [x for x in c if x != LIMBO] == [(58, 54), (58, 55)] and o[0] == (58, 55) \
            and not re.search(r"^RALLY\|", t, re.M)
notes.append("A' %s" % fmt([x for x in c if x != LIMBO]))
# C: behind-left rally.
t, c, m, o = read(sys.argv[3], "E1:GoodGuy#4")
res["C"] = exit_first(c, (58, 55), lambda p: p[1] <= 53) and o[0] == (55, 50)
notes.append("C %s end=%s" % (fmt([x for x in c if x != LIMBO]), o[0]))
# B: the Hand of Nod. The spawn cell 15,49 is above row 50 and is skipped. F, the
# helipad refusal, is in the same log: the set line says accepted=0 and no dump line
# names a helipad.
t, c, m, o = read(sys.argv[4], "E1:BadGuy#17")
res["B"] = exit_first(c, (16, 50), lambda p: p[1] <= 49, skip=1) and o[0] == (15, 44)
res["F"] = bool(re.search(r"^RALLY\|set\|HPAD\|id=\d+\|cell=20,50\|accepted=0$", t, re.M)) \
           and not re.search(r"^RALLY\|HPAD\|", t, re.M)
notes.append("F %s" % ("refused" if res["F"] else "STORED"))
notes.append("B %s end=%s" % (fmt([x for x in c if x != LIMBO]), o[0]))
t, c, m, o = read(sys.argv[5], "E1:BadGuy#17")
res["B'"] = [x for x in c if x != LIMBO] == [(15, 49), (15, 50), (16, 50)] and o[0] == (16, 50) \
            and not re.search(r"^RALLY\|", t, re.M)
notes.append("B' %s" % fmt([x for x in c if x != LIMBO]))
# D: the airstrip drop, then MISSION_MOVE, then the rally cell.
t, c, m, o = read(sys.argv[6], "BGGY:BadGuy#3")
res["D"] = len(c) >= 2 and c[0] == LIMBO and m[0] == "None" and "Move" in m and o[0] == (9, 58)
notes.append("D %s end=%s/%s" % (fmt(c[:3] + [c[-1]] if len(c) > 4 else c), o[0], o[1]))
# E: the harvester is left to harvest.
t, c, m, o = read(sys.argv[7], "HARV:BadGuy#1")
res["E"] = len(c) >= 2 and c[0] == LIMBO and "Move" not in m and (9, 58) not in c and o[1] == "Harvest"
notes.append("E cells=%d missions=%s end=%s/%s" % (len(c), ",".join(sorted(set(m))), o[0], o[1]))
order = ["A", "A'", "B", "B'", "C", "D", "E", "F"]
print("%d %s | %s" % (sum(1 for k in order if res[k]),
      " ".join("%s=%d" % (k, 1 if res[k] else 0) for k in order), "; ".join(notes)))
PY
)
EXP_N="${EXP_RES%% *}"
if [ "$GRC" != "0" ]; then
  bad "G249 exit before rally: a run failed or a shot is missing (GRC=$GRC)"
elif [ "${EXP_N:-0}" = "8" ]; then
  ok "G249 exit before rally: all eight legs hold [$EXP_RES]"
else
  bad "G249 exit before rally: ${EXP_N:-0} of 8 legs hold (want A B C D E F and the two controls all 1) [$EXP_RES]"
fi

# G253 walks the 1995 menu to its mission starts (menu1995_on, at the top).
menu1995_on
# G253 A MISSION THAT CANNOT START SAYS WHY. A report that every mission start closed the
# game after the mission briefing movie could not be worked, because a refused or crashed start
# left nothing behind: the window vanished, or the menu came back untouched with one line
# on stderr. Two shapes reproduce on the build before this gate and both are closed here.
#
#   a  THE THEATER ARCHIVE. DisplayClass::Init_Theater copied the theater palette out of
#      MFCD::Retrieve with no check on the answer, so a missing, zero-length or damaged
#      content/<THEATER>.MIX was a NULL dereference inside CNC_Start_Custom_Instance, and
#      the same crash met any play folder assembled without its content/ archives. Three runs
#      against a scratch content folder (empty; a zero-length TEMPERAT.MIX; 400 bytes of
#      junk whose header reads as a negative entry count, which faulted in the archive
#      reader once the palette copy no longer did). Each must exit 0 with no FATAL line,
#      print the engine's own OPENCNC3D|theater| line, and stand a world up (COUNT|E1|have>0).
#      PROVEN TO FAIL: the build before this exits 139 on all three with
#      "FATAL: signal 11 while: CNC_Start_Custom_Instance" and never reaches the count.
#   b  THE REFUSAL READOUT. A library that cannot be loaded (what an antivirus quarantine
#      or Smart App Control does to TiberianDawn.dll) made game_boot return 0 and the shell
#      go back to the menu. The shell now prints BOOTFAIL|<scen>|<reason> naming the file,
#      HARNESS|end still counts exactly one failure, and the menu's digest after the refusal
#      equals the one before it (the menu stands, nothing leaked onto it).
#      PROVEN TO FAIL: the build before this prints zero BOOTFAIL lines.
#   c  THE PLAYER IS TOLD. --bootfailshot attempts the same refused start, draws the
#      "Unable to start mission" box once and writes it. NOTICE|open| exactly once with the
#      box's framebuffer rectangle; the PNG exists; the ink inside that rectangle against a
#      black frame is in the thousands (measured 15399 sampled pixels at 1280x720) while a
#      120-row strip below the box has none, so the box is drawn where it says it is.
#      PROVEN TO FAIL: the build before this has no --bootfailshot and no notice page.
#   d  A MISSING MISSION FILE is refused before the engine is asked, with a sentence that
#      names the file, and no crash. PROVEN TO FAIL: the build before this reports only
#      "CNC_Start_Custom_Instance FAILED" and nothing a player could read.
rm -rf shots/bf; mkdir -p shots/bf/empty shots/bf/zero shots/bf/junk
: > shots/bf/zero/TEMPERAT.MIX
python3 -c 'import random; random.seed(253); open("shots/bf/junk/TEMPERAT.MIX", "wb").write(bytes(random.randrange(256) for _ in range(400)))'
G253BASE="--cameos cameos.pack --dospack dossidebar.pack --dosinf dosinfantry.pack --dylib TiberianDawn.dylib --dir missions/"
gbegin shots/bf/a_empty.log shots/bf/a_zero.log shots/bf/a_junk.log
grun shots/bf/a_empty.log --scen SCG90EA --pack SCG01EA.pack $G253BASE --content shots/bf/empty/ \
     --noshroud --w 640 --h 400 --script gate_bootfail.txt
grun shots/bf/a_zero.log  --scen SCG90EA --pack SCG01EA.pack $G253BASE --content shots/bf/zero/ \
     --noshroud --w 640 --h 400 --script gate_bootfail.txt
grun shots/bf/a_junk.log  --scen SCG90EA --pack SCG01EA.pack $G253BASE --content shots/bf/junk/ \
     --noshroud --w 640 --h 400 --script gate_bootfail.txt
G253ARC=$GRC
G253AFATAL=$(cat shots/bf/a_empty.log shots/bf/a_zero.log shots/bf/a_junk.log | grep -c '^FATAL: signal')
G253ALINE=$(cat shots/bf/a_empty.log shots/bf/a_zero.log shots/bf/a_junk.log | grep -c '^OPENCNC3D|theater|TEMPERAT.PAL is in no loaded archive: TEMPERAT.MIX is missing, empty or damaged')
G253AE1=$(cat shots/bf/a_empty.log shots/bf/a_zero.log shots/bf/a_junk.log | sed -n 's/^COUNT|E1|have=\([0-9]*\).*/\1/p' | paste -sd' ' -)
G253AE1OK=1
for g253n in $G253AE1 x; do
  [ "$g253n" = "x" ] && continue
  [ "$g253n" -gt 0 ] 2>/dev/null || G253AE1OK=0
done
[ "$(echo "$G253AE1" | wc -w | tr -d ' ')" = "3" ] || G253AE1OK=0
# leg b: the shell, a library that cannot be loaded
G253B=$(./opencnc3d --dylib ./nonexistent.dylib --harness 60 --rounds 1 2>&1)
echo "$G253B" >> "$OUT"
G253BFAIL=$(echo "$G253B" | grep -c '^BOOTFAIL|SCG90EA|.*nonexistent\.dylib')
G253BEND=$(echo "$G253B" | grep -c '^HARNESS|end|1 round(s), 1 failure(s)')
G253BM1=$(echo "$G253B" | sed -n 's/^HARNESS|menu1|ink=[0-9.]*|digest=\([0-9a-f]*\).*/\1/p' | head -1)
G253BM2=$(echo "$G253B" | sed -n 's/^HARNESS|menu2|ink=[0-9.]*|digest=\([0-9a-f]*\).*/\1/p' | head -1)
# leg c: the box, photographed
rm -f shots/bf/bootfail.png
G253C=$(./opencnc3d --scen SCG90EA --pack SCG01EA.pack $G253BASE --content content/ --menupack dosmenu.pack \
        --dylib ./nonexistent.dylib --bootfailshot shots/bf/bootfail.png 2>&1)
echo "$G253C" >> "$OUT"
G253COPEN=$(echo "$G253C" | grep -c '^NOTICE|open|caption=Unable to start mission|')
G253CRECT=$(echo "$G253C" | sed -n 's/^NOTICE|open|caption=[^|]*|lines=[0-9]*|rect=\([0-9,]*\)|.*/\1/p' | head -1)
G253CPNG=0; [ -s shots/bf/bootfail.png ] && G253CPNG=1
G253CINK=0; G253CBELOW=0
if [ "$G253CPNG" = "1" ] && [ -n "$G253CRECT" ]; then
  python3 -c 'from PIL import Image; im = Image.open("shots/bf/bootfail.png"); Image.new("RGB", im.size, (0, 0, 0)).save("shots/bf/black.png")'
  G253CINK=$(python3 "$GATEDIR/gate_pixdiff.py" shots/bf/bootfail.png shots/bf/black.png "$G253CRECT" 2>/dev/null)
  G253CY1=$(echo "$G253CRECT" | cut -d, -f4)
  G253CBELOW=$(python3 "$GATEDIR/gate_pixdiff.py" shots/bf/bootfail.png shots/bf/black.png "0,$((G253CY1 + 8)),1279,$((G253CY1 + 127))" 2>/dev/null)
fi
# leg d: a mission file that is not there
G253D=$(./cnc_eyes --scen NOSUCH --pack SCG01EA.pack $G253BASE --content content/ --noshroud \
        --w 640 --h 400 --script gate_bootfail.txt 2>&1); G253DRC=$?
echo "$G253D" >> "$OUT"
G253DLINE=$(echo "$G253D" | grep -c '^BOOTFAIL|The mission file missions/NOSUCH.INI is missing')
G253DFATAL=$(echo "$G253D" | grep -c '^FATAL: signal')
if [ "$G253ARC" != "0" ] || [ "$G253AFATAL" != "0" ]; then
  bad "G253 a mission that cannot start says why: a missing, empty or junk theater archive still ends the mission start (exit=$G253ARC fatal-lines=$G253AFATAL theater-lines=$G253ALINE E1=[$G253AE1])"
elif [ "$G253ALINE" != "3" ] || [ "$G253AE1OK" != "1" ]; then
  bad "G253 a mission that cannot start says why: the runs survived but the engine did not say so or stood no world up (theater-lines=$G253ALINE want 3, E1=[$G253AE1] want three counts above 0)"
elif [ "$G253BFAIL" != "1" ] || [ "$G253BEND" != "1" ] || [ -z "$G253BM1" ] || [ "$G253BM1" != "$G253BM2" ]; then
  bad "G253 a mission that cannot start says why: the shell did not report the refused library (BOOTFAIL-lines=$G253BFAIL want 1, end=$G253BEND want 1, menu1=$G253BM1 menu2=$G253BM2 want equal)"
elif [ "$G253COPEN" != "1" ] || [ "$G253CPNG" != "1" ] || [ -z "$G253CRECT" ] \
     || [ "${G253CINK:-0}" -lt 3000 ] || [ "${G253CBELOW:-1}" != "0" ]; then
  bad "G253 a mission that cannot start says why: the notice box is not on the glass (open=$G253COPEN png=$G253CPNG rect=[$G253CRECT] ink-in-box=$G253CINK want >=3000, ink-below=$G253CBELOW want 0)"
elif [ "$G253DRC" = "0" ] || [ "$G253DLINE" != "1" ] || [ "$G253DFATAL" != "0" ]; then
  bad "G253 a mission that cannot start says why: a missing mission file is not refused by name (exit=$G253DRC line=$G253DLINE fatal=$G253DFATAL)"
else
  ok "G253 a mission that cannot start says why: an empty content folder, a zero-length and a junk TEMPERAT.MIX all boot SCG90EA (exit 0, $G253ALINE theater lines, E1 counts $G253AE1); a library that cannot be loaded is reported as BOOTFAIL|SCG90EA|... naming it, HARNESS|end counts 1 failure and the menu digest $G253BM1 stands; the Unable to start mission box is drawn at $G253CRECT with $G253CINK sampled pixels of ink and $G253CBELOW below it; a missing mission file is refused by name (exit $G253DRC)"
fi

menu1995_off

# =====================================================================================
# G250 THE SCREEN EDGES SCROLL OVER THE UNIT CARD.
#
# The unit card is pinned to the bottom-left corner of the Enhanced HUD, and
# edge_scroll_allowed used to refuse wherever uc_over said the pointer was on it. uc_hit
# answers for every point in the card's rectangle while the card is up, so with anything
# selected the bottom strip was dead across the card's width, the left strip across its
# height, and the corner between them: measured as exactly the card's rectangle at every
# window size tried. The card's own presses never pass through that guard (uc_click sits
# at the head of the press ladders), so the veto bought nothing the card needed. The fix
# takes the clause out, and this gate is its keeper: the strips answer the SCREEN edge,
# the rule G79 and G141 already hold the east and top strips to.
#
# HARNESS FACT THIS GATE RESTS ON. The veto this gate guards against read g_ucShownNow
# through uc_over, a latch set only by a drawn frame (shot) or by the unitcard and
# cardclick verbs; a script tick does not refresh it. Every selection change is therefore followed by unitcard BEFORE its
# probes, and the UNITCARD|rect line that verb prints is asserted to the pixel, so the
# probes are proven to lie on the card rather than assumed to. Without that, a card that
# was never latched would let every probe pass for the wrong reason.
#
# THREE GEOMETRIES, because the card's size follows the sidebar zoom and the fault would
# survive at any one of them. The Enhanced HUD takes a whole-number zoom of the window
# height over its 693-row housing, so zoom 2 needs at least 1386 rows: legs A and C run at
# 2560x1440, the size G82 and G134 already ask for, and at 1280x960 there is no zoom-2
# card left to measure (it is leg B's zoom-1 card, 166 rows higher).
#   A  2560x1440, zoom 2, card 480x332 at y=1108. Probes 2,1438 (the corner: both
#      strips), 200,1438 (the bottom strip over the tab row), 2,1180 (the left strip over
#      the card's bezel). Controls 1200,1438 and 2,300, bare map on the same strips.
#   B  1280x720, zoom 1, card 240x166 at y=554. Probes 2,718 / 100,718 / 2,600, control
#      300,718 and 2,300.
#   C  2560x1440 with gfx ui_scale 1, zoom 1, card 240x166 at y=1274. Probes 2,1438 /
#      100,1438 / 2,1340, controls 1200,1438 and 2,300.
# Each moving arm is measured against its control arm on the same strip and, for leg A,
# against a Classic run of the identical script (no card exists there, UNITCARD says
# unavailable) to 0.002, the way G141 measures against the DOS bar. The corner arm must
# move on both axes (x < 44 and z > 46 from 45,45); a pure west pan drifts z by 0.02, so
# the left arm is held to x alone and to its control.
#
# THE CLICK LEG, on A and B: lclick at 5,H-6 sits inside both strips over tab 1 and must
# still print GROUP|recall|key=1|slot=0|selection=N with the card's count unchanged after
# it, proving the strips scrolling did not take the card's press away from it. And the
# cursor over the card while it pans stays the plain arrow, as it does over the east
# strip on the sidebar.
#
# PROVEN TO FAIL on the build before the fix, when leg A still ran at 1280x960 on the
# 640x480 art HUD, whose zoom 2 put the 480x332 card at y=628 there: leg A printed
#   EDGEAT|frames=20|mouse=2,958|tacright=960|guard=blocked|busy=0
#   CAM|edgeat|x=45.000|z=45.000
# for all three card probes, and the same at 1280x720 (2,718 / 100,718 / 2,600) and at
# ui_scale 1 (2,958 / 100,958 / 2,800), while the controls moved to z=49.028 and
# x=41.965 (z=50.351 / x=40.940 at 720). The fixed build moves the corner to
# x=42.871 z=47.796 at 960 and x=42.164 z=48.480 at 720.
# =====================================================================================
gbegin /tmp/g250a.log /tmp/g250cl.log /tmp/g250b.log /tmp/g250c.log shots/g250_card.png
printf 'enabled 1\n' > gfx_g250.cfg
# The Classic control runs the SAME script as leg A, shot line included, so it goes
# first: the picture left behind is then the Enhanced one with the card in it, not the
# plain HUD without.
grun /tmp/g250cl.log --noshroud --scen SCG01EC --pack SCG01EA.pack $BASE --w 2560 --h 1440 \
     --script gate_edgecard.txt
export OPENCNC3D_HUD=new
grun /tmp/g250a.log --noshroud --scen SCG01EC --pack SCG01EA.pack $BASE --w 2560 --h 1440 \
     --gfx gfx_g250.cfg --script gate_edgecard.txt
grun /tmp/g250b.log --noshroud --scen SCG01EC --pack SCG01EA.pack $BASE --w 1280 --h 720 \
     --gfx gfx_g250.cfg --script gate_edgecard_720.txt
grun /tmp/g250c.log --noshroud --scen SCG01EC --pack SCG01EA.pack $BASE --w 2560 --h 1440 \
     --gfx gfx_g250.cfg --script gate_edgecard_ui1.txt
unset OPENCNC3D_HUD
gshots shots/g250_card.png
# The nth EDGEAT guard word and the nth CAM|edgeat x and z of a log.
g250g() { grep -a '^EDGEAT|' "$1" | sed -n "$2p" | sed 's/.*|mouse=\([0-9,]*\)|.*|guard=\([a-z]*\)|.*/\1 \2/'; }
g250x() { grep -a '^CAM|edgeat|' "$1" | sed -n "$2p" | sed 's/.*|x=\([0-9.-]*\)|.*/\1/'; }
g250z() { grep -a '^CAM|edgeat|' "$1" | sed -n "$2p" | sed 's/.*|z=\([0-9.-]*\)|.*/\1/'; }
# Geometry, asserted: the card where the probes expect it, and a selection on it.
G250RA=$(grep -ac '^UNITCARD|rect|x=0|y=1108|w=480|h=332|scale=2.00$' /tmp/g250a.log)
G250RB=$(grep -ac '^UNITCARD|rect|x=0|y=554|w=240|h=166|scale=1.00$' /tmp/g250b.log)
G250RC=$(grep -ac '^UNITCARD|rect|x=0|y=1274|w=240|h=166|scale=1.00$' /tmp/g250c.log)
G250UI=$(grep -ac '^GFX|ui_scale=1$' /tmp/g250c.log)
G250NA=$(grep -a '^UNITCARD|shown=1|count=' /tmp/g250a.log | head -1 | sed 's/.*|count=\([0-9]*\)|.*/\1/')
G250NB=$(grep -a '^UNITCARD|shown=1|count=' /tmp/g250b.log | head -1 | sed 's/.*|count=\([0-9]*\)|.*/\1/')
G250NC=$(grep -a '^UNITCARD|shown=1|count=' /tmp/g250c.log | head -1 | sed 's/.*|count=\([0-9]*\)|.*/\1/')
G250CL=$(grep -ac '^UNITCARD|unavailable|' /tmp/g250cl.log)
# The guards, as "mouse guard" pairs, all five arms of each leg.
G250GA="$(g250g /tmp/g250a.log 1)/$(g250g /tmp/g250a.log 2)/$(g250g /tmp/g250a.log 3)/$(g250g /tmp/g250a.log 4)/$(g250g /tmp/g250a.log 5)"
G250GB="$(g250g /tmp/g250b.log 1)/$(g250g /tmp/g250b.log 2)/$(g250g /tmp/g250b.log 3)/$(g250g /tmp/g250b.log 4)/$(g250g /tmp/g250b.log 5)"
G250GC="$(g250g /tmp/g250c.log 1)/$(g250g /tmp/g250c.log 2)/$(g250g /tmp/g250c.log 3)/$(g250g /tmp/g250c.log 4)/$(g250g /tmp/g250c.log 5)"
G250GL="$(g250g /tmp/g250cl.log 1)/$(g250g /tmp/g250cl.log 2)/$(g250g /tmp/g250cl.log 3)/$(g250g /tmp/g250cl.log 4)/$(g250g /tmp/g250cl.log 5)"
G250WA="2,1438 pass/200,1438 pass/2,1180 pass/1200,1438 pass/2,300 pass"
G250WB="2,718 pass/100,718 pass/2,600 pass/300,718 pass/2,300 pass"
G250WC="2,1438 pass/100,1438 pass/2,1340 pass/1200,1438 pass/2,300 pass"
# The camera after each arm: corner, bottom, left, bottom control, left control.
g250leg() {
  awk -v cx="$(g250x "$1" 1)" -v cz="$(g250z "$1" 1)" \
      -v bx="$(g250x "$1" 2)" -v bz="$(g250z "$1" 2)" \
      -v lx="$(g250x "$1" 3)" -v lz="$(g250z "$1" 3)" \
      -v kx="$(g250x "$1" 4)" -v kz="$(g250z "$1" 4)" \
      -v mx="$(g250x "$1" 5)" -v mz="$(g250z "$1" 5)" '
  function ab(v) { return v < 0 ? -v : v }
  BEGIN { eps = 0.002;
    print (cx < 44.0 && cz > 46.0 \
        && bz > 46.0 && ab(bx - kx) < eps && ab(bz - kz) < eps \
        && lx < 44.0 && ab(lx - mx) < eps && ab(lz - mz) < eps \
        && kz > 46.0 && mx < 44.0) ? 1 : 0 }'
}
G250VA=$(g250leg /tmp/g250a.log); G250VB=$(g250leg /tmp/g250b.log); G250VC=$(g250leg /tmp/g250c.log)
# Leg A against the Classic run of the same script, arm by arm, to 0.002.
G250VL=$(awk -v a1x="$(g250x /tmp/g250a.log 1)" -v a1z="$(g250z /tmp/g250a.log 1)" \
             -v a2x="$(g250x /tmp/g250a.log 2)" -v a2z="$(g250z /tmp/g250a.log 2)" \
             -v a3x="$(g250x /tmp/g250a.log 3)" -v a3z="$(g250z /tmp/g250a.log 3)" \
             -v c1x="$(g250x /tmp/g250cl.log 1)" -v c1z="$(g250z /tmp/g250cl.log 1)" \
             -v c2x="$(g250x /tmp/g250cl.log 2)" -v c2z="$(g250z /tmp/g250cl.log 2)" \
             -v c3x="$(g250x /tmp/g250cl.log 3)" -v c3z="$(g250z /tmp/g250cl.log 3)" '
  function ab(v) { return v < 0 ? -v : v }
  BEGIN { eps = 0.002;
    print (ab(a1x - c1x) < eps && ab(a1z - c1z) < eps && ab(a2x - c2x) < eps \
        && ab(a2z - c2z) < eps && ab(a3x - c3x) < eps && ab(a3z - c3z) < eps) ? 1 : 0 }')
# The click leg: the press over tab 1 is still the card's, and the count after it holds.
G250KA=$(grep -ac "^GROUP|recall|key=1|slot=0|selection=${G250NA:-x}\$" /tmp/g250a.log)
G250KB=$(grep -ac "^GROUP|recall|key=1|slot=0|selection=${G250NB:-x}\$" /tmp/g250b.log)
G250HA=$(grep -a '^UNITCARD|shown=1|count=' /tmp/g250a.log | sed -n 2p | sed 's/.*|count=\([0-9]*\)|.*/\1/')
G250HB=$(grep -a '^UNITCARD|shown=1|count=' /tmp/g250b.log | sed -n 2p | sed 's/.*|count=\([0-9]*\)|.*/\1/')
# The cursor over the card and over the east strip: the plain arrow at both.
G250CU=$(grep -a '^CURSOR|at=2.0,1438.0|' /tmp/g250a.log | sed 's/.*|shape=\([a-z_]*\)|.*/\1/')
G250CE=$(grep -a '^CURSOR|at=2555.0,700.0|' /tmp/g250a.log | sed 's/.*|shape=\([a-z_]*\)|.*/\1/')
if [ "$GRC" != "0" ]; then
  bad "G250 edges over the unit card: a run failed or wrote no shot (GRC=$GRC)"
elif [ "${G250RA:-0}" -lt 1 ] || [ "${G250RB:-0}" -lt 1 ] || [ "${G250RC:-0}" -lt 1 ] || [ "${G250UI:-0}" -lt 1 ]; then
  bad "G250 edges over the unit card: the card is not where the probes expect it (rect lines 1440=$G250RA 720=$G250RB ui1=$G250RC ui_scale=$G250UI, want 1 each; a 1440 leg reading y=794 or smaller means the window manager did not grant the 1440 rows asked for): $(grep -a '^UNITCARD|rect' /tmp/g250a.log /tmp/g250b.log /tmp/g250c.log | head -3 | tr '\n' ' ')"
elif [ "${G250NA:-0}" -lt 1 ] || [ "${G250NB:-0}" -lt 1 ] || [ "${G250NC:-0}" -lt 1 ]; then
  bad "G250 edges over the unit card: the band left nothing on the card (counts $G250NA/$G250NB/$G250NC, want >0), so the probes were not over a card"
elif [ "${G250CL:-0}" -lt 1 ]; then
  bad "G250 edges over the unit card: the Classic control run had a card (want UNITCARD|unavailable)"
elif [ "$G250GL" != "$G250WA" ]; then
  bad "G250 edges over the unit card: the Classic control refused a strip it has nothing on: [$G250GL] want [$G250WA]"
elif [ "$G250GA" != "$G250WA" ] || [ "$G250GB" != "$G250WB" ] || [ "$G250GC" != "$G250WC" ]; then
  bad "G250 edges over the unit card: a strip over the card is vetoed. 2560x1440 [$G250GA] want [$G250WA]; 1280x720 [$G250GB] want [$G250WB]; ui_scale 1 [$G250GC] want [$G250WC]"
elif [ "$G250VA" != "1" ] || [ "$G250VB" != "1" ] || [ "$G250VC" != "1" ]; then
  bad "G250 edges over the unit card: the guard passed but the camera did not move as its control did (legs ok=$G250VA$G250VB$G250VC want 111). 1440: corner $(g250x /tmp/g250a.log 1),$(g250z /tmp/g250a.log 1) bottom z=$(g250z /tmp/g250a.log 2) ctl z=$(g250z /tmp/g250a.log 4) left x=$(g250x /tmp/g250a.log 3) ctl x=$(g250x /tmp/g250a.log 5); 720: corner $(g250x /tmp/g250b.log 1),$(g250z /tmp/g250b.log 1) bottom z=$(g250z /tmp/g250b.log 2) ctl z=$(g250z /tmp/g250b.log 4) left x=$(g250x /tmp/g250b.log 3) ctl x=$(g250x /tmp/g250b.log 5); ui1: corner $(g250x /tmp/g250c.log 1),$(g250z /tmp/g250c.log 1) bottom z=$(g250z /tmp/g250c.log 2) ctl z=$(g250z /tmp/g250c.log 4) left x=$(g250x /tmp/g250c.log 3) ctl x=$(g250x /tmp/g250c.log 5) (start 45,45; corner wants x<44 and z>46, each arm equals its control to 0.002)"
elif [ "$G250VL" != "1" ]; then
  bad "G250 edges over the unit card: the three card arms at 2560x1440 do not match the Classic run of the same script to 0.002: card $(g250x /tmp/g250a.log 1),$(g250z /tmp/g250a.log 1) / $(g250x /tmp/g250a.log 2),$(g250z /tmp/g250a.log 2) / $(g250x /tmp/g250a.log 3),$(g250z /tmp/g250a.log 3) vs classic $(g250x /tmp/g250cl.log 1),$(g250z /tmp/g250cl.log 1) / $(g250x /tmp/g250cl.log 2),$(g250z /tmp/g250cl.log 2) / $(g250x /tmp/g250cl.log 3),$(g250z /tmp/g250cl.log 3)"
elif [ "${G250KA:-0}" -lt 1 ] || [ "${G250KB:-0}" -lt 1 ] || [ "$G250HA" != "$G250NA" ] || [ "$G250HB" != "$G250NB" ]; then
  bad "G250 edges over the unit card: the press on tab 1 inside both strips is no longer the card's (recall lines 1440=$G250KA 720=$G250KB want 1 each; count after the press $G250HA/$G250HB want $G250NA/$G250NB)"
elif [ "$G250CU" != "normal" ] || [ "$G250CE" != "normal" ]; then
  bad "G250 edges over the unit card: the cursor over the card while it pans is [$G250CU] and over the east strip [$G250CE] (want normal, the plain arrow, at both)"
else
  ok "G250 edges over the unit card: with $G250NA units selected and the zoom-2 card at y=1108 (480x332) on a 2560x1440 screen, the corner at 2,1438 pans to $(g250x /tmp/g250a.log 1),$(g250z /tmp/g250a.log 1), the bottom strip over the tab row to z=$(g250z /tmp/g250a.log 2) and the left strip over the bezel to x=$(g250x /tmp/g250a.log 3), each the same as its bare-map control and as the Classic run with no card; the same at 1280x720 (corner $(g250x /tmp/g250b.log 1),$(g250z /tmp/g250b.log 1)) and at ui_scale 1 (corner $(g250x /tmp/g250c.log 1),$(g250z /tmp/g250c.log 1)); a press on tab 1 inside both strips still recalls group 1 with $G250NA selected, and the cursor over the card is the plain arrow"
fi

# G252 THE CREDITS TICK. The credits readout is CreditClass::Current, walked toward the
# bank one step per tick by the engine (credits.cpp CreditClass::AI: the difference >> 5,
# bounded 1..143) and exported as CreditsCounter. In 1995 every step also sounded VOC_UP
# (TONE15) or VOC_DOWN (TONE16) at VOL_1, but from the tab's draw routine, which the DLL
# build never calls: the count crossed into the port and the sound did not. The renderer
# now raises the tone from the poll delta, once per engine tick, on the effects bus.
#
# See gate_cashtick.txt for the sequence. Two legs, both with --dumpsound AND --audiowav,
# for the reason G109 gives: with a sink the voice pool retires honestly, and the recording
# proves something audible was mixed, so a gain of zero cannot pass on the log alone.
#
#   ON   the second creditsdump must read credits=30000 counter=7860 up=20 EXACTLY
#        (5000 + 20 steps of 143: the readout steps, it does not jump), with exactly 20
#        TONE15 played lines before it; the third must read counter=30000; the fourth,
#        forty ticks into a power plant's drip payment, must read down >= 30 with at
#        least 30 TONE16 played lines after the third. No cash line may say SILENT.
#        The recording over the 20 count-up ticks (105..125, nothing else sounds there)
#        must read RMS > 300.
#   OFF  the same run under `gfx cash_tick 0`: no cash lines at all, the count-up window
#        silent to the sample. The two runs are tick-locked and otherwise identical, so
#        the down window (525..565), where the plant's construction noise also sounds,
#        is measured as the DIFFERENCE between the two recordings: that is the tick's
#        own energy, and it must read RMS > 150.
# The tick windows below are the script's own numbers (5 + 100 ticks before the money
# switch, 20 after it, 400 more, then 40 into the build) and move with it.
#
# PROVEN TO FAIL on the build before the fix: `creditsdump` is an unknown verb (exit 1),
# 0 TONE15 and 0 TONE16 lines, and the count-up window reads RMS 0.
# Measured on the fixed build: up=20, 349 TONE15 and 40 TONE16 played, count-up RMS 730,
# down-window difference RMS 358, OFF leg 0 cash lines and peak 0.
printf 'gfx cash_tick 0\n' > /tmp/g252_off.txt
cat "$GATEDIR/gate_cashtick.txt" >> /tmp/g252_off.txt
gbegin shots/g252_on.log shots/g252_on.wav shots/g252_off.log shots/g252_off.wav
G252BASE="--scen $SKMAP --pack $SKMAP.pack $SKBASE --skirmish --side gdi --ai 2 --noshroud --w 1280 --h 720 --dumpsound --musicvol 0"
grun shots/g252_on.log  $G252BASE --audiowav shots/g252_on.wav  --script "$GATEDIR/gate_cashtick.txt"
grun shots/g252_off.log $G252BASE --audiowav shots/g252_off.wav --script /tmp/g252_off.txt
gshots shots/g252_on.wav shots/g252_off.wav
CT_N=$(grep -c '^CREDITS|' shots/g252_on.log)
CT_L2=$(grep '^CREDITS|' shots/g252_on.log | sed -n '2p')
CT_L3=$(grep '^CREDITS|' shots/g252_on.log | sed -n '3p')
CT_L4=$(grep '^CREDITS|' shots/g252_on.log | sed -n '4p')
CT_L2OK=$(echo "$CT_L2" | grep -c '^CREDITS|credits=30000|counter=7860|.*|up=20|down=0|')
CT_L3OK=$(echo "$CT_L3" | grep -c '^CREDITS|credits=30000|counter=30000|')
CT_DOWN=$(echo "$CT_L4" | sed -n 's/.*|down=\([0-9]*\)|.*/\1/p')
# The tones in ORDER: TONE15 played lines before the second dump, TONE16 after the third.
CT_UP20=$(awk '/^CREDITS\|/{n++} n==1 && /^SOUND\|cash\|TONE15\|.*\|played$/{c++} END{print c+0}' shots/g252_on.log)
CT_DN=$(awk '/^CREDITS\|/{n++} n==3 && /^SOUND\|cash\|TONE16\|.*\|played$/{c++} END{print c+0}' shots/g252_on.log)
CT_UPALL=$(grep -c '^SOUND|cash|TONE15|.*|played$' shots/g252_on.log)
CT_DNALL=$(grep -c '^SOUND|cash|TONE16|.*|played$' shots/g252_on.log)
CT_SIL=$(grep -c '^SOUND|cash|.*|SILENT$' shots/g252_on.log)
CT_OFFN=$(grep -c '^SOUND|cash' shots/g252_off.log)
CT_OFFRC=$(grep -c '^CREDITS|credits=30000|counter=7860|' shots/g252_off.log)
CT_W=$(python3 - <<'PY'
import os, wave
import numpy as np
def load(p):
    if not os.path.exists(p) or os.path.getsize(p) == 0:
        return None, 0
    w = wave.open(p)
    a = np.frombuffer(w.readframes(w.getnframes()), dtype='<i2').astype(float)
    return a, w.getframerate() * w.getnchannels() * 66 // 1000   # samples per engine tick
on, pt = load("shots/g252_on.wav")
off, pt2 = load("shots/g252_off.wav")
if on is None or off is None or pt != pt2 or len(on) != len(off):
    print("-1 -1 -1 -1")
else:
    def rms(a): return int(round((a ** 2).mean() ** 0.5)) if len(a) else -1
    def peak(a): return int(np.abs(a).max()) if len(a) else -1
    up = slice(105 * pt, 125 * pt); dn = slice(525 * pt, 565 * pt)
    print(rms(on[up]), rms(on[dn] - off[dn]), rms(off[up]), peak(off[up]))
PY
)
CT_UPRMS=$(echo "$CT_W" | cut -d' ' -f1)
CT_DNRMS=$(echo "$CT_W" | cut -d' ' -f2)
CT_OFFRMS=$(echo "$CT_W" | cut -d' ' -f3)
CT_OFFPK=$(echo "$CT_W" | cut -d' ' -f4)
if [ "$GRC" != "0" ]; then
  bad "G252 the credits tick: a run failed or wrote no recording (GRC=$GRC). On the build before the fix creditsdump is an unknown verb and the run exits 1"
elif [ "${CT_N:-0}" != "4" ]; then
  bad "G252 the credits tick: $CT_N CREDITS| lines (want 4): the creditsdump verb is missing or the script did not run through"
elif [ "${CT_L2OK:-0}" != "1" ] || [ "${CT_UP20:-0}" != "20" ]; then
  bad "G252 the credits tick: twenty ticks after the money switch the readout must stand at exactly 5000 + 20 x 143 = 7860 with up=20 and twenty TONE15 played lines before it; got [$CT_L2] with $CT_UP20 TONE15 lines. The count must STEP, one tone per step, not jump"
elif [ "${CT_L3OK:-0}" != "1" ]; then
  bad "G252 the credits tick: 400 ticks later the readout has not arrived at the bank [$CT_L3]"
elif [ "${CT_DOWN:--1}" -lt 30 ] || [ "${CT_DN:-0}" -lt 30 ]; then
  bad "G252 the credits tick: forty ticks into a power plant's drip payment the readout reports down=$CT_DOWN with $CT_DN TONE16 played lines after the third dump (want >= 30 of each) [$CT_L4]. The count-down is silent"
elif [ "${CT_SIL:-1}" != "0" ]; then
  bad "G252 the credits tick: $CT_SIL cash lines came back SILENT. TONE15.JUV/TONE16.JUV fall back to the .AUD; SILENT means neither is on the disc"
elif [ "${CT_UPRMS:--1}" -le 300 ]; then
  bad "G252 the credits tick: the log says the tones played but the recording over the 20 count-up ticks reads RMS $CT_UPRMS (want > 300, measured 730). A tick at gain 0, or one routed to a bus the recording does not carry, reads like this"
elif [ "${CT_DNRMS:--1}" -le 150 ]; then
  bad "G252 the credits tick: the down window's difference against the OFF recording reads RMS $CT_DNRMS (want > 150, measured 358); the TONE16 lines are printed but nothing of them reaches the mix"
elif [ "${CT_OFFN:-1}" != "0" ] || [ "${CT_OFFRC:-0}" != "1" ] || [ "${CT_OFFPK:--1}" != "0" ]; then
  bad "G252 the credits tick: with cash_tick 0 the run printed $CT_OFFN cash lines (want 0), reached 7860 on schedule=$CT_OFFRC (want 1) and the count-up window peaks at $CT_OFFPK (want 0). The switch must silence the tone and leave the count alone"
else
  ok "G252 the credits tick: the readout steps 5000 to 7860 in twenty ticks of 143 with twenty TONE15 tones and arrives at 30000 ($CT_UPALL up-ticks in all), a power plant's drip payment sounds $CT_DN TONE16 tones in forty ticks ($CT_DNALL in all), none SILENT; the recording reads RMS $CT_UPRMS over the count-up and $CT_DNRMS of tick over the count-down, and with the Gameplay switch off the same run prints no cash line and the count-up window is silent (peak $CT_OFFPK, RMS $CT_OFFRMS) while the readout still reaches 7860 on schedule"
fi

# G251's pixel leg reads the 1995 Resolution list at its own rectangle (menu1995_on, at the top).
menu1995_on
# =====================================================================================
# G251 THE RESOLUTION LIST FITS THE DISPLAY. The Advanced page's Resolution row used to
# keep the first seven distinct sizes in the driver's largest-first order, with no desktop
# lookup and no bounds test, so on any display whose driver advertises sizes above the
# panel (a 4K mode on a 1080p display, a Retina display's full pixel count) the native size
# and everything under it fell off the end: a 1080p display offered 3840x2160 down to
# 2048x1536 and nothing that fit. Five things are proved here, the way G206 proves the
# display rows: through the dialog's own functions, with the dial read beside the page.
#
#   THE LIST (inject leg). `optres inject` builds the list for a display this machine does
#   not have: a 1080p panel whose driver lists eighteen modes, eight above it. Entry 0 reads
#   Desktop, every size is kept (nres 18, nothing dropped for being oversized), and under
#   Windowed the nine that cannot fit the usable room are greyed with a reason and refuse
#   the click; the count is nine and not eight because the room is 1920x1040 (a task bar)
#   and 1680x1050 is 10 rows too tall for it. Under Fullscreen the same entries are
#   pickable, and picking 3840x2160 writes the dial.
#   THE DESKTOP ENTRY. Picking it under Windowed resolves to the usable room (a real
#   window), not the 0x0 that used to leave the window untouched.
#   SCROLLING. The list shows seven rows; the wheel, the slider well's lower half and
#   `pick` on an entry past the window all move restop, and a pick of entry 12 lands.
#   THE QUANTISER. res_w and res_h used to be quantised to a step of 8 on the way in from
#   the preset and the gfx verb, so 2103x1183 came back 2104x1184 and matched no entry.
#   THE CLAMP. A preset asking Windowed at 6015x3383 is shrunk to the usable room before
#   the window is born, and says so; this is the shell's birth path in a hidden harness
#   run, the one path that applies a mode in an automated run.
#   THE RETINA SWITCH, at the same birth: full resolution is asked for by Tiberian Dawn's
#   file for both games, off without a hidpi line, and a Red Alert save of it keeps that
#   file's one line in step (the leg after the clamp says how).
#
# A live leg (no inject) reads THIS machine's display through the same verb: entry 0 is
# the desktop, every unfit entry is exactly the set marked DISABLED under Windowed, and
# the list holds every distinct size the driver offered plus the desktop when unlisted.
# A pixel leg diffs two shots of the open list at the same scroll position, Windowed
# against Fullscreen: the Desktop row is byte-identical and each of the six greyed
# rows below it differs, which is the DISABLED ink and nothing else (G206's neighbours
# use gate_pixdiff.py the same way).
#
# PROVEN TO FAIL on the build before the fix: `optres` is an unknown command (SCRIPT
# failure, 1 in the run), OPTDISP reads nres=7 with the desktop unmarked, gfx res_w 3008
# and res_h 1692 read back as fx_res=3008x1696, and the shell's birth prints no
# DISPLAY|clamped line at all.
# =====================================================================================
cat > /tmp/g251_inject.txt <<'G251EOF'
tick 30
options
optclick Visuals
optclick Enhanced
optclick Advanced...
optclick Windowed
optres inject 1920 1080 1920 1040 3840x2160,3325x1871,2880x1620,2715x1527,2560x1440,2351x1323,2103x1183,2048x1536,1920x1080,1680x1050,1600x900,1440x900,1366x768,1280x1024,1280x720,1024x768,800x600,640x480
gfx res_w 2103
gfx res_h 1183
optvis
optclick OK
optclick OK
optclick Resume Mission
options
optclick Visuals
optclick Advanced...
optres
optvis
optres open
optres hover 1
optres pick 1
optres pick 0
optvis
optres open
optres scroll 6
optres pick 12
optvis
optres open
optres bar lower
optres scroll -12
shot shots/g251_windowed.png
optclick Fullscreen
optres open
optres scroll -12
shot shots/g251_fullscreen.png
optres pick 17
optvis
optres open
optres pick 1
optvis
quit
G251EOF
cat > /tmp/g251_live.txt <<'G251EOF'
tick 30
options
optclick Visuals
optclick Enhanced
optclick Advanced...
optclick Windowed
optres open
optres
quit
G251EOF
gbegin shots/g251_windowed.png shots/g251_fullscreen.png shots/g251_inject.log shots/g251_live.log
G251BASE="--noshroud --nosound --scen SCG01EC --pack SCG01EA.pack $BASE --w 1280 --h 800 --gfx"
grun shots/g251_inject.log $G251BASE --script /tmp/g251_inject.txt
grun shots/g251_live.log   $G251BASE --script /tmp/g251_live.txt
gshots shots/g251_windowed.png shots/g251_fullscreen.png
G251R=$(grep '^OPTRES|page=' shots/g251_inject.log)
G251D=$(grep '^OPTDISP|' shots/g251_inject.log)
g251r() { echo "$G251R" | sed -n "$1p"; }
g251d() { echo "$G251D" | sed -n "$1p"; }
G251OK=1; G251WHY=""
g251bad() { G251OK=0; G251WHY="$G251WHY [$1]"; }
# EVERY optres VERB PRINTS THE READOUT, so the lines are, in order: 1 the inject, 2 the
# dialog reopened on the saved size (shut), 3 open, 4 hover 1, 5 the refused pick, 6 pick
# 0 (shut), 7 open, 8 scroll 6, 9 pick 12 (shut), 10 open, 11 the bar press, 12 scroll
# -12, 13 open under fullscreen, 14 scroll -12 there, 15 pick 17 (the last entry, out of
# view, so the pick scrolls first), 16 open, 17 pick 1 (out of view the other way).
# OPTDISP lines: 1 after the gfx verb, 2 on the reopen, 3 after pick 0, 4 after pick 12,
# 5 and 6 after the two fullscreen picks.
G251RN=$(echo "$G251R" | grep -c .)
[ "$G251RN" = "17" ] || g251bad "optres lines=$G251RN want 17"
# THE QUANTISER: the gfx verb wrote 2103x1183 and it stayed 2103x1183 (was 2104x1184);
# then the dialog, closed and opened again, found the entry (7) from the dial alone.
echo "$(g251d 1)" | grep -q '|fx_res=2103x1183|' || g251bad "quantiser: $(g251d 1 | cut -c1-120)"
echo "$(g251r 2)" | grep -q '|open=0|value=7|.*|fx_res=2103x1183|' || g251bad "saved size not found on reopen: $(g251r 2 | sed 's/|0=.*|fx_res/|fx_res/' | cut -c1-200)"
echo "$(g251d 2)" | grep -q 'mode=0|res=7|nres=18|.*|fx_res=2103x1183|' || g251bad "optdisp res=7: $(g251d 2 | cut -c1-120)"
# THE LIST: 18 entries, the desktop first and named, all nine oversized sizes kept, the
# desktop's own pair folded into entry 0 (desktop_listed=1, nmodes_distinct=17+1).
echo "$(g251r 2)" | grep -q '|nres=18|0=Desktop|1=3840 x 2160|' || g251bad "entry 0 is not Desktop"
echo "$(g251r 2)" | grep -q '|17=640 x 480|' || g251bad "640x480 missing"
echo "$(g251r 2)" | grep -q '|desktop=1920x1080|usable=1920x1040|bounds=1|nmodes=18|nmodes_distinct=18|desktop_listed=1|desktop_entry=0|over_desktop=9|nfit=9|' || g251bad "counts: $(g251r 2 | sed 's/.*|fx_res=/|fx_res=/' | cut -c1-220)"
# OPEN UNDER WINDOWED: entries 1..9 carry (DISABLED), entry 0 and 10.. do not, seven rows
# shown with a slider well beside them, scrolled so the current entry (7) is the last row
# in view (restop 1).
echo "$(g251r 3)" | grep -q '|open=1|.*|0=Desktop|1=3840 x 2160 (DISABLED)|.*|9=1680 x 1050 (DISABLED)|10=1600 x 900|' || g251bad "greying under Windowed: $(g251r 3 | cut -c1-260)"
[ "$(echo "$(g251r 3)" | grep -o '(DISABLED)' | wc -l | tr -d ' ')" = "9" ] || g251bad "DISABLED count"
echo "$(g251r 3)" | grep -q '|restop=1|shown=7|list=[0-9]*,[0-9]*,[0-9]*x63|rowh=9|bar=[0-9]*,[0-9]*,5x63|' || g251bad "window/bar: $(g251r 3 | sed 's/.*|restop=/|restop=/')"
# THE REFUSED PICK: hover 1 raises the tip, the pick leaves the list open on value 0.
grep -q '^OPTRES|tooltip|Larger than the desktop. A window this size cannot fit. Pick it under True fullscreen.' shots/g251_inject.log || g251bad "no tip on hover 1"
echo "$(g251r 4)" | grep -q '|open=1|value=7|hot=1|' || g251bad "hover 1: $(g251r 4 | cut -c1-80)"
echo "$(g251r 5)" | grep -q '|open=1|value=7|hot=1|' || g251bad "pick 1 was not refused: $(g251r 5 | cut -c1-80)"
# THE DESKTOP ENTRY UNDER WINDOWED resolves to the usable room, on the dial and the page.
echo "$(g251r 6)" | grep -q '|open=0|value=0|.*|fx_res=1920x1040|fx_mode=0|' || g251bad "pick 0 under Windowed: $(g251r 6 | sed 's/|0=.*|fx_res/|fx_res/' | cut -c1-160)"
echo "$(g251d 3)" | grep -q 'mode=0|res=0|nres=18|.*|fx_mode=0|fx_res=1920x1040|' || g251bad "optdisp after pick 0: $(g251d 3 | cut -c1-120)"
echo "$(g251d 3)" | grep -q '|desktop=1920x1080|usable=1920x1040|nfit=9$' || g251bad "optdisp tail: $(g251d 3 | sed 's/.*|sb_div/|sb_div/')"
# SCROLLING: the wheel moves restop to 6, the pick of 12 lands (page and dial), the
# list reopens with 12 in view (restop 6), the bar's lower half pages to the end (11),
# and the wheel back up clamps at 0.
echo "$(g251r 7)" | grep -q '|open=1|value=0|.*|restop=0|shown=7|' || g251bad "open on 0: $(g251r 7 | sed 's/.*|restop=/|restop=/')"
echo "$(g251r 8)" | grep -q '|open=1|value=0|.*|restop=6|shown=7|' || g251bad "scroll 6: $(g251r 8 | sed 's/.*|restop=/|restop=/')"
echo "$(g251d 4)" | grep -q 'mode=0|res=12|nres=18|.*|fx_mode=0|fx_res=1366x768|' || g251bad "pick 12: $(g251d 4 | cut -c1-120)"
echo "$(g251r 10)" | grep -q '|open=1|value=12|.*|restop=6|shown=7|' || g251bad "reopen on 12: $(g251r 10 | sed 's/.*|restop=/|restop=/')"
echo "$(g251r 11)" | grep -q '|open=1|value=12|.*|restop=11|shown=7|' || g251bad "bar lower: $(g251r 11 | sed 's/.*|restop=/|restop=/')"
echo "$(g251r 12)" | grep -q '|open=1|value=12|.*|restop=0|shown=7|' || g251bad "scroll -12: $(g251r 12 | sed 's/.*|restop=/|restop=/')"
# TRUE FULLSCREEN: nothing greyed; a pick past the window scrolls to it first (17 at the
# bottom, then 1 at the top), and the oversized 3840x2160 is picked and written.
echo "$(g251r 14)" | grep -q '|open=1|value=12|.*|1=3840 x 2160|2=3325 x 1871|.*|fx_mode=2|.*|restop=0|' || g251bad "fullscreen open: $(g251r 14 | cut -c1-200)"
echo "$(g251r 14)" | grep -q '(DISABLED)' && g251bad "greyed under fullscreen"
echo "$(g251d 5)" | grep -q 'mode=2|res=17|nres=18|.*|fx_mode=2|fx_res=640x480|' || g251bad "fullscreen pick 17: $(g251d 5 | cut -c1-120)"
grep -q 'scrolled|restop=11|for=optres pick 17' shots/g251_inject.log || g251bad "pick 17 did not scroll into view"
echo "$(g251d 6)" | grep -q 'mode=2|res=1|nres=18|.*|fx_mode=2|fx_res=3840x2160|' || g251bad "fullscreen pick 1: $(g251d 6 | cut -c1-120)"
grep -q 'scrolled|restop=1|for=optres pick 1' shots/g251_inject.log || g251bad "pick 1 did not scroll into view"
# NO SCRIPT FAILURE, and the window was only ever asked for (a hidden automated run).
grep -q '^SCRIPT|end .* 0 failures' shots/g251_inject.log || g251bad "script failures: $(grep '^SCRIPT|end' shots/g251_inject.log)"
[ "$(grep -c '^DISPLAY|' shots/g251_inject.log)" = "$(grep -c '^DISPLAY|deferred|' shots/g251_inject.log)" ] || g251bad "a DISPLAY line was not deferred"
# THE LIVE LEG: this machine's display, whatever it is.
G251L=$(grep '^OPTRES|page=' shots/g251_live.log | tail -1)
g251f() { printf '%s' "$1" | sed -n "s/.*|$2=\([-0-9]*\).*/\1/p"; }
G251LN=$(g251f "$G251L" nres); G251LDIST=$(g251f "$G251L" nmodes_distinct)
G251LLISTED=$(g251f "$G251L" desktop_listed); G251LOVER=$(g251f "$G251L" over_desktop)
G251LDIS=$(printf '%s' "$G251L" | grep -o '(DISABLED)' | wc -l | tr -d ' ')
echo "$G251L" | grep -q '|open=1|.*|0=Desktop|' || g251bad "live: entry 0 not Desktop"
echo "$G251L" | grep -q '|0=Desktop (DISABLED)' && g251bad "live: Desktop greyed"
echo "$G251L" | grep -q '|bounds=1|.*|desktop_entry=0|.*|injected=0' || g251bad "live: $(echo "$G251L" | sed 's/.*|fx_res=/|fx_res=/')"
[ "${G251LOVER:-x}" = "$G251LDIS" ] || g251bad "live: over_desktop=$G251LOVER but $G251LDIS DISABLED"
if [ "${G251LLISTED:-0}" = "1" ]; then G251LWANT=$G251LDIST; else G251LWANT=$((G251LDIST + 1)); fi
[ "${G251LN:-0}" = "$G251LWANT" ] || g251bad "live: nres=$G251LN want $G251LWANT (distinct=$G251LDIST listed=$G251LLISTED)"
[ "${G251LN:-0}" -ge 2 ] || g251bad "live: only $G251LN entries"
# THE PIXEL LEG: the open list's window from the readout (DOS pixels, x4 at 1280x800:
# the plate is 320x200 scaled 4 and sits at 0,0), row by row.
G251LIST=$(g251r 12 | sed -n 's/.*|list=\([0-9]*\),\([0-9]*\),\([0-9]*\)x\([0-9]*\)|rowh=\([0-9]*\)|.*/\1 \2 \3 \4 \5/p')
set -- $G251LIST 0 0 0 0 0
G251LX=$1; G251LY=$2; G251LW=$3; G251LH=$4; G251RH=$5
G251ROWS=""
if [ "${G251RH:-0}" -gt 0 ]; then
  G251I=0
  while [ $G251I -lt 7 ]; do
    G251Y0=$(( (G251LY + G251I * G251RH) * 4 )); G251Y1=$(( (G251LY + (G251I + 1) * G251RH) * 4 - 1 ))
    G251PX=$(python3 "$GATEDIR/gate_pixdiff.py" shots/g251_windowed.png shots/g251_fullscreen.png \
             "$((G251LX * 4)),$G251Y0,$(( (G251LX + G251LW) * 4 - 1 )),$G251Y1" 2>/dev/null)
    G251ROWS="$G251ROWS ${G251PX:-x}"
    if [ $G251I = 0 ]; then
      [ "${G251PX:-x}" = "0" ] || g251bad "pixel row 0 (Desktop) differs by $G251PX"
    else
      [ "${G251PX:-0}" -ge 20 ] || g251bad "pixel row $G251I differs by only $G251PX (want >= 20, the DISABLED ink)"
    fi
    G251I=$((G251I + 1))
  done
else
  g251bad "no list rectangle in the readout"
fi
# THE CLAMP, through the shell's birth: a preset asking for a window larger than the
# desktop, in a scratch folder of links (G233's arrangement) so the run folder's own
# preset is never touched. 6015x3383 is not a multiple of 8, so the asked= half also
# proves the preset is read unquantised.
G251SB=/tmp/g251_clamp
rm -rf "$G251SB"; mkdir -p "$G251SB/shots"
( cd "$RUNDIR" && find . -mindepth 1 -type d -print ) | while IFS= read -r g251d; do
  mkdir -p "$G251SB/${g251d#./}"
done
( cd "$RUNDIR" && find . -mindepth 1 \( -type f -o -type l \) -print ) | while IFS= read -r g251f; do
  case "${g251f#./}" in opencnc3d-controls.cfg|opencnc3d-fx.cfg|shots/*) continue ;; esac
  ln -s "$RUNDIR/${g251f#./}" "$G251SB/${g251f#./}" 2>/dev/null
done
printf 'display_mode 0\nres_w 6015\nres_h 3383\n' > "$G251SB/opencnc3d-fx.cfg"
( cd "$G251SB" && ./opencnc3d --scen SCG01EC --pack SCG01EA.pack $BASE --menupack dosmenu.pack \
    --nosound --harness 1 --rounds 1 --shotdir shots > /tmp/g251_shell.log 2>&1 )
G251SRC=$?
cat /tmp/g251_shell.log >> "$OUT"
G251CL=$(grep '^DISPLAY|clamped|' /tmp/g251_shell.log | head -1)
G251UW=$(g251f "$G251L" usable | sed 's/x.*//'); G251UH=$(printf '%s' "$G251L" | sed -n 's/.*|usable=[0-9]*x\([0-9]*\)|.*/\1/p')
G251GW=$(printf '%s' "$G251CL" | sed -n 's/.*|got=\([0-9]*\)x\([0-9]*\).*/\1/p')
G251GH=$(printf '%s' "$G251CL" | sed -n 's/.*|got=\([0-9]*\)x\([0-9]*\).*/\2/p')
[ "$G251SRC" = "0" ] || g251bad "clamp: the shell run failed (exit $G251SRC)"
echo "$G251CL" | grep -q '^DISPLAY|clamped|asked=6015x3383|got=[0-9]*x[0-9]*$' || g251bad "clamp: no clamped line [$G251CL]"
[ -n "$G251GW" ] && [ "$G251GW" -le "${G251UW:-0}" ] && [ "$G251GH" -le "${G251UH:-0}" ] || g251bad "clamp: got ${G251GW}x${G251GH} is not within the usable ${G251UW}x${G251UH}"
# THE RETINA SWITCH, through the same birth and the same sandbox. Full resolution is one
# setting for both games, off unless the player turned it on, and read from Tiberian
# Dawn's file whenever that exists. The shell prints DISPLAY|hidpi|wanted=W|applied=A|
# from=FILE as the window is born, in every run; applied is 1 only in a player's run, so it
# is 0 in all of these. A row turned on is saved as "hidpi 1    # moved"; a bare "hidpi 1"
# was written while the default was on and reads as the default.
#   (i)   the clamp run above, whose file has no hidpi line: wanted=0, by the default;
#   (ii)  the same kind of file with a marked hidpi 1 (a menu shot): wanted=1;
#   (iii) Red Alert (a menu shot), Tiberian Dawn's file with a bare hidpi 1 and Red Alert's
#         own with a marked one: wanted=0 from Tiberian Dawn's file (the old default),
#         Red Alert's live row 0 (RA3D|hidpi|live=0), and neither file written;
#   (iv)  Red Alert remembering its own file (--visualscfg ra3d-fx.cfg), both directions:
#         a. Tiberian Dawn's LF file without the line, Red Alert's own with a marked 1:
#            wanted=0, live 0 read back with gfxsave; an unrelated dial saves Red Alert's
#            file with hidpi still 0 and must leave Tiberian Dawn's alone; then hidpi 1
#            appends the one marked line (two saves of its own file, one VISCFG|hidpi);
#         b. Tiberian Dawn's CRLF file with a marked 1 in the middle, Red Alert's own 0:
#            wanted=1, live 1 read back; hidpi 0 replaces that line in place with an
#            unmarked 0, CRLF and every other byte kept, no temporary left;
#   (v)   saves Red Alert does not carry: a --visualscfg naming another file, whose
#         remembered save of hidpi 1 must not reach Tiberian Dawn's file, and a gfxsave of
#         ra3d-fx.cfg in that run, which is not the file the run remembers.
# Every Tiberian Dawn file that a rewrite may touch carries the enh_textures line every
# save writes, without which the rewrite refuses the file as not whole. Both Red Alert
# files are written fresh into the sandbox after removing whatever link stood there,
# because a save through a link lands in the run folder; --shotdir keeps the debrief
# picture a skirmish writes inside the sandbox too.
# PROVEN TO FAIL on the build before: no DISPLAY|hidpi or RA3D|hidpi line at all, Red
# Alert's live row read back from its own file, and Tiberian Dawn's file never written.
G251HI=$(grep '^DISPLAY|hidpi|' /tmp/g251_shell.log | head -1)
[ "$G251HI" = "DISPLAY|hidpi|wanted=0|applied=0|from=opencnc3d-fx.cfg (no hidpi line: the default)" ] || g251bad "retina (i): a file without the line gave [$G251HI]"
printf 'display_mode 0\nres_w 1280\nres_h 720\n%-18s %d    # moved\n' hidpi 1 > "$G251SB/opencnc3d-fx.cfg"
( cd "$G251SB" && perl -e 'alarm 120; exec @ARGV' ./opencnc3d --nosound $BASE --menupack dosmenu.pack \
    --menushot shots/g251_hidpi_td.png > /tmp/g251_hidpi_td.log 2>&1 ) || g251bad "retina (ii): the menu shot failed"
cat /tmp/g251_hidpi_td.log >> "$OUT"
G251HI=$(grep '^DISPLAY|hidpi|' /tmp/g251_hidpi_td.log | head -1)
[ "$G251HI" = "DISPLAY|hidpi|wanted=1|applied=0|from=opencnc3d-fx.cfg" ] || g251bad "retina (ii): a file with a marked hidpi 1 gave [$G251HI]"
G251RA="the Red Alert arms did not run: no Red Alert module is staged in this folder"
if [ -x ra3d/opencnc3d ] && [ -f ra3d/RedAlert.dylib ]; then
  G251RA="Red Alert follows Tiberian Dawn's file both ways (0 over its own marked 1, 1 over its own 0) on the window, the live row and a gfxsave read back, writing neither file at start; its saves append a marked hidpi 1 to an LF file and put an unmarked 0 in place in a CRLF file, every other byte kept; a save to another --visualscfg file or a gfxsave of a file the run does not remember leaves Tiberian Dawn's file alone"
  rm -f "$G251SB/ra3d-fx.cfg" "$G251SB/ra3d-controls.cfg" "$G251SB/ra_debrief.png"
  rm -rf /tmp/g251_hidpi_save; mkdir -p /tmp/g251_hidpi_save
  g251ra() {   # g251ra LOG SCRIPT [extra args]: one hidden Red Alert skirmish in the sandbox
    g251log=$1; g251scr=$2; shift 2
    ( cd "$G251SB" && perl -e 'alarm 180; exec @ARGV' ./ra3d/opencnc3d --module ra3d --hidden --nosound --no-movies \
        --raskirmish SCM10EA --side soviet --ai 3 --seed 4242 --savedir /tmp/g251_hidpi_save --shotdir shots \
        "$@" --script "$g251scr" > "$g251log" 2>&1 )
  }
  # (iii)
  printf 'enh_textures       1\ndisplay_mode 0\nres_w 1280\nres_h 720\n%-18s %d\n' hidpi 1 > "$G251SB/opencnc3d-fx.cfg"
  printf '%-18s %d    # moved\n' hidpi 1 > "$G251SB/ra3d-fx.cfg"
  cp "$G251SB/opencnc3d-fx.cfg" /tmp/g251_hidpi_td_before.cfg
  cp "$G251SB/ra3d-fx.cfg" /tmp/g251_hidpi_ra_before.cfg
  ( cd "$G251SB" && perl -e 'alarm 120; exec @ARGV' ./ra3d/opencnc3d --module ra3d --nosound \
      --menushot shots/g251_hidpi_ra.png > /tmp/g251_hidpi_ra.log 2>&1 ) || g251bad "retina (iii): the Red Alert menu shot failed"
  cat /tmp/g251_hidpi_ra.log >> "$OUT"
  G251HI=$(grep '^DISPLAY|hidpi|' /tmp/g251_hidpi_ra.log | head -1)
  [ "$G251HI" = "DISPLAY|hidpi|wanted=0|applied=0|from=opencnc3d-fx.cfg (an unmarked hidpi 1, the old default: the default)" ] || g251bad "retina (iii): Red Alert's window asked [$G251HI]"
  G251HI=$(grep '^RA3D|hidpi|' /tmp/g251_hidpi_ra.log | head -1)
  [ "$G251HI" = "RA3D|hidpi|live=0|from=opencnc3d-fx.cfg (an unmarked hidpi 1, the old default: the default)" ] || g251bad "retina (iii): Red Alert's live row [$G251HI]"
  cmp -s /tmp/g251_hidpi_td_before.cfg "$G251SB/opencnc3d-fx.cfg" || g251bad "retina (iii): a plain Red Alert run wrote Tiberian Dawn's file"
  cmp -s /tmp/g251_hidpi_ra_before.cfg "$G251SB/ra3d-fx.cfg" || g251bad "retina (iii): a plain Red Alert run wrote its own file"
  # (iv) a: appended
  printf 'enh_textures       1\ndisplay_mode 0\nres_w 1280\nres_h 720\n' > "$G251SB/opencnc3d-fx.cfg"
  cp "$G251SB/opencnc3d-fx.cfg" /tmp/g251_hidpi_td_before.cfg
  printf 'gfxsave /tmp/g251_hidpi_live.cfg\ngfx taa_sharpen 0.5\nframes 5\ngfx hidpi 1\nquit\n' > /tmp/g251_hidpi_a.txt
  { cat /tmp/g251_hidpi_td_before.cfg; printf '%-18s %d    # moved\n' hidpi 1; } > /tmp/g251_hidpi_a_want.cfg
  rm -f /tmp/g251_hidpi_live.cfg
  g251ra /tmp/g251_hidpi_a.log /tmp/g251_hidpi_a.txt --visualscfg ra3d-fx.cfg || g251bad "retina (iv a): the appending Red Alert run failed"
  cat /tmp/g251_hidpi_a.log >> "$OUT"
  grep -q '^SCRIPT|end .* 0 failures' /tmp/g251_hidpi_a.log || g251bad "retina (iv a): script [$(grep '^SCRIPT|end' /tmp/g251_hidpi_a.log)]"
  G251HI=$(grep '^DISPLAY|hidpi|' /tmp/g251_hidpi_a.log | head -1)
  [ "$G251HI" = "DISPLAY|hidpi|wanted=0|applied=0|from=opencnc3d-fx.cfg (no hidpi line: the default)" ] || g251bad "retina (iv a): Red Alert's window asked [$G251HI]"
  G251HI=$(grep '^RA3D|hidpi|' /tmp/g251_hidpi_a.log | head -1)
  [ "$G251HI" = "RA3D|hidpi|live=0|from=opencnc3d-fx.cfg (no hidpi line: the default)" ] || g251bad "retina (iv a): Red Alert's live row [$G251HI]"
  G251HI=$(sed -n 's/^hidpi  *\([0-9]\).*/\1/p' /tmp/g251_hidpi_live.cfg 2>/dev/null | head -1)
  [ "$G251HI" = "0" ] || g251bad "retina (iv a): Red Alert's live row read back [$G251HI] at the start of a remembering run, want 0"
  G251HI=$(grep '^VISCFG|hidpi|' /tmp/g251_hidpi_a.log | tr '\n' ' ')
  [ "$G251HI" = "VISCFG|hidpi|wrote|opencnc3d-fx.cfg|1 " ] || g251bad "retina (iv a): printed [$G251HI], want one VISCFG|hidpi|wrote|opencnc3d-fx.cfg|1"
  G251HI=$(grep -c '^VISCFG|wrote|ra3d-fx.cfg$' /tmp/g251_hidpi_a.log)
  [ "$G251HI" = "2" ] || g251bad "retina (iv a): Red Alert saved its own file $G251HI times, want 2 (hidpi 0, then 1)"
  cmp -s /tmp/g251_hidpi_a_want.cfg "$G251SB/opencnc3d-fx.cfg" || g251bad "retina (iv a): Tiberian Dawn's file is not itself plus one appended hidpi line: [$(tr '\n' '/' < "$G251SB/opencnc3d-fx.cfg")]"
  # (iv) b: replaced in place, the other way
  printf 'enh_textures       1\r\ndisplay_mode 0\r\nres_w 1280\r\n%-18s %d    # moved\r\nres_h 720\r\n# kept as written\r\n' hidpi 1 > "$G251SB/opencnc3d-fx.cfg"
  printf 'hidpi 0\n' > "$G251SB/ra3d-fx.cfg"
  printf 'enh_textures       1\r\ndisplay_mode 0\r\nres_w 1280\r\n%-18s %d\r\nres_h 720\r\n# kept as written\r\n' hidpi 0 > /tmp/g251_hidpi_b_want.cfg
  printf 'gfxsave /tmp/g251_hidpi_live.cfg\ngfx hidpi 0\nquit\n' > /tmp/g251_hidpi_b.txt
  rm -f /tmp/g251_hidpi_live.cfg
  g251ra /tmp/g251_hidpi_b.log /tmp/g251_hidpi_b.txt --visualscfg ra3d-fx.cfg || g251bad "retina (iv b): the replacing Red Alert run failed"
  cat /tmp/g251_hidpi_b.log >> "$OUT"
  grep -q '^SCRIPT|end .* 0 failures' /tmp/g251_hidpi_b.log || g251bad "retina (iv b): script [$(grep '^SCRIPT|end' /tmp/g251_hidpi_b.log)]"
  G251HI=$(grep '^DISPLAY|hidpi|' /tmp/g251_hidpi_b.log | head -1)
  [ "$G251HI" = "DISPLAY|hidpi|wanted=1|applied=0|from=opencnc3d-fx.cfg" ] || g251bad "retina (iv b): Red Alert's window asked [$G251HI], want 1 from Tiberian Dawn's file over its own 0"
  G251HI=$(grep '^RA3D|hidpi|' /tmp/g251_hidpi_b.log | head -1)
  [ "$G251HI" = "RA3D|hidpi|live=1|from=opencnc3d-fx.cfg" ] || g251bad "retina (iv b): Red Alert's live row [$G251HI]"
  G251HI=$(sed -n 's/^hidpi  *\([0-9]\).*/\1/p' /tmp/g251_hidpi_live.cfg 2>/dev/null | head -1)
  [ "$G251HI" = "1" ] || g251bad "retina (iv b): Red Alert's live row read back [$G251HI], want 1"
  G251HI=$(grep '^VISCFG|hidpi|' /tmp/g251_hidpi_b.log | tr '\n' ' ')
  [ "$G251HI" = "VISCFG|hidpi|wrote|opencnc3d-fx.cfg|0 " ] || g251bad "retina (iv b): printed [$G251HI], want one VISCFG|hidpi|wrote|opencnc3d-fx.cfg|0"
  cmp -s /tmp/g251_hidpi_b_want.cfg "$G251SB/opencnc3d-fx.cfg" || g251bad "retina (iv b): Tiberian Dawn's CRLF file is not itself with the one hidpi line replaced: [$(od -c "$G251SB/opencnc3d-fx.cfg" | head -4 | tr '\n' ' ')]"
  [ -e "$G251SB/opencnc3d-fx.cfg.tmp" ] && g251bad "retina (iv b): the rewrite left its temporary file behind"
  # (v) saves that are not carried
  printf 'enh_textures       1\ndisplay_mode 0\nres_w 1280\nres_h 720\n' > "$G251SB/opencnc3d-fx.cfg"
  cp "$G251SB/opencnc3d-fx.cfg" /tmp/g251_hidpi_td_before.cfg
  printf 'hidpi 0\n' > "$G251SB/ra3d-fx.cfg"
  printf 'hidpi 0\n' > /tmp/g251_hidpi_other.cfg
  printf 'gfx hidpi 1\nframes 5\ngfxsave ra3d-fx.cfg\nquit\n' > /tmp/g251_hidpi_c.txt
  g251ra /tmp/g251_hidpi_c.log /tmp/g251_hidpi_c.txt --visualscfg /tmp/g251_hidpi_other.cfg || g251bad "retina (v): the Red Alert run failed"
  cat /tmp/g251_hidpi_c.log >> "$OUT"
  grep -q '^SCRIPT|end .* 0 failures' /tmp/g251_hidpi_c.log || g251bad "retina (v): script [$(grep '^SCRIPT|end' /tmp/g251_hidpi_c.log)]"
  grep -q '^VISCFG|wrote|/tmp/g251_hidpi_other.cfg$' /tmp/g251_hidpi_c.log || g251bad "retina (v): the remembered other file was never saved, so the arm proved nothing"
  grep -q '^GFX|saved|ra3d-fx.cfg$' /tmp/g251_hidpi_c.log || g251bad "retina (v): the gfxsave of ra3d-fx.cfg did not save"
  G251HI=$(grep '^VISCFG|hidpi|' /tmp/g251_hidpi_c.log | tr '\n' ' ')
  [ -z "$G251HI" ] || g251bad "retina (v): printed [$G251HI], want no VISCFG|hidpi line"
  cmp -s /tmp/g251_hidpi_td_before.cfg "$G251SB/opencnc3d-fx.cfg" || g251bad "retina (v): a save Red Alert does not carry wrote Tiberian Dawn's file"
  rm -rf /tmp/g251_hidpi_save
fi
# EVERY NUMBER IS READ BY NOW: the sandbox and the leg's files go, as G233's do. The
# sandbox's settings files are real files and the rest are links into the run folder;
# every log was already appended to the suite's output.
rm -rf "$G251SB"
rm -f /tmp/g251_hidpi_* /tmp/g251_inject.txt /tmp/g251_live.txt /tmp/g251_shell.log
if [ "$GRC" != "0" ]; then
  bad "G251 the Resolution list fits the display: a run failed or a shot was not written (GRC=$GRC)"
elif [ "$G251OK" = "1" ]; then
  ok "G251 the Resolution list fits the display: for a 1080p panel listing 18 sizes the list holds all 18 with Desktop first, the 9 that cannot fit its 1920x1040 room are greyed and refused under Windowed with a reason and pickable under True fullscreen (3840x2160 written), Desktop under Windowed resolves to 1920x1040, the wheel/bar/pick scroll the seven-row window (restop 6, 11, 0), 2103x1183 survives the quantiser and lands on entry 7; this display lists $G251LN sizes ($G251LDIST distinct, desktop listed=$G251LLISTED) with $G251LOVER greyed; the Desktop row is pixel-identical across modes and the six greyed rows differ by$G251ROWS; the shell clamped a 6015x3383 window to ${G251GW}x${G251GH}; full resolution is asked for by Tiberian Dawn's file, wanted=0 without a hidpi line and 1 with a marked hidpi 1; $G251RA"
else
  bad "G251 the Resolution list fits the display:$G251WHY"
fi
menu1995_off

# G254 SELLING AND REPAIRING IN A MATCH ARE ORDERS, NOT ACTS. The first online playtest
# ended three matches with the desync alarm, and the players named three triggers:
# assigning a control group, repairing and selling. The first was real (a local field in
# the world hash, fixed with the group keypress G195 and G199 now make). This gate is the
# other two, over loopback: the host builds and places a Power Plant and SELLS it; both
# peers damage the joiner's Construction Yard at the same engine tick (hurtobj, which is
# a desync by construction unless the tick agrees, so the frame each peer applied it on
# is asserted equal FIRST and a misaligned run says "alignment" rather than "desync");
# the joiner then REPAIRS it. Asserted: no NETDESYNC line, both peers exit clean, at
# least 40 hash reports agree, the plant reads mission=Selling on both peers' dumps after
# the sale, and the yard reads repairing=1 with a strength above the 50 it was left at on
# BOTH peers, which is the repair order having crossed the wire and executed on a
# machine that never clicked.
#
# THE HOST'S SCRIPT STARTS THREE FRAMES LATER THAN THE JOINER'S (measured: the same
# `tick 5` reached frame 718 on the host and 715 on the joiner), so the host's first
# tick is 2 where the joiner's is 5. If that offset ever moves, the alignment assertion
# names it.
# ---------------------------------------------------------------------------
G254HRC=99; G254JRC=99; G254DESYNC=1; G254AGREE=0; G254HF=""; G254JF=""; G254SOLD=0; G254REP=0
if [ -x ./cnc_eyes ] && [ -s "$SKMAP.pack" ] && [ -s "missions/$SKMAP.INI" ]; then
  rm -f net_rs_host.log net_rs_join.log
  # --enhanced on both: the placement jolt is an Enhanced feature, and the joiner's
  # shakedump twelve ticks after the host's placement is the assertion that it stayed on
  # the host's screen.
  ./cnc_eyes --scen $SKMAP --pack $SKMAP.pack $SKBASE --enhanced --skirmish --side gdi --ai 0 \
      --host 17437 --script gate_net_rs_host.txt > net_rs_host.log 2>&1 &
  NHP=$!
  sleep 2
  ./cnc_eyes --scen $SKMAP --pack $SKMAP.pack $SKBASE --enhanced --skirmish --side nod --ai 0 \
      --join 127.0.0.1 17437 --script gate_net_rs_join.txt > net_rs_join.log 2>&1 &
  NJP=$!
  wait $NHP; G254HRC=$?
  wait $NJP; G254JRC=$?
  cat net_rs_host.log net_rs_join.log >> "$OUT"
  G254DESYNC=$(cat net_rs_host.log net_rs_join.log | grep -c '^NETDESYNC|')
  grep '^NETSYNC|' net_rs_host.log | sort -u > /tmp/g254_h.txt
  grep '^NETSYNC|' net_rs_join.log | sort -u > /tmp/g254_j.txt
  G254AGREE=$(comm -12 /tmp/g254_h.txt /tmp/g254_j.txt | grep -c .)
  # The frame each peer applied the damage on: the OBJDUMP-END receipt printed just
  # before its HURTOBJ line.
  G254HF=$(grep -B1 '^HURTOBJ|' net_rs_host.log | sed -n 's/^OBJDUMP-END.*frame=\([0-9]*\).*/\1/p' | head -1)
  G254JF=$(grep -B1 '^HURTOBJ|' net_rs_join.log | sed -n 's/^OBJDUMP-END.*frame=\([0-9]*\).*/\1/p' | head -1)
  # The plant was sold on BOTH peers: after the sale it reads mission=Selling and later
  # leaves the world. Counted as "a Selling line exists in each log".
  G254SOLD=0
  grep '^OBJ|BUILDING|NUKE|' net_rs_host.log | grep -q '|mission=Selling|' && G254SOLD=$((G254SOLD + 1))
  grep '^OBJ|BUILDING|NUKE|' net_rs_join.log | grep -q '|mission=Selling|' && G254SOLD=$((G254SOLD + 1))
  # The yard is repairing, above 50, on BOTH peers' final dumps.
  # THE HOST'S PLACEMENT DID NOT SHAKE THE JOINER: the joiner's shakedump twelve ticks
  # after the host's place auto must not show a live jolt (amp > 0 and age inside the
  # nine-tick decay). The joiner's own deploy jolted it at frame ~29 and has long expired.
  G254SHAKE=$(grep '^SHAKE|' net_rs_join.log | head -1 | sed -n 's/^SHAKE|amp=\([0-9.]*\)|frame=[-0-9]*|age=\([0-9]*\)|.*/\1 \2/p')
  G254LEAK=$(printf '%s' "$G254SHAKE" | awk '{ if ($1 > 0 && $2 <= 12) print 1; else print 0 }')
  G254REP=0
  for f in net_rs_host.log net_rs_join.log; do
    L=$(grep '^OBJ|BUILDING|FACT|' "$f" | grep '|str=[0-9]*|' | tail -1)
    ST=$(printf '%s' "$L" | sed -n 's/.*|str=\([0-9]*\)|.*/\1/p')
    printf '%s' "$L" | grep -q '|repairing=1|' && [ "${ST:-0}" -gt 50 ] && G254REP=$((G254REP + 1))
  done
fi
if [ -z "$G254HF" ] || [ "$G254HF" != "$G254JF" ]; then
  bad "G254 selling and repairing in a match: alignment. The two scripts damaged the yard on different frames (host ${G254HF:-none}, joiner ${G254JF:-none}), so any desync below is the test's and not the game's. Move the host's first tick until they agree"
elif [ "$G254HRC" = "0" ] && [ "$G254JRC" = "0" ] && [ "$G254DESYNC" = "0" ] && [ "${G254AGREE:-0}" -ge 40 ] \
     && [ "$G254SOLD" = "2" ] && [ "$G254REP" = "2" ] && [ "${G254LEAK:-1}" = "0" ]; then
  ok "G254 selling and repairing in a match are orders: the host sold its Power Plant (mission=Selling on both peers), both peers damaged the joiner's yard at frame $G254HF, the joiner's repair order ran on both (repairing=1 and climbing on both dumps), $G254AGREE hash reports agree, no desync alarm, both exited clean; and the host's placement left the joiner's camera still (joiner shake amp/age $G254SHAKE)"
else
  bad "G254 selling and repairing in a match: host exit=$G254HRC joiner exit=$G254JRC desync-alarms=$G254DESYNC(want 0) hash-reports-agreeing=$G254AGREE(want >=40) sold-on-peers=$G254SOLD(want 2) repairing-on-peers=$G254REP(want 2) joiner-shaken-by-host-placement=${G254LEAK:-none}(want 0; amp/age $G254SHAKE). $(grep -hE '^NETDESYNC|^NET\|error' net_rs_host.log net_rs_join.log 2>/dev/null | head -2 | tr '\n' ' ')"
fi

# G255 THE BUILD QUEUE IN A MATCH. G95 proves the queue in a mission, where a start is an
# act and the factory reads busy on the next frame. In a match a start is an ORDER, taken
# several frames later, and the pump used to read the idle frames in between as "free"
# and fire the whole queue into a factory that could take one (measured: five queued,
# five pumps in five frames, two delivered). The first online playtest reported it as the
# infantry queue dropping out. Asserted: the host queues five Minigunners after placing a
# Power Plant and a Barracks, five SBQUEUE|took lines follow (one per start the factory
# actually accepted, none called lost), the queue is empty at the end, and FIVE stand in
# the host's world AND in the joiner's, which never clicked. No desync alarm, both exit
# clean.
# ---------------------------------------------------------------------------
G255HRC=99; G255JRC=99; G255DESYNC=1; G255TOOK=0; G255LOST=0; G255EMPTY=0; G255H=0; G255J=0
if [ -x ./cnc_eyes ] && [ -s "$SKMAP.pack" ] && [ -s "missions/$SKMAP.INI" ]; then
  rm -f net_q_host.log net_q_join.log
  ./cnc_eyes --scen $SKMAP --pack $SKMAP.pack $SKBASE --skirmish --side gdi --ai 0 \
      --host 17438 --script gate_net_queue_host.txt > net_q_host.log 2>&1 &
  NHP=$!
  sleep 2
  ./cnc_eyes --scen $SKMAP --pack $SKMAP.pack $SKBASE --skirmish --side nod --ai 0 \
      --join 127.0.0.1 17438 --script gate_net_queue_join.txt > net_q_join.log 2>&1 &
  NJP=$!
  wait $NHP; G255HRC=$?
  wait $NJP; G255JRC=$?
  cat net_q_host.log net_q_join.log >> "$OUT"
  G255DESYNC=$(cat net_q_host.log net_q_join.log | grep -c '^NETDESYNC|')
  G255TOOK=$(grep -c '^SBQUEUE|took|E1|' net_q_host.log)
  G255LOST=$(grep -c '^SBQUEUE|lost|' net_q_host.log)
  G255EMPTY=$(grep -c '^SBQUEUEDUMP|entries=0$' net_q_host.log)
  G255H=$(sed -n 's/^COUNT|E1:@me|have=\([0-9]*\).*/\1/p' net_q_host.log | tail -1)
  # The joiner's final dump: every E1 the host's house owns. The host's house is the one
  # its own HOUSE line marks player=1.
  G255HOUSE=$(grep '^HOUSE|' net_q_host.log | grep '|player=1|' | tail -1 | cut -d'|' -f2)
  # From the joiner's LAST dump only: it dumps ten times through the blush window.
  G255J=$(sed -n '/^OBJDUMP-BEGIN/h; /^OBJDUMP-BEGIN/,$p' net_q_join.log | awk '/^OBJDUMP-BEGIN/{n=0} /^OBJ\|INFANTRY\|E1\|'"$G255HOUSE"'\|/{n++} END{print n+0}')
  # THE TARGET BLUSH IS THE CLICKER'S TO SEE. The host's rifleman force-fires at the
  # host's own Power Plant (cell 3,15, where place auto put it) and both peers dump the
  # world through the seven-tick envelope. The shared blush= bit lights on both, as the
  # 1995 engine has it; flashme= must read 1 on the host's lit lines and 0 on every one
  # of the joiner's, which is what keeps the defender from reading the attacker's aim.
  G255BH=$(grep "^OBJ|BUILDING|NUKE|$G255HOUSE|" net_q_host.log | grep -c '|blush=1|.*|flashme=1|')
  G255BJ=$(grep "^OBJ|BUILDING|NUKE|$G255HOUSE|" net_q_join.log | grep -c '|blush=1|')
  G255BJME=$(grep "^OBJ|BUILDING|NUKE|$G255HOUSE|" net_q_join.log | grep -c '|blush=1|.*|flashme=1|')
fi
if [ "$G255HRC" = "0" ] && [ "$G255JRC" = "0" ] && [ "$G255DESYNC" = "0" ] && [ "$G255TOOK" = "5" ] \
   && [ "$G255LOST" = "0" ] && [ "${G255EMPTY:-0}" -ge 1 ] && [ "${G255H:-0}" = "5" ] && [ "${G255J:-0}" = "5" ] \
   && [ "${G255BH:-0}" -ge 2 ] && [ "${G255BJ:-0}" -ge 2 ] && [ "${G255BJME:-1}" = "0" ]; then
  ok "G255 the build queue in a match: five Minigunners queued on the host, five starts taken by the barracks one at a time (none lost), the queue emptied, and five stand in the host's world and five in the joiner's; no desync alarm, both exited clean. And the host's force-fire blushed its plant for the host ($G255BH lit dumps with flashme=1) while the joiner's $G255BJ lit dumps all read flashme=0"
else
  bad "G255 the build queue in a match: host exit=$G255HRC joiner exit=$G255JRC desync-alarms=$G255DESYNC(want 0) starts-taken=$G255TOOK(want 5) starts-lost=$G255LOST(want 0) emptied=$G255EMPTY(want >=1) riflemen-host=${G255H:-none}(want 5) riflemen-joiner=${G255J:-none}(want 5; fewer means the pump fired into a busy factory and the orders were refused) blush-host-lit-for-host=${G255BH:-0}(want >=2) blush-joiner-lit=${G255BJ:-0}(want >=2, the shared bit) blush-joiner-lit-for-joiner=${G255BJME:-none}(want 0)"
fi

# =====================================================================================
# G256 THE TRACKS A VEHICLE LEAVES ON THE GROUND (treadmark_mod.h). Under ENHANCED a
# vehicle now marks the ground it drove over: two bands, laid along the path the engine
# actually took it on, fading on a timer and thinning away a set distance behind it.
#
# WHY THE MAP IS DESERT. The marks are a MULTIPLY, so they are a fraction of whatever
# colour the ground already is, and on SCG07EA's dark grass a quarter of nearly nothing
# is nearly nothing: the first build of this feature measured 4529 changed pixels there
# that read as a texture seam. SCB01EA's sand is the ground this can be measured on, and
# it is already in the run folder for twelve other gates.
#
# SIX CLAIMS, and the first three are the feature while the last three are the promises
# that make it safe to leave switched on:
#   (1) IT DRAWS. With the switch on, thousands of ground pixels differ from the same
#       frame with it off, and the pass says how many band quads it emitted.
#   (2) THE DISTANCE DIAL IS THE TRAIL'S LENGTH. Cut it from 12 cells to 3 and
#       measurably less ground is marked, in the same frame, with no extra ticks.
#   (3) THE TIMER IS THE MARK'S LIFE. Cut it from 40 seconds to 4 and the older end of
#       the same trail is gone. Both dials are read at DRAW time, so both legs
#       photograph one recorded path rather than three different drives.
#   (4) IT NEVER BRIGHTENS THE GROUND AND NEVER TOUCHES THE SIDEBAR. A multiply cannot
#       make a pixel lighter, so anything lighter is a mistake somewhere; one level of
#       one pixel is allowed because the chain resolves and grades after this pass.
#       WHERE THE SIDEBAR STARTS IS READ OUT OF THE DUMP, never assumed. The bar
#       magnifies by whole numbers, so its left edge follows the UI scale dial: at this
#       window width it stands at 1120 under the shipped default and at 960 one step
#       coarser. A hard-coded 960 counted those 160 columns of ordinary ground as chrome
#       and failed a build whose tracks reached nothing but sand.
#   (5) CLASSIC RECORDS NOTHING AND DRAWS NOTHING. Not "looks the same": the per-tick
#       observer is asked, and it must hold zero trails and zero points after the same
#       drive. A feature that records a path under Classic and merely declines to draw
#       it would pass a pixel test and still be a Tier 1 promise broken.
#   (6) TWO RUNS OF ONE SCRIPT ARE ONE PICTURE. This is the fault the whole tick/draw
#       split exists to prevent: a mark advanced per DRAWN frame instead of per engine
#       tick makes every --shot run disagree with the last one.
# =====================================================================================
cat > /tmp/g256.txt <<'G256EOF'
# Grade can raise a channel while physical luminance falls. Measure the multiply
# before grade/bloom/gamma; every spatial, lifetime and zero-leak floor is unchanged.
# The temporal anti-aliasing resolves after the marks and rings up to 4 levels lighter
# along their edges, so it is off too.
gfx grade_on 0
gfx bloom_on 0
gfx gamma_on 0
gfx aa_mode 0
cam 53 17
zoom min
tick 6
lclickobj BGGY 0
order 57 20
tick 70
order 51 21
tick 80
shot shots/g256_on.png
tmarkdump
gfx tmark_dist 3
shot shots/g256_dist.png
gfx tmark_dist 12
gfx tmark_life 4
shot shots/g256_life.png
gfx tmark_life 40
gfx tmark_on 0
shot shots/g256_off.png
quit
G256EOF
# The second run is the same script line for line, and only the file name differs: that
# is what makes the comparison a statement about the binary and not about two scripts.
sed 's#g256_on#g256_on2#' /tmp/g256.txt > /tmp/g256b.txt
# The Classic leg drives the same vehicle the same way with no --enhanced, and asks the
# observer what it recorded rather than looking at the picture.
cat > /tmp/g256c.txt <<'G256EOF'
# Grade can raise a channel while physical luminance falls. Measure the multiply
# before grade/bloom/gamma; every spatial, lifetime and zero-leak floor is unchanged.
# The temporal anti-aliasing resolves after the marks and rings up to 4 levels lighter
# along their edges, so it is off too.
gfx grade_on 0
gfx bloom_on 0
gfx gamma_on 0
gfx aa_mode 0
cam 53 17
zoom min
tick 6
lclickobj BGGY 0
order 57 20
tick 70
order 51 21
tick 80
shot shots/g256_classic.png
tmarkdump
quit
G256EOF
gbegin shots/g256_on.png shots/g256_on2.png shots/g256_dist.png shots/g256_life.png \
       shots/g256_off.png shots/g256_classic.png \
       shots/g256.log shots/g256b.log shots/g256c.log
# THE VEHICLES' LAMPS STAY OUT (--novehiclelights): a lamp adds light in proportion to the
# ground's own colour, so in the buggy's headlight pool a mark darkens the lit ground too and
# the counts below would measure the lamps as much as the marks. This gate is about the
# marks; G339 is the lamps'.
grun shots/g256.log  --noshroud --scen SCB01EA --pack SCB01EA.pack $BASE --w 1280 --h 800 \
     --script /tmp/g256.txt --enhanced --novehiclelights
grun shots/g256b.log --noshroud --scen SCB01EA --pack SCB01EA.pack $BASE --w 1280 --h 800 \
     --script /tmp/g256b.txt --enhanced --novehiclelights
grun shots/g256c.log --noshroud --scen SCB01EA --pack SCB01EA.pack $BASE --w 1280 --h 800 \
     --script /tmp/g256c.txt
gshots shots/g256_on.png shots/g256_on2.png shots/g256_dist.png shots/g256_life.png \
       shots/g256_off.png
G256Q=$(sed -n 's/^TMARK|on=1|trails=[0-9]*|points=[0-9]*|quads=\([0-9]*\)|.*/\1/p' shots/g256.log | head -1)
G256CT=$(sed -n 's/^TMARK|on=0|trails=\([0-9]*\)|.*/\1/p' shots/g256c.log | head -1)
G256CP=$(sed -n 's/^TMARK|on=0|trails=[0-9]*|points=\([0-9]*\)|.*/\1/p' shots/g256c.log | head -1)
G256CQ=$(sed -n 's/^TMARK|on=0|trails=[0-9]*|points=[0-9]*|quads=\([0-9]*\)|.*/\1/p' shots/g256c.log | head -1)
G256FAILS=$(sed -n 's/^SCRIPT|end .*: [0-9]* lines, \([0-9]*\) failures/\1/p' shots/g256.log | head -1)
# The column the map stops at, as the renderer reports it. See claim (4).
G256TR=$(sed -n 's/^TMARK|.*|tacright=\([0-9]*\).*/\1/p' shots/g256.log | head -1)
G256PIX=$(TACR="${G256TR:-0}" python3 - <<'PY'
import os
from PIL import Image
import numpy as np
def rd(n): return np.asarray(Image.open('shots/g256_%s.png' % n).convert('RGB')).astype(int)
off, on, dist, life = rd('off'), rd('on'), rd('dist'), rd('life')
d = (on != off).any(axis=2)
# The sidebar starts where the renderer says the map stops, and nothing in this pass may
# reach it. Not a constant: see claim (4).
bar = int(d[:, int(os.environ['TACR']):].sum())
# A multiply darkens. Count the pixels that came out LIGHTER instead.
up = int(((on - off) > 0).any(axis=2).sum())
print("%d %d %d %d %d" % (int(d.sum()), bar, up,
                          int((dist != off).any(axis=2).sum()),
                          int((life != off).any(axis=2).sum())))
PY
)
set -- $G256PIX
G256ON="$1"; G256BAR="$2"; G256UP="$3"; G256D="$4"; G256L="$5"
G256DET=0
cmp -s shots/g256_on.png shots/g256_on2.png && G256DET=1
if [ "$GRC" != "0" ]; then
  bad "G256 the tracks a vehicle leaves: a run failed or wrote no shot (GRC=$GRC)"
elif [ "${G256FAILS:-1}" != "0" ]; then
  bad "G256 the tracks a vehicle leaves: the script did not drive the buggy ($G256FAILS step failures; a MISSING lclickobj means this map's vehicle has moved and the gate needs a new one)"
elif [ -z "$G256TR" ] || [ "$G256TR" -le 0 ] || [ "$G256TR" -gt 1280 ]; then
  bad "G256 the tracks a vehicle leaves: the dump did not say where the map stops (tacright=${G256TR:-none} of 1280), so 'nothing on the sidebar' could not be measured and was not guessed at"
elif [ -n "$G256ON" ] && [ "$G256ON" -ge 3000 ] && [ "${G256Q:-0}" -ge 10 ] \
     && [ "$G256BAR" = "0" ] && [ "$G256UP" -le 4 ] \
     && [ "$G256D" -lt "$((G256ON * 4 / 5))" ] && [ "$G256D" -ge 200 ] \
     && [ "$G256L" -lt "$G256ON" ] && [ "$G256L" -ge "$((G256ON / 5))" ] \
     && [ "${G256CT:-9}" = "0" ] && [ "${G256CP:-9}" = "0" ] && [ "${G256CQ:-9}" = "0" ] \
     && [ "$G256DET" = "1" ]; then
  ok "G256 the tracks a vehicle leaves on the ground: a buggy driven two legs across SCB01EA's sand marks $G256ON pixels of ground in $G256Q band quads, not one of them on the sidebar, whose left edge the renderer puts at $G256TR of 1280, and not one of them lighter than the ground was ($G256UP, and one level of one pixel is the chain's own rounding). The trail length dial cut to 3 cells leaves $G256D of those pixels and the life cut to 4 seconds leaves $G256L, both read at draw time from ONE recorded drive. Under CLASSIC the same drive records $G256CT trails and $G256CP points and draws $G256CQ quads. Two runs of the one script are byte identical"
else
  bad "G256 the tracks a vehicle leaves on the ground: marked-px=$G256ON(want >=3000) band-quads=${G256Q:-none}(want >=10) on-the-sidebar=$G256BAR(want 0, measured from column $G256TR) lighter-px=$G256UP(want <=4) dist-3-px=$G256D(want <$((G256ON * 4 / 5)) and >=200) life-4s-px=$G256L(want <$G256ON and >=$((G256ON / 5))) classic-trails=${G256CT:-none}(want 0) classic-points=${G256CP:-none}(want 0) classic-quads=${G256CQ:-none}(want 0) two-runs-identical=$G256DET(want 1)"
fi

# G257 THE AUTHORED MAMMOTH TANK (model3d_mod.h): RETIRED WITH THE EXPERIMENTAL LOOK.
# It proved that under ENHANCED the Mammoth was drawn from models3d/HTNK.c3m in place of
# the cartridge's 138-triangle mesh: lit by a real light (black with every light at zero),
# its sun dial live, its own normals in the post chain's normal buffer, nothing on the
# sidebar, and Classic and --nomodel3d building none of it. m3_available draws an
# authored vehicle only under the experimental switch.
# NOTHING RUNS HERE. Its subject is drawn only under the experimental look, whose switch
# is now forced off (fx_state.h: a preset that still carries it is read as off, and a
# script that sets it fails as an unknown dial). No run can reach the feature, so every
# arm could only fail its script or measure a picture the feature is absent from.
# The number stays so the history reads straight; the code and art are left in the tree.
# NOTHING REPLACED IT: Enhanced draws the cartridge's own vehicle meshes, so no vehicle
# is lit as a model or writes a normal of its own. The sidebar's left edge at 1280 wide
# (column 1120) that later gates quote was measured here against --nosidebar.

# G258 THE FOUR LIGHTING ADDITIONS (HDR and the highlight rolloff, the sky cube map, the
# contact shadows, and relighting the cartridge's own art). All four are ENHANCED ONLY
# and all four carry a --noFEATURE switch, which is what this gate is built on.
#
# WHY THIS GATE EXISTS IN THIS SHAPE. The first build of all four appeared to change
# NOTHING: five frames with the features switched on one at a time came out byte
# identical. The cause was one variable referenced from the wrong scope in the light
# program, which failed to compile; the chain reports that and then carries on without
# it, drawing a complete and entirely reasonable picture -- the Classic one. So a broken
# shader and a feature that does nothing are the same photograph, and no pixel assertion
# can separate them. THE FIRST CLAIM IS THEREFORE NOT ABOUT PIXELS AT ALL.
#
# SIX CLAIMS:
#   (1) THE CHAIN IS ACTUALLY RUNNING. FX|chain must report usable=1 with all six
#       programs linked. Everything below is meaningless without it, which is exactly
#       the trap this gate was written after falling into.
#   (2) EACH OF THE THREE STILL SHIPPING MOVES THE PICTURE ON ITS OWN, switched on one at
#       a time against the frame with all four off. HIGH DYNAMIC RANGE IS RETIRED, so its
#       leg asks for it by name and must come out byte identical to the all-off frame.
#   (3) THE SKY IS REALLY LOADED. m3dump reports env=1 and the level count, because a
#       missing sky pack falls back to the two-colour fill and looks perfectly fine.
#   (4) THE ROLLOFF IS RETIRED WITH IT. It bends what a float target holds above white,
#       and there is no float target now, so in ONE run with one dial moved the number of
#       pixels pinned at white must be the SAME with the curve on and off. (While HDR
#       shipped, the count had to FALL when the curve was switched on.) It is
#       tested that way and not against the old chain because the bloom is scene
#       referred now as well, and a brighter bloom pushes pixels up to white while the
#       curve pulls the scene's own highlights down -- two features in opposite
#       directions, which is not a measurement of either.
#   (5) THE RELIGHT RE-AIMS THE LIGHT RATHER THAN RE-GRADING IT. Swinging the sun 180
#       degrees must move the cartridge buildings measurably MORE with it on than with
#       it off, while the frame's mean brightness stays close -- because the ratio is
#       meant to change where the light comes from and not how much of it there is.
#   (6) CLASSIC IS UNTOUCHED. With no --enhanced, all four switches together change
#       nothing at all. This is the Enhanced-only promise, and it is the claim here that
#       protects the other two hundred gates.
# =====================================================================================
cat > /tmp/g258.txt <<'G258EOF'
cam 24 41
zoom 2900
tick 10
shot shots/g258_X.png
m3dump
quit
G258EOF
for g258v in off sky contact relight; do
  sed "s#g258_X#g258_$g258v#" /tmp/g258.txt > /tmp/g258_$g258v.txt
done
# THE ROLLOFF IS TESTED AGAINST ITSELF, not against the eight bit chain. Comparing the
# whole HDR chain to the whole old one does not isolate it: the bloom is scene referred
# now too, so a bright area blooms harder and pushes its neighbours UP to white even as
# the rolloff pulls the scene's own highlights down. Measured, that came out as 5081
# clipped pixels before and 5113 after, and read as the feature failing when it was two
# features pulling opposite ways. One run, one bloom, one dial moved.
cat > /tmp/g258_hdr.txt <<'G258EOF'
cam 24 41
zoom 2900
tick 10
shot shots/g258_hdr.png
quit
G258EOF
# AND THE CURVE IS MEASURED WHERE THERE IS SOMETHING FOR IT TO DO, which is on the
# remastered structures: their painted metal and hazard stripes run well past white
# before the curve, and the cartridge's own art barely passes it at all. This leg was
# first aimed at the authored Mammoth hulls, which were retired with the experimental
# look; left on the grass and cartridge tanks they had stood on, the margin fell to 93
# clipped channels against 80, a true claim and a gate that would go red on a driver's
# rounding. Framed on the base's own buildings at camera 27,44 it measured 2,355
# against 36 over the tactical view.
#
# THIS LEG KEEPS THE SKY, AND IT IS THE ONLY ONE THAT DOES. The other legs turn off
# everything but the feature under test, which is the right shape for them and the wrong
# shape for this one: a lit model takes much of its light from the sky's ambient (an
# authored hull under --nosky peaked at 74 of 255 against temperate grass). Isolating
# HDR that way removes the highlights the rolloff exists to rescue, and the curve then
# measures as doing nothing because there is correctly nothing to do -- a red light for
# a feature that works. Isolation here is ONE DIAL MOVED BETWEEN TWO SHOTS OF ONE RUN,
# which is stronger than a flag comparison anyway: same scene, same bloom, same frame.
cat > /tmp/g258_clip.txt <<'G258EOF'
cam 27 44
zoom max
tick 8
shot shots/g258_clipoff.png
gfx tonemap 0
shot shots/g258_clip.png
quit
G258EOF
cat > /tmp/g258_swing.txt <<'G258EOF'
cam 24 41
zoom 2900
tick 10
gfx sun_az 30
shot shots/g258_swA.png
gfx sun_az 210
shot shots/g258_swB.png
quit
G258EOF
sed 's#g258_sw#g258_rsw#' /tmp/g258_swing.txt > /tmp/g258_rswing.txt
cat > /tmp/g258_cl.txt <<'G258EOF'
cam 24 41
zoom 2900
tick 10
shot shots/g258_classic.png
quit
G258EOF
sed 's#g258_classic#g258_classic2#' /tmp/g258_cl.txt > /tmp/g258_cl2.txt
# $BASE CARRIES --dir missions/ AND IS PASSED FIRST, so this one wins: a user map
# lives in missions/user_maps/ and the last --dir on the line is the one that counts.
G258B="--noshroud --scen USER30 --pack SCG01EA.pack --dir missions/user_maps/ --w 1280 --h 800"
# THE GROUND DETAIL, PINNED OFF. The grass clumps and the rocks are sunlit models, so
# swinging the sun moves them as well, which is not what claim (5) measures: they took the
# mean drift over its limit with the four additions exactly as before.
for g258f in /tmp/g258*.txt; do
  { printf 'gfx unified_lighting 0\ngfx fol_on 0\ngfx rock_on 0\ngfx mottle_on 0\n'; cat "$g258f"; } > "$g258f.pin" && mv "$g258f.pin" "$g258f"
done
# HDR IS ASKED FOR BY NAME in every leg that used to have it on, so that retiring it is
# measured rather than assumed: a settings file from a build that shipped it on carries
# hdr_on 1, and that must change nothing. Only the all-off leg and the second Classic leg
# go without. THE SKY'S BAR IS ITS OWN NOW: it was 2000 px while the sky leg ran with HDR
# on and the all-off frame without, so it counted HDR's change as well. Alone, the sky
# moves 765 px of this frame (the lit models' ambient), and claim (3) proves it loaded.
for g258f in /tmp/g258_hdr.txt /tmp/g258_sky.txt /tmp/g258_contact.txt /tmp/g258_relight.txt \
             /tmp/g258_clip.txt /tmp/g258_swing.txt /tmp/g258_rswing.txt /tmp/g258_cl.txt; do
  { printf 'gfx hdr_on 1\n'; cat "$g258f"; } > "$g258f.hdr" && mv "$g258f.hdr" "$g258f"
done
for g258f in /tmp/g258*.txt; do
  { printf 'gfx gamma_on 0\ngfx gamma 1.00000\ngfx shadow_on 1\ngfx sun_az 67.50000\ngfx sun_el 28.71428\ngfx shadow_strength 1.00000\ngfx shadow_soft 0.64286\ngfx shadow_bias 0.03043\ngfx shadow_span 1.41429\ngfx shadow_ox 11.57143\ngfx shadow_oz 7.71428\ngfx shadow_res 4096.0\ngfx shadow_r 0.49107\ngfx shadow_g 0.58000\ngfx shadow_b 0.68750\ngfx shadow_terrain 1\ngfx terrain_shadow_strength 0.69643\ngfx terrain_brightness 1.14286\ngfx terrain_contrast 1.03571\ngfx sun_lambert 1\ngfx sun_floor 0.54464\ngfx contact_len 0.30\ngfx contact_steps 8.0\ngfx contact_thick 0.60\ngfx contact_bias 0.020\ngfx contact_strength 1.0\ngfx shadow_noff 1.5\ngfx shadow_pen 0.08\ngfx shadow_terrain_rise 0.0\ngfx ssao_foliage 0.79464\ngfx cloud_on 1\ngfx cloud_strength 0.30357\ngfx cloud_cover 0.34800\ngfx cloud_sharp 0.03600\ngfx cloud_scale 20.00000\ngfx cloud_speed 0.57100\ngfx cloud_rot 67.50000\ngfx cloud_height 12.00000\ngfx fog_fx 1\ngfx fog_density 0.05357\ngfx fog_height 1.46964\ngfx fog_scale 2.00000\ngfx fog_speed 0.57143\ngfx fog_wind 64.28571\ngfx fog_light 4.50000\ngfx water_fx 1\ngfx water_flow 0.35000\ngfx water_flow_rate 0.25000\ngfx water_current 67.50000\ngfx water_foam 0.00000\ngfx water_foam_width 0.90000\ngfx water_wave_len 0.50000\ngfx water_wave_speed 0.35000\ngfx water_shallow 0.30000\ngfx water_deep 0.30000\ngfx water_edge 0.45000\ngfx water_fade 0.90000\ngfx water_fade_width 0.90000\ngfx water_foam_cross 0.30000\ngfx water_pan 0.35000\ngfx water_river_width 3.00000\ngfx water_river_speed 1.50000\ngfx water_bump 0.14732\ngfx water_spec 0.85000\ngfx water_refract 0.02000\ngfx water_natural 0.88393\ngfx water_dark 0.16000\ngfx water_wake 0.03571\ngfx water_wake_width 1.20000\ngfx water_wake_sim 1\ngfx water_wake_bump 1.20000\ngfx water_wake_ring 0.12000\ngfx water_wake_speed 0.02000\ngfx bloom_on 1\ngfx bloom_threshold 0.68000\ngfx bloom_knee 0.15000\ngfx bloom_intensity 0.92857\ngfx bloom_radius 1.93750\ngfx bloom_passes 4.0\ngfx ssao_on 1\ngfx ssao_radius 0.20670\ngfx ssao_intensity 0.51786\ngfx ssao_bias 0.01384\ngfx ssao_power 1.31250\ngfx ssao_samples 18.0\ngfx ssao_ground 0.5\ngfx ssao_object 1.0\ngfx light_intensity 0.96429\ngfx light_radius 2.87500\ngfx light_falloff 1.88393\ngfx light_fade 0.26786\ngfx light_fade_muzzle 0.15000\ngfx light_r 1.00000\ngfx light_g 0.72000\ngfx light_b 0.36000\ngfx light_explosions 1\ngfx light_muzzle 1\ngfx light_fire 1\ngfx light_tiberium 1\ngfx exposure -0.10714\ngfx contrast 1.22321\ngfx saturation 0.94643\ngfx temperature -0.01786\ngfx tint 0.0\ngfx lift -0.03571\ngfx gain 1.45089\ngfx grass 0\ngfx einf_scale 1.07143\ngfx m3inf_sun 0.30357\ngfx m3inf_fill 0.16071\ngfx m3inf_paint 0.55\ngfx m3_sun 0.69643\ngfx m3_ambient 3.00000\ngfx m3_normal 0.76786\ngfx m3_ao 0.51786\ngfx m3_roughmin 0.11607\ngfx m3_specamb 0.76786\ngfx tonemap 1.0\ngfx tone_knee 0.85\ngfx bloom_clamp 8.875\ngfx st_gamma 1.0\ngfx st_bright 0.73214\ngfx st_contrast 1.0\ngfx st_sat 1.0\ngfx st_shade 1.01786\ngfx st_sun 1.0\ngfx st_glow 1.0\ngfx st_ao 0.94643\n'; cat "$g258f"; } > "$g258f.historic" && mv "$g258f.historic" "$g258f"
done
gbegin shots/g258_off.png shots/g258_hdr.png shots/g258_clip.png shots/g258_sky.png shots/g258_contact.png \
       shots/g258_relight.png shots/g258_swA.png shots/g258_swB.png \
       shots/g258_rswA.png shots/g258_rswB.png shots/g258_classic.png \
       shots/g258_classic2.png shots/g258.log shots/g258r.log
grun shots/g258.log  $BASE $G258B --enhanced --nohdr --nosky --nocontact --norelight --script /tmp/g258_off.txt
grun -               $BASE $G258B --enhanced --nosky --nocontact --norelight --script /tmp/g258_hdr.txt
grun -               $BASE $G258B --enhanced --nocontact --norelight --script /tmp/g258_sky.txt
grun -               $BASE $G258B --enhanced --norelight --script /tmp/g258_contact.txt
grun shots/g258r.log $BASE $G258B --enhanced --relight --script /tmp/g258_relight.txt
grun -               $BASE $G258B --enhanced --nocontact --norelight --script /tmp/g258_clip.txt
grun -               $BASE $G258B --enhanced --norelight --script /tmp/g258_swing.txt
grun -               $BASE $G258B --enhanced --relight   --script /tmp/g258_rswing.txt
grun -               $BASE $G258B --script /tmp/g258_cl.txt
grun -               $BASE $G258B --nohdr --nosky --nocontact --relight --script /tmp/g258_cl2.txt
gshots shots/g258_off.png shots/g258_hdr.png shots/g258_clip.png shots/g258_clipoff.png shots/g258_sky.png shots/g258_contact.png \
       shots/g258_relight.png shots/g258_swA.png shots/g258_rswA.png shots/g258_classic.png
G258CHAIN=$(sed -n 's/^FX|chain|usable=\([0-9]\)|.*/\1/p' shots/g258.log | head -1)
G258PROGS=$(grep -c '^FX|chain|usable=1|light=1|bright=1|blur=1|resolve=1|crt=1|copy=1' shots/g258.log)
G258ENV=$(sed -n 's/^M3DUMP|.*|env=\([0-9]*\)|.*/\1/p' shots/g258r.log | head -1)
G258LOD=$(sed -n 's/^M3DUMP|.*|envlod=\([0-9]*\).*/\1/p' shots/g258r.log | head -1)
G258PIX=$(python3 - <<'PY'
from PIL import Image
import numpy as np
def rd(n): return np.asarray(Image.open('shots/g258_%s.png' % n).convert('RGB')).astype(int)
off = rd('off')
out = []
for n in ('hdr', 'sky', 'contact', 'relight'):
    out.append(int((rd(n) != off).any(axis=2).sum()))
# HDR must RESCUE clipped highlights: pixels pinned at white have to fall.
out.append(int((rd('clip') >= 255).sum()))
out.append(int((rd('clipoff') >= 255).sum()))
# The relight re-aims rather than re-grades: more response to a sun swing, same mean.
# The box is the two buildings; the brightness test keeps the grass out of it.
swA, swB, rA, rB = rd('swA'), rd('swB'), rd('rswA'), rd('rswB')
m = np.zeros(off.shape[:2], bool)
m[280:670, 130:1000] = True
m &= (swA.max(axis=2) > 60)
out.append(int(np.abs(swA[m] - swB[m]).mean() * 100) if m.any() else 0)
out.append(int(np.abs(rA[m] - rB[m]).mean() * 100) if m.any() else 0)
out.append(int(abs(rd('relight').mean() - off.mean()) * 100))
print(' '.join(str(v) for v in out))
PY
)
set -- $G258PIX
G258H="$1"; G258S="$2"; G258C="$3"; G258R="$4"
G258CLIP0="$5"; G258CLIP1="$6"; G258SWO="$7"; G258SWR="$8"; G258DRIFT="$9"
G258CL=0
cmp -s shots/g258_classic.png shots/g258_classic2.png && G258CL=1
if [ "$GRC" != "0" ]; then
  bad "G258 the lighting additions, HDR retired: a run failed or wrote no shot (GRC=$GRC). A MISSING sky.pack in the run folder is the first thing to check"
elif [ "${G258CHAIN:-0}" != "1" ] || [ "${G258PROGS:-0}" -lt 1 ]; then
  bad "G258 the lighting additions, HDR retired: the post chain did not come up (usable=${G258CHAIN:-none}, all-six-programs lines=${G258PROGS:-0}). Every pixel number below would be the CLASSIC picture and would read as four features doing nothing. Look in the log for a shader that failed to compile"
elif [ "${G258H:-1}" = "0" ] && [ "${G258S:-0}" -ge 400 ] \
     && [ "${G258C:-0}" -ge 1000 ] && [ "${G258R:-0}" -ge 20000 ] \
     && [ "${G258ENV:-0}" = "1" ] && [ "${G258LOD:-0}" -ge 5 ] \
     && [ -n "$G258CLIP1" ] && [ "$G258CLIP1" = "$G258CLIP0" ] \
     && [ "$G258SWR" -gt "$G258SWO" ] && [ "${G258DRIFT:-999}" -le 400 ] \
     && [ "$G258CL" = "1" ]; then
  ok "G258 the lighting additions, HDR retired: the chain is up with all six programs linked; asking for HDR by name changes 0 pixels and the rolloff leaves $G258CLIP0 clipped channels where they were, while the sky moves $G258S px, contact shadows $G258C and the relight $G258R; the sky really loaded ($G258LOD roughness levels), the relight re-aims a sun swing ($G258SWR against $G258SWO) with a mean drift of $G258DRIFT, and Classic is untouched"
else
  bad "G258 the lighting additions, HDR retired: hdr-px=$G258H(want 0, retired) sky-px=$G258S(want >=400) contact-px=$G258C(want >=1000) relight-px=$G258R(want >=20000) env=${G258ENV:-none}(want 1) envlod=${G258LOD:-none}(want >=5) clipped-with-the-curve-off=$G258CLIP0 with-it-on=$G258CLIP1(want the same, retired) sun-swing-relit=$G258SWR(want more than $G258SWO) mean-drift=$G258DRIFT(want <=400) classic-untouched=$G258CL(want 1)"
fi

# G259 THE DIAL PANEL'S TABLE: no two rows drive the same setting.
#
# WHY THIS EXISTS. Group 12g shipped with its "light from the sky" row written out
# TWICE, identical in key, label, field and help text. Both rows drove the one switch,
# so the panel worked perfectly: ticking either did the right thing. It was found by a
# reader, not by anything here, because there is nothing for a pixel gate to see -- the
# picture is correct either way and the only symptom is a second row on a panel nobody
# photographs.
#
# It is a static read of the table rather than a render, which is why it costs nothing
# and can afford to check all of it rather than the new groups only. Two rows on one
# field are not obviously wrong in principle, but there are none anywhere in this table
# today, so the invariant is real and worth holding: a second row is a copy-paste that
# got away rather than a design.
# $GATEDIR, not the working directory: the suite has cd'd into the run folder by now,
# and the run folder holds a build rather than the source this reads.
G259=$(python3 - "$GATEDIR/fx_state.h" <<'G259EOF' 2>>"$OUT"
import collections, re, sys
src = open(sys.argv[1], encoding="utf-8").read()
rows = re.findall(r'\{\s*(FXP_BOOL|FXP_FLOAT|FXP_STEP|FXP_INT)\s*,\s*"([^"]*)"\s*,\s*"([^"]*)"\s*,\s*FXO\((\w+)\)', src)
field = collections.Counter(r[3] for r in rows)
label = collections.Counter((r[1], r[2]) for r in rows)
dup = sorted(k for k, v in field.items() if v > 1)
dupl = sorted("%s/%s" % k for k, v in label.items() if v > 1)
for d in dup:
    print("G259| field %s has %d rows" % (d, field[d]), file=sys.stderr)
for d in dupl:
    print("G259| label %s appears twice" % d, file=sys.stderr)
print("%d %d %s" % (len(rows), len(dup) + len(dupl), ",".join(dup + dupl) or "-"))
G259EOF
)
G259N=$(echo "$G259" | awk '{print $1}')
G259D=$(echo "$G259" | awk '{print $2}')
G259W=$(echo "$G259" | awk '{print $3}')
if [ "${G259N:-0}" -ge 200 ] && [ "${G259D:-1}" = "0" ]; then
  ok "G259 the dial panel's table: $G259N rows, and no setting is reachable from two of them"
else
  if [ ! -f "$GATEDIR/fx_state.h" ]; then
    bad "G259 the dial panel's table: $GATEDIR/fx_state.h is not there, so the table could not be read at all. The gate resolves it beside gates.sh; a run folder needs it staged in (game/make-build.sh copies it)"
  else
    bad "G259 the dial panel's table: rows=${G259N:-none}(want >=200) duplicates=${G259D:-none}(want 0) [$G259W]"
  fi
fi

# =====================================================================================
# G260 THE 3D SOLDIER (model3d_mod.h m3_pose, cnc_eyes.cpp m3inf_draw). A skinned .c3m
# for E1 is drawn in place of the Minigunner's sprite, posed from its idle, run and shoot
# clips. This gate was written for the experimental set's soldier (models3d/E1.c3m),
# drawn under experimental art behind the m3inf_on row. That look is retired (its switch
# is forced off), and the soldier that replaced it is Enhanced's remastered Minigunner
# (einf/E1.c3m, behind the einf_on row), so the claims below are now made of that one.
# The remastered set is proved type by type on a user map by G275; this gate is its
# shipped mission, and the only one that asks whether the body leaves the sprite's rules.
#
# WHY SCG01EA. It is shipped, and its opening frame at the default camera holds four
# Minigunners, so the gate needs no staging and depends on nothing a player can edit.
#
# THE CLAIMS:
#   (1) THE FILE IS A SKINNED ONE. The load line (M3E|E1) reports bones and clips; a
#       rigid E1 would be drawn in one pose for ever and must not pass as the feature.
#   (2) IT DRAWS AND IT IS THE MODEL. The observer counts posed soldiers, and the same
#       frame with the soldiers' row off differs by hundreds of pixels, none of them on
#       the sidebar (column 1120 rightward at 1280 wide, measured against --nosidebar).
#   (3) IT IS GATED WHERE IT SAYS. Its own row off, --nomodel3d and Classic all report
#       no soldier drawn -- the observer's count, not a picture.
#   (4) THE VEHICLE ROW DOES NOT REACH IT. With the authored vehicles' row off, the
#       soldiers are still drawn: two rows that silently coupled would be a panel that
#       lies about what a switch does.
#   (5) TWO RUNS OF ONE SCRIPT ARE ONE PICTURE.
#   (6) THE BODY IS NOT THE SPRITE'S. Over 240 more ticks of the opening firefight
#       the soldiers' own headings leave the engine's 45 degree grid, and their clip
#       weights are caught part way through a cross-fade. A model drawn on the sprite's
#       eight headings with hard cuts between clips reads zero on both.
# =====================================================================================
cat > /tmp/g260.txt <<'G260EOF'
tick 20
shot shots/g260_on.png
m3dump
gfx m3_on 0
shot shots/g260_nov.png
m3dump
gfx m3_on 1
gfx einf_on 0
shot shots/g260_off.png
m3dump
gfx einf_on 1
G260EOF
# THE BODY IS HIS OWN: 240 more ticks, the per-soldier state read every other tick. The
# mission's men are on Hunt and hold still for the first hundred or so, so the window has
# to reach the fighting for a cross-fade to happen at all; a fade lasts three ticks, so
# reading every second tick cannot step over one.
i=0; while [ $i -lt 120 ]; do printf 'tick 2\nm3dump\n' >> /tmp/g260.txt; i=$((i+1)); done
echo quit >> /tmp/g260.txt
sed 's#g260_on\.png#g260_on2.png#' /tmp/g260.txt > /tmp/g260b.txt
cat > /tmp/g260c.txt <<'G260EOF'
tick 20
shot shots/g260_nom.png
m3dump
quit
G260EOF
sed 's#g260_nom#g260_classic#' /tmp/g260c.txt > /tmp/g260d.txt
gbegin shots/g260_on.png shots/g260_on2.png shots/g260_nov.png shots/g260_off.png \
       shots/g260_nom.png shots/g260_classic.png \
       shots/g260.log shots/g260b.log shots/g260c.log shots/g260d.log
grun shots/g260.log  --scen SCG01EA --pack SCG01EA.pack $BASE --nosound --w 1280 --h 800 \
     --script /tmp/g260.txt --enhanced
grun shots/g260b.log --scen SCG01EA --pack SCG01EA.pack $BASE --nosound --w 1280 --h 800 \
     --script /tmp/g260b.txt --enhanced
grun shots/g260c.log --scen SCG01EA --pack SCG01EA.pack $BASE --nosound --w 1280 --h 800 \
     --script /tmp/g260c.txt --enhanced --nomodel3d
grun shots/g260d.log --scen SCG01EA --pack SCG01EA.pack $BASE --nosound --w 1280 --h 800 \
     --script /tmp/g260d.txt
gshots shots/g260_on.png shots/g260_on2.png shots/g260_off.png
# The three dumps of the main run, in order: on, vehicles off, soldiers off.
g260inf() { sed -n 's/^M3DUMP|.*|inf=\([0-9]*\)|.*/\1/p' "$1" | sed -n "${2}p"; }
G260ON=$(g260inf shots/g260.log 1)
G260NOV=$(g260inf shots/g260.log 2)
G260OFF=$(g260inf shots/g260.log 3)
G260NOM=$(g260inf shots/g260c.log 1)
G260CL=$(g260inf shots/g260d.log 1)
G260BONES=$(sed -n 's/^M3E|E1|tris.*|bones \([0-9]*\)|clips.*/\1/p' shots/g260.log | head -1)
G260CLIPS=$(sed -n 's/^M3E|E1|tris.*|clips \([0-9]*\)$/\1/p' shots/g260.log | head -1)
G260F=$(sed -n 's/^SCRIPT|end .*: [0-9]* lines, \([0-9]*\) failures/\1/p' shots/g260.log | head -1)
# OFF THE SPRITE'S GRID: headings that are not a multiple of 45 degrees, and clip weights
# caught mid-fade. Either count at zero means the soldier is still on the sprite's rules.
G260OFFGRID=$(sed -n 's/^M3INF|.*|yaw=\([0-9.]*\)|.*/\1/p' shots/g260.log \
    | awk '{r = $1 - 45 * int($1 / 45); if (r > 0.5 && r < 44.5) n++} END {print n + 0}')
G260FADE=$(sed -n 's/^M3INF|.*|idle=\([0-9.]*\)|run=\([0-9.]*\)|shoot=\([0-9.]*\)$/\1 \2 \3/p' shots/g260.log \
    | awk '{for (k = 1; k <= 3; k++) if ($k > 0.05 && $k < 0.95) n++} END {print n + 0}')
G260PIX=$(python3 - <<'PY'
from PIL import Image
import numpy as np
def rd(n): return np.asarray(Image.open('shots/g260_%s.png' % n).convert('RGB')).astype(int)
on, off, on2 = rd('on'), rd('off'), rd('on2')
d = (on != off).any(axis=2)
print(int(d[:, :1120].sum()), int(d[:, 1120:].sum()), int((on != on2).any(axis=2).sum()))
PY
)
G260VIEW=$(echo "$G260PIX" | awk '{print $1}')
G260BAR=$(echo "$G260PIX" | awk '{print $2}')
G260DET=$(echo "$G260PIX" | awk '{print $3}')
if [ "$GRC" = "0" ] && [ "${G260BONES:-0}" -gt 0 ] && [ "${G260CLIPS:-0}" -ge 3 ] \
   && [ "${G260ON:-0}" -ge 3 ] && [ "${G260NOV:-0}" -ge 3 ] \
   && [ "${G260OFF:-x}" = "0" ] \
   && [ "${G260NOM:-x}" = "0" ] && [ "${G260CL:-x}" = "0" ] \
   && [ "${G260VIEW:-0}" -ge 300 ] && [ "${G260BAR:-1}" = "0" ] \
   && [ "${G260DET:-1}" = "0" ] && [ "${G260F:-1}" = "0" ] \
   && [ "${G260OFFGRID:-0}" -gt 0 ] && [ "${G260FADE:-0}" -gt 0 ]; then
  ok "G260 the 3D soldier: the remastered E1 is a skinned model ($G260BONES bones, $G260CLIPS clips) and $G260ON Minigunners on SCG01EA are posed from it, changing $G260VIEW pixels against the sprites and none on the sidebar. Gated where the panel says: its own row off, --nomodel3d and Classic each draw 0, and taking the authored vehicles' row out still leaves $G260NOV soldiers drawn. Off the sprite's rules: $G260OFFGRID heading samples between the engine's 45 degree steps and $G260FADE clip weights caught mid cross-fade. Two runs are one picture"
else
  bad "G260 the 3D soldier: rc=$GRC bones=${G260BONES:-none}(>0) clips=${G260CLIPS:-none}(>=3) drawn on=${G260ON:-none}(>=3) vehicles-off=${G260NOV:-none}(>=3) row-off=${G260OFF:-none}(0) nomodel3d=${G260NOM:-none}(0) classic=${G260CL:-none}(0) pixels=${G260VIEW:-none}(>=300) sidebar=${G260BAR:-none}(0) determinism=${G260DET:-none}(0) script-failures=${G260F:-none}(0) off-grid-headings=${G260OFFGRID:-none}(>0) mid-fade-weights=${G260FADE:-none}(>0)"
fi

# =====================================================================================
# G261 THE POINTER MEETS THE GROUND ON A RAISED USER MAP (terrain_range_refresh). A user
# map is the donor pack reskinned with its own .HGT, and the reskin zeroed the ground's
# height range without recomputing it. The mouse ray searches only inside that range, so
# on USER92's plateau (a cell above the datum) it stopped at height zero, about a cell
# north of the real ground: the 3D cursor drew there, and a unit could only be selected
# by aiming well above it. Measured before the fix: 0.84 cell from the Mammoth, 0.87 from
# the Construction Yard, 0.71 to 0.83 from the Minigunners.
#
# WHY A USER MAP, against the usual rule. The fault exists only on a reskinned map with
# its own heights, and no shipped mission is one. USER92 is a tracked example; if it is
# ever edited off its plateau this gate says so rather than passing on flat ground: it
# also demands the Construction Yard stand at least half a cell above the datum.
#
# TWO CLAIMS PER OBJECT, aimed at the Mammoth, the Yard and two Minigunners:
#   (1) THE RAY FINDS THE GROUND. The terrain search's hit is within 0.05 cell of the
#       same ray's closed-form meeting with the flat plane the object stands on
#       (planegap). This is the fault itself and nothing else: with the range refresh
#       taken out it reads 0.53 to 0.79 on all five, and 0.000 with it in.
#   (2) THE POINTER LANDS ON THE OBJECT (raygap, from the object's own centre): within
#       a quarter cell of the Mammoth and the Yard, and for a soldier within 0.65 of his
#       drawn height. The soldier's limit is a ratio because the aim point is the middle
#       of his billboard, and the ray through it meets the ground behind his feet by
#       about 0.55 of his height at this camera. So it grows with the infantry size row
#       and says nothing about the search: 0.206 at a drawn height of 0.375, 0.249 at
#       0.45, 0.305 at 0.549, 0.422 at 0.75, planegap 0.000 at every one. A fixed 0.3
#       cell was the old soldier's height, and the size change past it turned this gate
#       red with the pointer landing exactly where it always had. A soldier with no
#       drawn height fails rather than passing an empty ratio.
# The first measurement is taken BEFORE any frame is drawn, so the load path itself has
# to be right, not only the per-frame refresh.
# =====================================================================================
cat > /tmp/g261.txt <<'G261EOF'
cam 33 31
zoom max
cursorobj HTNK 0
tick 3
shot shots/g261.png
cursorobj HTNK 0
cursorobj FACT 0
cursorobj E1 0
cursorobj E1 3
m3dump
quit
G261EOF
gbegin shots/g261.png shots/g261.log
grun shots/g261.log --reskin --noshroud --scen USER92 --pack SCG01EA.pack $BASE \
     --dir missions/user_maps/ --nosound --w 1280 --h 800 --script /tmp/g261.txt --enhanced
G261GAPS=$(sed -n 's/^CURSOROBJ|\([A-Z0-9#]*\)|.*|raygap=\([0-9.]*\)|.*/\1=\2/p' shots/g261.log | tr '\n' ' ')
G261TALL=$(sed -n 's/^CURSOROBJ|\(E1[A-Z0-9#]*\)|.*|tall=\([0-9.]*\)|.*/\2/p' shots/g261.log | head -1)
G261PG=$(sed -n 's/^CURSOROBJ|\([A-Z0-9#]*\)|.*|planegap=\([0-9.]*\)|.*/\1=\2/p' shots/g261.log | tr '\n' ' ')
G261BAD=$(awk -F'|' '/^CURSOROBJ\|.*\|raygap=/ {
      rg = -1; pg = -1; t = -1
      for (i = 1; i <= NF; i++) {
        if ($i ~ /^raygap=/)   { v = $i; sub(/^raygap=/, "", v);   rg = v + 0 }
        if ($i ~ /^planegap=/) { v = $i; sub(/^planegap=/, "", v); pg = v + 0 }
        if ($i ~ /^tall=/)     { v = $i; sub(/^tall=/, "", v);     t = v + 0 }
      }
      if ($2 ~ /^E1/) lim = (t > 0) ? 0.65 * t : -1; else lim = 0.25
      if (rg < 0 || pg < 0 || pg > 0.05 || rg > lim) b++
    } END {print b + 0}' shots/g261.log)
G261N=$(grep -ac '^CURSOROBJ|.*|raygap=' shots/g261.log)
G261HIGH=$(sed -n 's/^M3FACT|.*|ground=\([-0-9.]*\)$/\1/p' shots/g261.log | head -1)
G261PLAT=$(grep -ac '^reskin: USER92.HGT applied' shots/g261.log)
G261RAISED=$(echo "${G261HIGH:--9}" | awk '{print ($1 >= 0.5) ? 1 : 0}')
if [ "$GRC" = "0" ] && [ "${G261N:-0}" = "5" ] && [ "${G261BAD:-1}" = "0" ] \
   && [ "${G261PLAT:-0}" -ge 1 ] && [ "$G261RAISED" = "1" ]; then
  ok "G261 the pointer meets the ground on a raised user map: USER92's own heights applied (the Yard stands ${G261HIGH} cell above the datum), and aimed at each object the ray meets the ground under it (off its ground plane by $G261PG) and the pointer lands on it ($G261GAPS cells from its centre, the first before any frame is drawn; a soldier drawn ${G261TALL} cell tall may read up to 0.65 of that). Before the fix the Mammoth read 0.84"
else
  bad "G261 the pointer meets the ground on a raised user map: rc=$GRC readings=${G261N:-0}(want 5) over-limit=${G261BAD:-none}(want 0) heights-applied=${G261PLAT:-0} yard-height=${G261HIGH:-none}(>=0.5) raygap [$G261GAPS] planegap(<=0.05) [$G261PG] soldier-height(raygap<=0.65x) [${G261TALL:-none}]"
fi

# =====================================================================================
# G262 THE TEST INFANTRY E1TR (idata.cpp E1TR, cnc_eyes.cpp m3inf_tick / m3inf_draw_as).
# The brain has a copy of the minigunner under its own name. It was written for the
# experimental set's E1TR.c3m, the first model with the full set of infantry states.
# That look is retired (its switch is forced off) and E1TR.c3m with it; in Enhanced the
# test type now wears the remastered Minigunner (einf/E1.c3m), which carries the same
# full set of states. The claims below are made of that model; the one that was about
# E1TR.c3m's own file is gone (see (7)).
#
# THE CLAIMS:
#   (1) THE BRAIN FIELDS IT. USER92 places three, and with the remastered row off, where
#       the dump names the model type the brain gave each man, all three read E1TR while
#       every other minigunner stays E1: the clone is its own type, not a relabel.
#   (2) ENHANCED DRAWS IT AS THE MINIGUNNER. The remastered E1 loads skinned with at
#       least 20 clips, the three are posed from it (M3INF2 type=E1 on the same ids), and
#       with the remastered row off none is drawn (the sprite takes them back).
#   (3) IT MOVES LIKE A MODEL. Ordered across the map it runs, at headings between the
#       engine's 45 degree steps, and stands again when it arrives.
#   (4) IT STANDS ABOUT LIKE A PERSON. Left alone it plays at least one of its fidgets.
#   (5) THE GROUND WAR IS THE MODEL'S. Beside six Nod riflemen (a copy of USER92 made
#       here, not the shipped map), the Minigunner model is seen lying down, prone, firing prone and dying,
#       each from a clip of its own (clip= is never "-"), and a body outlives the engine
#       object (M3CORPSE detached) and is gone when its time is up.
#   (6) TWO RUNS OF THE FIGHT ARE ONE PICTURE.
#   (7) RETIRED: LEVELS OF DETAIL. E1TR.c3m carried two coarser levels and this claim
#       proved all three test soldiers drew from the coarsest at the default camera. The
#       remastered soldiers carry no levels of detail, so there is nothing left to
#       measure.
#   (8) A SOLDIER FIRES THE WAY THE ENGINE FACES HIM. In the fight, at least 80% of the
#       per-tick samples of a firing soldier have his drawn heading within 30 degrees of
#       the engine's facing (the rest are the first ticks of a turn). When the target
#       cell was decoded with the wrong row stride this was 34%: soldiers aimed away.
#   (9) THE SIDES DRESS APART. The six Nod riflemen of the fight are drawn in Nod's cloth
#       colour over the uniform's paint (M3DUMP infcloth counts soldiers drawn so; GDI's
#       cloth amount is zero, so a GDI soldier is never counted): at some tick all six.
#  (10) NO IDLE SPIN. A soldier who stands the whole run (every sample a standing Do: stand
#       ready or guard, idle 1 and 2, on guard, the salutes and gestures) is turned now
#       and then by the engine's idle routine, which sets his facing to a random compass
#       point; the model keeps its heading instead. Over those soldiers the engine's
#       facing changes at least three times and the model's heading does not move.
#  (11) THE ENGINE PICKS THE FIDGET. Every sample of a Minigunner model (E1, E1TR, both with
#       idle2..idle7) fidgeting while the engine has him in one of its own fidget Dos plays
#       that Do's clip: IDLE1/2 idle2/idle3, GESTURE1/2 idle4/idle5, SALUTE1/2
#       idle6/idle7; none plays another, and at least one gesture or salute is seen, so
#       the check examined the part that was new. (m3inf_engine_fidget; before it, the
#       clip was the soldier's id and the engine's gestures were drawn as standing.)
# =====================================================================================
cat > /tmp/g262.txt <<'G262EOF'
cam 29 33
tick 20
shot shots/g262_on.png
m3dump
lclickobj E1 9
tick 1
order 25 31
G262EOF
i=0; while [ $i -lt 40 ]; do printf 'tick 2\nm3dump\n' >> /tmp/g262.txt; i=$((i+1)); done
i=0; while [ $i -lt 100 ]; do printf 'tick 3\nm3dump\n' >> /tmp/g262.txt; i=$((i+1)); done
# the remastered row off: the sprite takes the soldiers back, and the dump names the
# model type the brain gave each man, which is where E1TR is seen as its own type
printf 'gfx einf_on 0\nshot shots/g262_off.png\nm3dump\nquit\n' >> /tmp/g262.txt
rm -rf /tmp/g262m && mkdir -p /tmp/g262m
cp missions/user_maps/USER92.INI missions/user_maps/USER92.BIN missions/user_maps/USER92.HGT /tmp/g262m/ 2>/dev/null
python3 - /tmp/g262m/USER92.INI <<'PY'
import sys
p = sys.argv[1]
s = open(p, 'rb').read().decode('latin-1')
nl = '\r\n' if '\r\n' in s else '\n'
old = '011=GoodGuy,E1TR,256,2204,2,Guard,128,None'
# numbered after the last [INFANTRY] entry, whatever the map has grown to since
import re
sec = s[s.index('[INFANTRY]'):]
sec = sec[:sec.find(nl + '[', 1) if sec.find(nl + '[', 1) > 0 else len(sec)]
rows = re.findall(r'^(\d{3})=.*$', sec, re.M)
last = [ln for ln in sec.split(nl) if re.match(r'^\d{3}=', ln)][-1]
first = max(int(r) for r in rows) + 1
add = nl.join('%03d=BadGuy,E1,256,%d,%d,Guard,128,None' % (first + i, 32 * 64 + 27 + i // 3, i % 3 + 1)
              for i in range(6))
if old in s:
    open(p, 'wb').write(s.replace(last, last + nl + add, 1).encode('latin-1'))
PY
cat > /tmp/g262f.txt <<'G262EOF'
cam 28 33
tick 1
G262EOF
i=0; while [ $i -lt 260 ]; do
  printf 'tick 1\nm3dump\n' >> /tmp/g262f.txt
  [ $i = 100 ] && printf 'shot shots/g262_fight.png\n' >> /tmp/g262f.txt
  i=$((i+1))
done
echo quit >> /tmp/g262f.txt
sed 's#g262_fight\.png#g262_fight2.png#' /tmp/g262f.txt > /tmp/g262g.txt
gbegin shots/g262_on.png shots/g262_off.png shots/g262_fight.png shots/g262_fight2.png \
       shots/g262.log shots/g262f.log shots/g262g.log
grun shots/g262.log --reskin --noshroud --scen USER92 --pack SCG01EA.pack $BASE \
     --dir missions/user_maps/ --nosound --w 1280 --h 800 --script /tmp/g262.txt --enhanced
grun shots/g262f.log --reskin --noshroud --scen USER92 --pack SCG01EA.pack $BASE \
     --dir /tmp/g262m/ --nosound --w 1280 --h 800 --script /tmp/g262f.txt --enhanced
grun shots/g262g.log --reskin --noshroud --scen USER92 --pack SCG01EA.pack $BASE \
     --dir /tmp/g262m/ --nosound --w 1280 --h 800 --script /tmp/g262g.txt --enhanced
G262TYPES=$(sed -n 's/^M3INF2|id=\([0-9]*\)|type=E1TR|.*/\1/p' shots/g262.log | sort -u | tr '\n' ' ')
G262NTR=$(echo $G262TYPES | wc -w | tr -d ' ')
# THE SAME MEN, DRAWN AS THE MINIGUNNER: with the remastered row on, each E1TR id is posed
# as type=E1 from a clip of that model. G262IDS is an alternation for grep -E.
G262IDS=$(echo $G262TYPES | tr ' ' '|')
G262AS=$(grep -aE "^M3INF2\|id=(${G262IDS:-none})\|type=E1\|.*\|clip=[a-z0-9]+\|" shots/g262.log \
    | sed -n 's/^M3INF2|id=\([0-9]*\)|.*/\1/p' | sort -u | wc -l | tr -d ' ')
G262CLIPS=$(sed -n 's/^M3E|E1|tris.*|bones \([0-9]*\)|clips \([0-9]*\)$/\2/p' shots/g262.log | head -1)
G262BONES=$(sed -n 's/^M3E|E1|tris.*|bones \([0-9]*\)|clips.*/\1/p' shots/g262.log | head -1)
G262ON=$(sed -n 's/^M3DUMP|.*|inf=\([0-9]*\)|.*/\1/p' shots/g262.log | head -1)
G262OFF=$(sed -n 's/^M3DUMP|.*|inf=\([0-9]*\)|.*/\1/p' shots/g262.log | tail -1)
# THE SOLDIER THE CLICK ACTUALLY SELECTED, not a fixed id. The three E1TR stand
# shoulder to shoulder, and a change in infantry size moves which silhouette covers the
# aim point: at the experimental size of 0.9 the click on the tenth E1 selects id 10, at
# 0.75 it selected id 9. Either is an E1TR ordered across the map, which is the claim.
G262SID=$(sed -n 's/^SELECT|at=.*|type=E1|.*|id=\([0-9]*\)|selected$/\1/p' shots/g262.log | head -1)
G262SID=${G262SID:-9}
G262RUN=$(grep -ac "^M3INF2|id=$G262SID|type=E1|state=run|.*|clip=run|" shots/g262.log)
G262OFFGRID=$(sed -n "s/^M3INF|id=$G262SID|doing=3|.*|yaw=\\([0-9.]*\\)|.*/\\1/p" shots/g262.log \
    | awk '{r = $1 - 45 * int($1 / 45); if (r > 0.5 && r < 44.5) n++} END {print n + 0}')
G262STOOD=$(grep -a "^M3INF2|id=$G262SID|" shots/g262.log | tail -1 | grep -c 'state=\(idle\|fidget\|aim\)')
G262FIDGET=$(grep -acE "^M3INF2\|id=(${G262IDS:-none})\|type=E1\|state=fidget\|.*\|clip=idle[2-7]\|" shots/g262.log)
g262seen() { grep -ac "^M3INF2|id=[0-9]*|type=E1|state=$1|.*|clip=[a-z0-9]*|" shots/g262f.log; }
G262LIE=$(g262seen liedown); G262PRONE=$(g262seen prone); G262FP=$(g262seen fireprone)
G262DIE=$(g262seen die)
G262NOCLIP=$(grep -ac '^M3INF2|id=[0-9]*|type=E1|.*|clip=-|' shots/g262f.log)
G262DET=$(grep -ac '^M3CORPSE|n=[1-9]*|detached=[1-9]' shots/g262f.log)
G262GONE=$(grep -a '^M3CORPSE' shots/g262f.log | tail -1)
G262SAME=$(cmp -s shots/g262_fight.png shots/g262_fight2.png && echo 1 || echo 0)
G262AIMOK=$(grep -a '^M3INF|' shots/g262f.log | awk -F'|' '{split($3,d,"="); split($4,f,"="); split($5,y,"=");
    if (d[2] == 4 && f[2] >= 0) { e = y[2] - f[2]; while (e > 180) e -= 360; while (e < -180) e += 360;
    if (e < 0) e = -e; n++; if (e <= 30) ok++ } } END { print (n ? int(100 * ok / n) : 0) }')
G262SPIN=$(grep -a '^M3INF|' shots/g262.log | awk -F'|' '{split($2,i,"="); split($3,d,"="); split($4,f,"="); split($5,y,"=");
    id=i[2]; n[id]++; if (d[2] !~ /^(0|1|9|10|11|27|28|29|30)$/) moved[id]=1;
    if (n[id] > 1 && f[2] != lf[id]) turns[id]++; lf[id]=f[2];
    if (!(id in lo) || y[2] < lo[id]) lo[id]=y[2]; if (!(id in hi) || y[2] > hi[id]) hi[id]=y[2] }
    END { t=0; r=0; for (id in n) if (!(id in moved)) { t+=turns[id]; if (hi[id]-lo[id] > r) r=hi[id]-lo[id] }
          printf "%d %.1f", t, r }')
G262SPINT=${G262SPIN% *}; G262SPINR=${G262SPIN#* }
G262CLOTH=$(sed -n 's/^M3DUMP|.*|infcloth=\([0-9]*\)|.*/\1/p' shots/g262f.log | sort -n | tail -1)
G262PICK=$(cat shots/g262.log shots/g262f.log | grep -a '^M3INF2|id=[0-9]*|type=E1\(TR\)\{0,1\}|state=fidget|' \
    | awk -F'|' '{split($7,c,"="); split($9,d,"="); want = "";
        if (d[2] == 9) want = "idle2"; if (d[2] == 10) want = "idle3"; if (d[2] == 27) want = "idle4";
        if (d[2] == 29) want = "idle5"; if (d[2] == 28) want = "idle6"; if (d[2] == 30) want = "idle7";
        if (want == "") next; if (c[2] == want) { ok++; if (d[2] >= 27) g++ } else bad++ }
        END { printf "%d %d %d", ok + 0, bad + 0, g + 0 }')
G262PICKOK=$(echo $G262PICK | cut -d' ' -f1); G262PICKBAD=$(echo $G262PICK | cut -d' ' -f2)
G262PICKG=$(echo $G262PICK | cut -d' ' -f3)
if [ "$GRC" = "0" ] && [ "$G262NTR" = "3" ] && [ "${G262AS:-0}" = "3" ] && [ "${G262BONES:-0}" -gt 0 ] \
   && [ "${G262CLIPS:-0}" -ge 20 ] && [ "${G262ON:-0}" -ge 12 ] && [ "${G262OFF:-x}" = "0" ] \
   && [ "${G262RUN:-0}" -gt 0 ] && [ "${G262OFFGRID:-0}" -gt 0 ] && [ "${G262STOOD:-0}" = "1" ] \
   && [ "${G262FIDGET:-0}" -gt 0 ] && [ "${G262LIE:-0}" -gt 0 ] && [ "${G262PRONE:-0}" -gt 0 ] \
   && [ "${G262FP:-0}" -gt 0 ] && [ "${G262DIE:-0}" -gt 0 ] && [ "${G262DET:-0}" -gt 0 ] \
   && [ "$G262SAME" = "1" ] && [ "${G262AIMOK:-0}" -ge 80 ] \
   && [ "${G262CLOTH:-0}" -ge 6 ] && [ "${G262SPINT:-0}" -ge 3 ] \
   && [ "$(echo "${G262SPINR:-99} <= 0.5" | bc)" = "1" ] \
   && [ "${G262PICKG:-0}" -gt 0 ] && [ "${G262PICKBAD:-1}" = "0" ]; then
  ok "G262 the test infantry E1TR: the brain fields $G262NTR on USER92 (ids $G262TYPES) beside the E1 minigunners, and Enhanced draws all $G262AS as the remastered Minigunner ($G262BONES bones, $G262CLIPS clips), the sprite with its row off. Ordered, it runs ($G262RUN samples, $G262OFFGRID off the 45 degree grid) and stands again; left alone it fidgets ($G262FIDGET samples). Under fire the model lies down ($G262LIE), lies ($G262PRONE), fires prone ($G262FP) and dies ($G262DIE) from its own clips, the body outlives the engine object ($G262DET samples) and is then gone ($G262GONE). Two runs of the fight are one picture. Firing, $G262AIMOK% of samples face within 30 degrees of the engine. Up to $G262CLOTH Nod riflemen drawn in Nod's cloth at once. Standing soldiers: the engine turned them $G262SPINT times, their models' headings moved ${G262SPINR} degrees. The engine's own fidgets play their own clips: $G262PICKOK samples, $G262PICKG of them gestures or salutes, none wrong"
else
  bad "G262 the test infantry E1TR: rc=$GRC e1tr=${G262NTR:-0}(3) drawn-as-minigunner=${G262AS:-0}(3) bones=${G262BONES:-none}(>0) clips=${G262CLIPS:-none}(>=20) drawn-on=${G262ON:-none}(>=12) drawn-off=${G262OFF:-none}(0) run=${G262RUN:-0}(>0) off-grid=${G262OFFGRID:-0}(>0) stood=${G262STOOD:-0}(1) fidget=${G262FIDGET:-0}(>0) liedown=${G262LIE:-0} prone=${G262PRONE:-0} fireprone=${G262FP:-0} die=${G262DIE:-0}(all >0) states-without-clip=${G262NOCLIP:-?} detached-body=${G262DET:-0}(>0) same-picture=$G262SAME(1) firing-heading-within-30deg=${G262AIMOK:-0}%(>=80) nod-cloth=${G262CLOTH:-none}(>=6) idle-engine-turns=${G262SPINT:-none}(>=3) idle-model-heading-range=${G262SPINR:-none}(<=0.5) engine-fidget-clips=${G262PICKOK:-0}ok/${G262PICKBAD:-?}wrong(0)/${G262PICKG:-0}gestures(>0)"
fi

# =====================================================================================
# G263 FREE INFANTRY MOVEMENT (brain OpenCNC3D_FreeInfantry, renderer freeinf_tick): RETIRED
# WITH THE EXPERIMENTAL LOOK. It proved that with the rule on, a walking soldier's engine
# facing left the 45 degree grid (he walked at any angle along a straight line through
# enterable cells), that the rule's own row and Classic kept the 1995 eight-direction
# walk, and that two runs gave the same facings. freeinf_tick sends the rule to the brain
# only under the experimental switch, so every soldier now walks the 1995 way.
# NOTHING RUNS HERE. Its subject is drawn only under the experimental look, whose switch
# is now forced off (fx_state.h: a preset that still carries it is read as off, and a
# script that sets it fails as an unknown dial). No run can reach the feature, so every
# arm could only fail its script or measure a picture the feature is absent from.
# The number stays so the history reads straight; the code and art are left in the tree.
# NOTHING REPLACED IT. The brain's rule (OpenCNC3D_FreeInfantry) is still in the patch set
# and is simply never switched on.

# =====================================================================================
# G264 THE UNITY EXPLOSIONS (unityvfx_mod.h): RETIRED WITH THE EXPERIMENTAL LOOK. It
# proved that each of the engine's 13 explosion types drew its chosen Vefects prefab
# (game/vfx3d/claims.txt), that one explosion matched Unity's own post-processed frames
# (tools/art/unity_vfx/ref/) to a mean of a level, that shell hits in SCG01EA's fight were
# claimed and moved onto the surface they hit, that the grenade and the rocket hit drew
# their own picks, and that --nouvfx and Classic claimed none. uvfx_on draws only under
# the experimental switch.
# NOTHING RUNS HERE. Its subject is drawn only under the experimental look, whose switch
# is now forced off (fx_state.h: a preset that still carries it is read as off, and a
# script that sets it fails as an unknown dial). No run can reach the feature, so every
# arm could only fail its script or measure a picture the feature is absent from.
# The number stays so the history reads straight; the code and art are left in the tree.
# WHAT REPLACED IT is Enhanced's remastered effects (efx_enh.pack, effects_mod.h and
# efx_enhanced.h), which G293 proves.

# =====================================================================================
# G265 THE GDI ROCKETEER (game/einf/E3.c3m, cnc_eyes.cpp m3inf_tick). Read from G262's
# runs, so it costs no run of its own. It was written for the experimental set's E3.c3m,
# the rifleman's body carrying a borrowed launcher, whose shoot clip was played WHOLE and
# held for 25 ticks or more past the engine's fire. That look is retired (its switch is
# forced off) and its model is never drawn; it still loads, so this gate went on reading
# its load line and reporting a model nobody sees. Under Enhanced the Rocket
# Soldier is the remastered set's own E3, and that model's shot follows the engine: its
# shoot clip loops and is played on the engine's fire stages, so the launch lands on the
# stage the 1995 sprite fires on. The claims below are made of that model.
#
# THE CLAIMS:
#   (1) IT IS THE REMASTERED SET'S SKINNED MODEL: M3E|E3 loads with bones and at least 20
#       clips. (The levels-of-detail claim is retired as G262's (7) is: the remastered
#       soldiers carry none.)
#   (2) USER92 FIELDS FOUR, all drawn from it (every E3 state has its clip, never "-").
#   (3) IT AIMS AND FIRES ON THE ENGINE'S STAGES. In G262's firefight an E3 aims, and is
#       seen in the shoot state, and EVERY shoot sample falls on a tick the engine has him
#       in DO_FIRE_WEAPON (doing=4); the model's shoot clip carries the loop flag, which
#       is what keeps m3inf_tick from holding it past the engine's fire. A shot played
#       whole and held, as the retired model's was, shows as shoot samples at another Do.
#   (4) THE HOLD IS VISIBLE TO THIS DUMP, so (3) is not true by construction: the once
#       clip m3inf_tick does hold, the lie-down, is seen carried on into the engine's
#       prone or prone fire (doing=2 or 8) in the same fight.
# =====================================================================================
G265CLIPS=$(sed -n 's/^M3E|E3|tris.*|bones \([0-9]*\)|clips \([0-9]*\)$/\2/p' shots/g262.log | head -1)
G265BONES=$(sed -n 's/^M3E|E3|tris.*|bones \([0-9]*\)|clips.*/\1/p' shots/g262.log | head -1)
G265LOOP=$(grep -a '^M3E|E3|clip shoot|' shots/g262.log | head -1 | grep -c '|loop$')
G265IDS=$(sed -n 's/^M3INF2|id=\([0-9]*\)|type=E3|.*/\1/p' shots/g262.log | sort -u | wc -l | tr -d ' ')
G265NOCLIP=$(grep -ac '^M3INF2|id=[0-9]*|type=E3|.*|clip=-|' shots/g262.log)
G265AIM=$(grep -ac '^M3INF2|id=[0-9]*|type=E3|state=aim|.*|clip=aim|' shots/g262f.log)
G265SHOT=$(grep -ac '^M3INF2|id=[0-9]*|type=E3|state=shoot|.*|clip=shoot|' shots/g262f.log)
G265OFF=$(grep -a '^M3INF2|id=[0-9]*|type=E3|state=shoot|' shots/g262f.log | grep -vc '|doing=4$')
G265HELD=$(grep -a '^M3INF2|id=[0-9]*|type=E3|state=liedown|' shots/g262f.log | grep -c '|doing=[28]$')
if [ "${G265BONES:-0}" -gt 0 ] && [ "${G265CLIPS:-0}" -ge 20 ] && [ "${G265LOOP:-0}" = "1" ] \
   && [ "${G265IDS:-0}" = "4" ] && [ "${G265NOCLIP:-1}" = "0" ] \
   && [ "${G265AIM:-0}" -gt 0 ] && [ "${G265SHOT:-0}" -gt 0 ] && [ "${G265OFF:-1}" = "0" ] \
   && [ "${G265HELD:-0}" -gt 0 ]; then
  ok "G265 the GDI rocketeer: E3 is the remastered set's skinned model ($G265BONES bones, $G265CLIPS clips, its shoot clip a loop), USER92 fields $G265IDS all drawn from it, and in the firefight it aims ($G265AIM samples) and fires on the engine's own fire action ($G265SHOT shoot samples, none outside DO_FIRE_WEAPON), where the dump does show a held clip ($G265HELD lie-down samples carried into the engine's prone)"
else
  bad "G265 the GDI rocketeer: bones=${G265BONES:-none}(>0) clips=${G265CLIPS:-none}(>=20) shoot-clip-loops=${G265LOOP:-0}(1) e3=${G265IDS:-0}(4) states-without-clip=${G265NOCLIP:-?}(0) aim=${G265AIM:-0}(>0) shoot=${G265SHOT:-0}(>0) shoot-outside-the-engine-fire=${G265OFF:-?}(0) held-liedown-control=${G265HELD:-0}(>0)"
fi

# G266 THE GREEN POINTER (cursor3d_mod.h; tools/art/cursor_green.py): RETIRED WITH THE
